INSERT INTO modules (part_number, title, slug, description, badge_name, badge_icon, order_index) VALUES (1, 'Pengenalan Python & Tipe Data', 'pengenalan-python', 'Memahami cara kerja Python, sintaks dasar print, komentar, variabel, dan tipe data primitif.', 'Python Novice', 'fa-seedling', 1);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (1, 1, '1.1', '1.1 Cara Kerja Python & Fungsi print()', '1-1-cara-kerja-print', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Pengeras Suara Restoran\n        </div>\n        <p>Bayangkan Anda bekerja di restoran cepat saji. Dapur memasak makanan, dan ada pelayan yang mengumumkan ke pengeras suara: <em>\"Pesanan nomor 25 sudah siap!\"</em>. Fungsi <code>print()</code> di Python bekerja persis seperti pengeras suara tersebut. Tanpa <code>print()</code>, komputer bisa memproses miliaran data di memorinya, tetapi Anda tidak akan pernah melihat hasil akhirnya di layar!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Konsep Inti &amp; Cara Kerja Interpreter\n        </h4>\n        <p>Python adalah <strong>Interpreted Language</strong>. Artinya, program dibaca dan dieksekusi <em>baris per baris</em> dari atas ke bawah. Saat Python membaca baris <code>print(...)</code>:</p>\n        <ol class=\"list-decimal pl-5 space-y-1 mt-2 text-slate-600\">\n            <li>Interpreter mengevaluasi apa pun yang ada di dalam tanda kurung <code>( )</code>.</li>\n            <li>Jika berupa teks dalam tanda kutip, Python mencetaknya apa adanya.</li>\n            <li>Jika berupa ekspresi matematika (misal <code>10 + 5</code>), Python menghitungnya dulu (menjadi <code>15</code>), baru mencetak hasilnya.</li>\n            <li>Setelah mencetak, Python secara otomatis berpindah ke baris baru (newline <code>\\n</code>).</li>\n        </ol>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Mencetak teks string (wajib pakai tanda kutip)\nprint(\"Selamat Datang di Akademi Python SMK!\")\n\n# Mencetak angka matematika (tanpa tanda kutip)\nprint(100)\n\n# Mencetak hasil kalkulasi\nprint(25 + 75)\n\n# Mencetak banyak data sekaligus dipisahkan koma\nprint(\"Tahun:\", 2026, \"- Status: Aktif\")</code></pre>\n        <p class=\"text-[11px] text-slate-500 mt-1\"><strong>Keluaran terminal:</strong><br>Selamat Datang di Akademi Python SMK!<br>100<br>100<br>Tahun: 2026 - Status: Aktif</p>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error Pemula (Common Mistakes)\n        </div>\n        <ul class=\"list-disc pl-5 space-y-1.5 text-slate-700\">\n            <li><strong>SyntaxError (Lupa Tanda Kurung / Kutip):</strong> Di Python 3, <code>print \"Halo\"</code> akan error. Wajib menulis <code>print(\"Halo\")</code>.</li>\n            <li><strong>NameError (Teks Tanpa Kutip):</strong> Menulis <code>print(Halo)</code> tanpa kutip akan membuat Python mengira <em>Halo</em> adalah variabel yang belum pernah dibuat.</li>\n            <li><strong>Huruf Besar-Kecil (Case Sensitivity):</strong> Menulis <code>Print()</code> atau <code>PRINT()</code> akan menghasilkan <code>NameError</code> karena Python hanya mengenali huruf kecil <code>print()</code>.</li>\n        </ul>\n    </div>\n\n    <div class=\"p-4 bg-emerald-50/80 border-l-4 border-emerald-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-emerald-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-mobile-screen-button text-emerald-600\"></i> 5. Tips Cepat Mengetik di HP\n        </div>\n        <p>Gunakan tombol pintasan simbol <code>\" \"</code> dan <code>( )</code> yang ada di atas keyboard emulator HP Anda. Satu ketukan tombol pintas langsung membuat sepasang tanda kurung dan menempatkan kursor di tengahnya!</p>\n    </div>\n</div>', 'print(\"Halo, saya sedang belajar Python!\")\nprint(10 + 25)', 1, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (1, 'Mengapa Python dikategorikan sebagai \"Interpreted Language\" dan apa fungsi utama print()?', 'Karena kodenya dikonversi ke file exe sebelum jalan; print() untuk menghapus data', 'Karena kodenya dibaca dan dijalankan baris demi baris oleh interpreter; print() untuk menampilkan data ke layar output', 'Karena Python hanya bisa dijalankan di peramban web tanpa mesin interpreter', 'Karena print() otomatis menghentikan komputer setelah dieksekusi', 'B', 'Python adalah bahasa interpretasi yang membaca baris kode secara berurutan. Fungsi print() bertugas mengirimkan teks atau hasil kalkulasi ke terminal output.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (1, 'Perhatikan potongan kode berikut:\nprint(10 + 5)\nprint(\"10 + 5\")\nBerapakah output yang dihasilkan di layar terminal?', '15 lalu baris kedua 15', '10 + 5 lalu baris kedua 10 + 5', '15 lalu baris kedua 10 + 5', 'Terjadi SyntaxError karena teks dan angka dicampur', 'C', 'Baris pertama tanpa tanda kutip dihitung sebagai operasi matematika (10+5=15). Baris kedua diapit tanda kutip sehingga dicetak apa adanya sebagai teks (\"10 + 5\").', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (1, 'Seorang siswa menulis kode:\nPrint(\"Halo Dunia\")\nSaat dijalankan muncul error NameError: name \"Print\" is not defined. Mengapa error ini terjadi?', 'Tanda kutip harus diganti kutip tunggal', 'Python bersifat case-sensitive, fungsi resmi adalah print huruf kecil bukan Print huruf kapital', 'Kata \"Halo Dunia\" dilarang di Python', 'Kurang menambahkan titik koma (;) di akhir baris', 'B', 'Python membedakan huruf besar dan kecil (case-sensitive). Perintah bawaan Python adalah print() seluruhnya menggunakan huruf kecil.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (1, 'Tantangan 1.1: Mencetak Kalimat Sambutan', 'Cetaklah tepat teks berikut:\nSaya Siap Belajar Python', 'print(\"\")', '[{\"name\": \"Cek Kalimat Sambutan\", \"expected_output\": \"Saya Siap Belajar Python\"}]', 'Gunakan print(\"Saya Siap Belajar Python\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (2, 1, '1.2', '1.2 Komentar (#) & Dokumentasi Kode', '1-2-komentar-dokumentasi', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Catatan Kertas Sticky Note\n        </div>\n        <p>Bayangkan Anda menempelkan kertas sticky note di kulkas: <em>\"Beli susu sebelum jam 5 sore\"</em>. Pesan itu hanya untuk dibaca manusia, kulkas Anda tidak akan melakukan apa pun dengan catatan tersebut. Di dunia pemrograman, itulah fungsi <strong>Komentar</strong>. Komentar adalah catatan untuk programmer lain atau diri Anda sendiri di masa depan yang sepenuhnya diabaikan oleh komputer.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Konsep Inti &amp; Cara Kerja Eksekusi\n        </h4>\n        <p>Ketika interpreter Python mendeteksi karakter pagar <code>#</code> di sebuah baris:</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-2 text-slate-600\">\n            <li>Seluruh karakter setelah tanda <code>#</code> hingga akhir baris tersebut akan <strong>dilewati 100%</strong>.</li>\n            <li>Komentar tidak memakai memori dan tidak memperlambat kecepatan eksekusi program.</li>\n            <li>Bisa diletakkan di baris tersendiri (Full Line) atau di samping kanan kode yang sedang aktif (Inline).</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Program: Menghitung Keliling Persegi\n# Dibuat oleh: Fadhil (X PPLG 1)\n\nsisi = 10 # Satuan dalam centimeter\nkeliling = 4 * sisi # Rumus: 4 x sisi\n\n# Cetak hasil ke layar\nprint(\"Keliling persegi:\", keliling)\n\n# print(\"Baris ini dinonaktifkan sementara saat debugging\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error Pemula\n        </div>\n        <p>Kesalahan umum adalah lupa bahwa tanda <code>#</code> di dalam string teks (diapit tanda kutip) <strong>TIDAK BERLAKU</strong> sebagai komentar!</p>\n        <pre class=\"bg-slate-900 text-slate-100 p-2.5 rounded-xl text-xs font-mono my-1.5\"><code>print(\"Ini tanda # bukan komentar\") # Ini baru komentar!</code></pre>\n        <p class=\"text-slate-600\">Tanda <code>#</code> di dalam kutip akan ikut dicetak ke layar sebagai teks biasa.</p>\n    </div>\n\n    <div class=\"p-4 bg-emerald-50/80 border-l-4 border-emerald-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-emerald-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-mobile-screen-button text-emerald-600\"></i> 5. Tips Cepat Mengetik di HP\n        </div>\n        <p>Gunakan tombol pintasan simbol <code>#</code> di HP Toolbar agar Anda tidak perlu membuka layer menu simbol pada papan ketik Android/iOS saat ingin membuat catatan kode.</p>\n    </div>\n</div>', '# Program perkenalan diri\n# Dibuat oleh Siswa Hebat\nprint(\"Program dimulai\")\n# print(\"Baris ini dinonaktifkan\")\nprint(\"Program selesai\")', 2, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (2, 'Karakter apakah yang digunakan di Python untuk menandai baris komentar?', '// (Garis miring ganda)', '/* */ (Bintang slash)', '# (Tanda pagar / hash)', '-- (Tanda minus ganda)', 'C', 'Di Python, komentar satu baris selalu diawali dengan karakter pagar (#). Simbol // di Python adalah pembagian bulat (floor division).', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (2, 'Perhatikan potongan kode berikut:\n# print(\"A\")\nprint(\"B\") # print(\"C\")\n# print(\"D\")\nHuruf apa sajakah yang akan muncul di layar saat kode dijalankan?', 'A, B, C, D', 'Hanya B', 'B dan C', 'Tidak ada huruf yang dicetak', 'B', 'Baris print(\"A\") dan print(\"D\") berada di baris komentar. Bagian print(\"C\") berada di sebelah kanan tanda # sehingga diabaikan. Hanya print(\"B\") yang dieksekusi.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (2, 'Manakah pernyataan yang BENAR mengenai sifat komentar di Python?', 'Komentar membuat eksekusi program menjadi jauh lebih lambat karena interpreter harus membaca semuanya', 'Komentar wajib ditulis di setiap baris kode agar program bisa berjalan tanpa error', 'Tanda # di dalam kutip seperti print(\"#1\") akan dianggap komentar dan tidak dicetak', 'Komentar diabaikan oleh interpreter dan sangat berguna untuk mendokumentasikan alur logika kode bagi manusia', 'D', 'Komentar murni untuk kemudahan membaca kode bagi manusia dan tidak mempengaruhi kinerja maupun logika program.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (2, 'Tantangan 1.2: Baris Kode Bersih dengan Komentar', 'Tuliskan satu baris komentar di baris pertama, kemudian di baris kedua cetak teks:\nKODE BERHASIL DIJALANKAN', '# Tulis komentar di sini\n', '[{\"name\": \"Cek Output Teks\", \"expected_output\": \"KODE BERHASIL DIJALANKAN\"}]', 'Awali baris 1 dengan tanda #, lalu di baris 2 tulis print(\"KODE BERHASIL DIJALANKAN\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (3, 1, '1.3', '1.3 Variabel & Aturan Penamaan', '1-3-variabel-aturan-penamaan', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Kotak Kardus Berlabel\n        </div>\n        <p>Bayangkan Anda memiliki beberapa kotak kardus di gudang. Agar tidak tertukar, Anda menempelkan stiker label: satu kotak diberi label <code>nama_siswa</code> berisi kertas bertuliskan \"Ahmad\", kotak lain berlabel <code>umur</code> berisi angka \"16\". Variabel adalah kotak kardus tersebut yang bertugas menyimpan nilai di memori RAM komputer.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Konsep Inti &amp; Operator Penugasan (=)\n        </h4>\n        <p>Di Python, tanda sama dengan <code>=</code> bukanlah \"sama dengan\" dalam matematika, melainkan <strong>Assignment Operator (Penugasan)</strong>. Nilai di sebelah kanan akan disimpan ke dalam variabel di sebelah kiri.</p>\n        <p class=\"mt-1 font-bold text-slate-800\">Aturan Resmi Penamaan Variabel (PEP 8 snake_case):</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-1 text-slate-600\">\n            <li>Hanya boleh menggunakan huruf (a-z, A-Z), angka (0-9), dan garis bawah (<code>_</code>).</li>\n            <li><strong>DILARANG</strong> diawali dengan angka (contoh terlarang: <code>1nama</code>, <code>2data</code>).</li>\n            <li><strong>DILARANG</strong> menggunakan spasi atau tanda minus/hubung (contoh terlarang: <code>nama siswa</code>, <code>nama-siswa</code>).</li>\n            <li><strong>DILARANG</strong> menggunakan kata kunci cadangan Python (Reserved Keywords seperti <code>print</code>, <code>if</code>, <code>class</code>).</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Penamaan snake_case standar Python\nnama_lengkap = \"Ahmad Fadhil\"\nskor_ujian = 95\nstatus_lulus = True\n\n# Menampilkan isi variabel\nprint(\"Nama Siswa:\", nama_lengkap)\nprint(\"Skor:\", skor_ujian)\n\n# Mengubah isi variabel (re-assign)\nskor_ujian = 100\nprint(\"Skor Remedial:\", skor_ujian)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error Pemula\n        </div>\n        <p>Banyak pemula menulis kode terbalik, meletakkan nilai di sebelah kiri dan variabel di sebelah kanan:</p>\n        <pre class=\"bg-slate-900 text-slate-100 p-2.5 rounded-xl text-xs font-mono my-1.5\"><code># SALAH (SyntaxError: cannot assign to literal)\n100 = skor\n\n# BENAR:\nskor = 100</code></pre>\n        <p class=\"text-slate-600\">Ingat kaidah: <strong>VARIABEL = NILAI</strong> (Variabel selalu di sebelah kiri!).</p>\n    </div>\n\n    <div class=\"p-4 bg-emerald-50/80 border-l-4 border-emerald-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-emerald-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-mobile-screen-button text-emerald-600\"></i> 5. Tips Cepat Mengetik di HP\n        </div>\n        <p>Gunakan tombol pintasan simbol <code>=</code> pada toolbar atas editor untuk menghemat waktu penulisan penugasan variabel tanpa membuka simbol kedua keyboard HP.</p>\n    </div>\n</div>', '# Penamaan variabel yang benar\nnama_depan = \"Ahmad\"\nnama_belakang = \"Fadhil\"\numur = 16\n\nprint(nama_depan, nama_belakang, \"berumur\", umur)', 3, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (3, 'Manakah nama variabel berikut yang SAH dan mengikuti konvensi snake_case di Python?', '1_skor_maksimal', 'skor-maksimal', 'skor_maksimal', 'skor maksimal', 'C', 'skor_maksimal sah karena menggunakan huruf kecil, pemisah garis bawah (_), tidak diawali angka, dan tidak memakai spasi atau tanda hubung (-).', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (3, 'Perhatikan potongan kode berikut:\nx = 5\nx = x + 10\nprint(x)\nBerapakah output dari variabel x?', '5', '10', '15', 'Error', 'C', 'Nilai awal x adalah 5. Baris kedua mengevaluasi sisi kanan: 5 + 10 = 15, lalu menyimpannya kembali ke variabel x.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (3, 'Seorang siswa menulis kode: nilai siswa = 90. Pesan error apakah yang akan dimunculkan oleh Python?', 'NameError karena nama siswa belum terdaftar', 'SyntaxError: invalid syntax karena nama variabel tidak boleh mengandung spasi', 'TypeError karena 90 bukan teks', 'ZeroDivisionError', 'B', 'Python tidak mengizinkan spasi pada penamaan variabel. Spasi dianggap sebagai dua token kata terpisah sehingga memicu SyntaxError.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (3, 'Tantangan 1.3: Debugging Penamaan Variabel', 'Perbaiki kode yang salah sintaks berikut agar variabel bernama skor_maksimal memiliki nilai 100 dan dicetak:\nOutput yang diharapkan:\nSkor: 100', '# Perbaiki baris di bawah:\n# 1_skor = 100\n# print(\"Skor:\", 1_skor)\n', '[{\"name\": \"Cek Variabel Valid\", \"expected_output\": \"Skor: 100\"}]', 'Ganti 1_skor menjadi skor_maksimal = 100 lalu print(\"Skor:\", skor_maksimal)', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (4, 1, '1.4', '1.4 Tipe Data Primitif & Fungsi type()', '1-4-tipe-data-primitif', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Wadah Minuman &amp; Makanan\n        </div>\n        <p>Anda tidak bisa menuangkan kuah bakso panas ke dalam kantong plastik tipis tanpa bocor, dan Anda tidak bisa memotong daging dengan sedotan es. Setiap benda memiliki wadah dan perlakuannya sendiri. Di Python, komputer perlu mengetahui <strong>Tipe Data</strong> agar tahu operasi apa yang bisa dilakukan terhadap data tersebut.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Mengenal 4 Tipe Data Primitif Utama\n        </h4>\n        <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left text-xs border border-slate-200 rounded-xl overflow-hidden\">\n                <thead class=\"bg-slate-100 text-slate-700 font-bold\">\n                    <tr><th class=\"p-2.5\">Tipe Data</th><th class=\"p-2.5\">Keterangan</th><th class=\"p-2.5\">Contoh di Python</th></tr>\n                </thead>\n                <tbody class=\"divide-y divide-slate-100\">\n                    <tr><td class=\"p-2.5 font-bold font-mono text-blue-600\">str (String)</td><td class=\"p-2.5\">Teks dalam tanda kutip</td><td class=\"p-2.5 font-mono\">\"Wikrama\", \'Ahmad\'</td></tr>\n                    <tr><td class=\"p-2.5 font-bold font-mono text-emerald-600\">int (Integer)</td><td class=\"p-2.5\">Bilangan bulat tanpa desimal</td><td class=\"p-2.5 font-mono\">16, 2026, -5</td></tr>\n                    <tr><td class=\"p-2.5 font-bold font-mono text-amber-600\">float</td><td class=\"p-2.5\">Bilangan desimal (pecahan titik)</td><td class=\"p-2.5 font-mono\">3.14, 85.5, -0.5</td></tr>\n                    <tr><td class=\"p-2.5 font-bold font-mono text-purple-600\">bool (Boolean)</td><td class=\"p-2.5\">Kebenaran logika (True / False)</td><td class=\"p-2.5 font-mono\">True, False</td></tr>\n                </tbody>\n            </table>\n        </div>\n        <p class=\"mt-2 text-slate-600\">Gunakan fungsi bawaan <code>type(variabel)</code> untuk mengecek jenis tipe data variabel kapan saja.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>nama = \"Inda\"      # string (str)\nusia = 17           # integer (int)\ntinggi = 172.5      # float\npunya_ktp = False   # boolean (bool)\n\nprint(type(nama))      # <class \'str\'>\nprint(type(usia))      # <class \'int\'>\nprint(type(tinggi))    # <class \'float\'>\nprint(type(punya_ktp)) # <class \'bool\'></code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error Pemula\n        </div>\n        <p>Perbedaan tanda desimal: Di Indonesia kita biasa memakai koma (misal: <code>3,5</code>). Di Python, tanda koma akan membuat Python mengira itu adalah dua nilai (Tuple). Tanda desimal resmi di Python adalah <strong>TITIK</strong> (<code>3.5</code>)!</p>\n    </div>\n\n    <div class=\"p-4 bg-emerald-50/80 border-l-4 border-emerald-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-emerald-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-mobile-screen-button text-emerald-600\"></i> 5. Tips Cepat Mengetik di HP\n        </div>\n        <p>Huruf awal pada nilai Boolean wajib kapital: <code>True</code> dan <code>False</code>. Menulis <code>true</code> huruf kecil akan menyebabkan NameError!</p>\n    </div>\n</div>', 'bilangan_bulat = 42\ndesimal = 3.14\nteks = \"SMK Bisa\"\nstatus = True\n\nprint(type(bilangan_bulat))\nprint(type(desimal))\nprint(type(teks))\nprint(type(status))', 4, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (4, 'Jika variabel a = \"100\" dan variabel b = 100, apakah tipe data dari kedua variabel tersebut secara berurutan?', 'Keduanya adalah int', 'a bertipe str, b bertipe int', 'a bertipe float, b bertipe int', 'Keduanya adalah str', 'B', 'Nilai yang diapit tanda kutip (\"100\") selalu bertipe string (str), sedangkan angka murni tanpa kutip (100) bertipe integer (int).', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (4, 'Berapakah output dari kode berikut:\nx = 7.0\nprint(type(x))', '<class \'int\'>', '<class \'str\'>', '<class \'float\'>', '<class \'number\'>', 'C', 'Meskipun angka di belakang titik adalah nol (.0), adanya tanda titik desimal menandakan tipe data float.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (4, 'Seorang siswa menulis: status_hadir = true. Mengapa kode tersebut memicu NameError: name \"true\" is not defined?', 'Karena Python mewajibkan huruf kapital di awal untuk nilai Boolean: True', 'Karena status_hadir harus diapit tanda kutip', 'Karena Boolean dilarang disimpan di variabel', 'Karena tidak ada titik koma di akhir baris', 'A', 'Konstanta Boolean resmi di Python adalah True dan False (dengan huruf T dan F kapital). Menulis true huruf kecil dianggap nama variabel yang belum didefinisikan.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (4, 'Tantangan 1.4: Cetak 4 Tipe Data', 'Buat 4 baris print yang masing-masing mencetak:\nAngka: 25\nDesimal: 7.5\nTeks: Sukses\nAktif: True', '# Buat 4 perintah print di bawah ini\n', '[{\"name\": \"Cek 4 Baris Tipe Data\", \"expected_output\": \"Angka: 25\nDesimal: 7.5\nTeks: Sukses\nAktif: True\"}]', 'Cetak sesuai label dan nilainya persis di 4 baris terpisah.', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (5, 1, '1.5', '1.5 Boss Challenge: Kartu Biodata Siswa', '1-5-boss-challenge-biodata', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-trophy text-amber-600\"></i> 1. Uji Kompetensi Part 1: Kartu Biodata Mandiri\n        </div>\n        <p>Selamat telah menyelesaikan seluruh materi dasar di Part 1! Sekarang saatnya membuktikan penguasaan Anda: merancang program pembuatan kartu biodata siswa mandiri yang menggabungkan seluruh 4 tipe data primitif, komentar penjelasan, dan pencetakan terformat rapi.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-list-check text-blue-600\"></i> 2. Kriteria &amp; Komponen Wajib Proyek\n        </h4>\n        <ol class=\"list-decimal pl-5 space-y-1.5 text-slate-600\">\n            <li>Membuat variabel <code>nama_siswa</code> bertipe string (str).</li>\n            <li>Membuat variabel <code>umur</code> bertipe integer (int).</li>\n            <li>Membuat variabel <code>nilai_rata_rata</code> bertipe float.</li>\n            <li>Membuat variabel <code>status_aktif</code> bertipe boolean (<code>True</code>).</li>\n            <li>Mencetak kartu biodata berbingkai rapi menggunakan fungsi <code>print()</code>.</li>\n        </ol>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Solusi\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Program Pembuat Kartu Biodata Siswa SMK\n# Dibuat untuk memenuhi Tantangan Boss Part 1\n\nnama_siswa = \"Ahmad Fadhil\"\numur = 16\nnilai_rata_rata = 88.5\nstatus_aktif = True\n\nprint(\"=\" * 32)\nprint(\"      KARTU BIODATA SISWA       \")\nprint(\"=\" * 32)\nprint(\"Nama   :\", nama_siswa)\nprint(\"Umur   :\", umur, \"tahun\")\nprint(\"Nilai  :\", nilai_rata_rata)\nprint(\"Status : Aktif (\", status_aktif, \")\")\nprint(\"=\" * 32)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Menyambung Teks dan Angka dengan Tanda Tambah (+)\n        </div>\n        <p>Jangan menulis <code>print(\"Nilai: \" + nilai_rata_rata)</code> karena akan memicu <code>TypeError</code>. Gunakan pemisah koma <code>print(\"Nilai:\", nilai_rata_rata)</code> agar Python otomatis menambahkan spasi dan mengonversinya secara aman.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Karakter garis pemisah panjang seperti <code>\"=\" * 32</code> adalah trik cerdas Python untuk mencetak 32 buah tanda sama dengan tanpa harus mengetiknya satu per satu di ponsel!</p>\n        </div>\n    </div>\n</div>', '# Boss Challenge Part 1\nnama = \"Budi Santoso\"\nkelas = \"PPLG X-1\"\numur = 16\nstatus = True\n\n# Cetak biodata terformat sesuai instruksi', 5, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (5, 'Komponen apa saja yang wajib hadir dalam program Biodata Siswa yang baik?', 'Hanya fungsi print tanpa variabel sama sekali', 'Variabel penampung data (str, int, float, bool), komentar dokumentasi, dan fungsi print terformat', 'Perulangan while loop tak terhingga', 'Koneksi database SQL', 'B', 'Program biodata mendasar di Part 1 mengintegrasikan variabel dari berbagai tipe data primitif, komentar penjelasan, dan pencetakan data ke layar.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (5, 'Jika Anda ingin mencetak teks dan variabel sekaligus dalam satu perintah print:\nnama = \"Fadhil\"\numur = 16\nManakah sintaks yang paling tepat?', 'print(\"Nama:\", nama, \"- Umur:\", umur)', 'print \"Nama:\" nama \"Umur:\" umur', 'print(\"Nama:\" + umur)', 'print(Nama, nama; Umur, umur)', 'A', 'Fungsi print() dapat menerima banyak argumen yang dipisahkan tanda koma. Setiap nilai akan otomatis dicetak dengan pemisah spasi secara aman.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (5, 'Mengapa perintah print(\"Nilai: \" + 88.5) akan menghasilkan TypeError di Python?', 'Karena Python tidak mengizinkan penggabungan operator tambah (+) langsung antara String dan Float tanpa konversi', 'Karena angka 88.5 tidak boleh dicetak', 'Karena tanda titik dilarang di dalam tanda kurung', 'Karena nama variabel salah', 'A', 'Operator tambah (+) pada string hanya bisa menggabungkan sesama string. Solusinya gunakan pemisah koma: print(\"Nilai:\", 88.5) atau konversi str(88.5).', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (5, 'Tantangan 1.5 (Boss): Kartu Biodata Digital', 'Buatlah program yang mencetak tepat 4 baris berikut:\n=== KARTU SISWA ===\nNAMA: Budi Santoso\nKELAS: PPLG X-1\nSTATUS: AKTIF', 'print(\"=== KARTU SISWA ===\")\n', '[{\"name\": \"Cek Format Kartu Biodata\", \"expected_output\": \"=== KARTU SISWA ===\nNAMA: Budi Santoso\nKELAS: PPLG X-1\nSTATUS: AKTIF\"}]', 'Cetak baris demi baris menggunakan print() dengan teks yang persis.', 50);
INSERT INTO modules (part_number, title, slug, description, badge_name, badge_icon, order_index) VALUES (2, 'Operator, Input & Format Teks', 'operator-dan-input', 'Mengolah data input pengguna, operasi aritmatika, perbandingan, logika, dan f-string.', 'Calculation Ace', 'fa-calculator', 2);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (6, 2, '2.1', '2.1 Operator Aritmatika (+, -, *, /, //, %, **)', '2-1-operator-aritmatika', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Mesin Kasir & Kalkulator Cerdas\n        </div>\n        <p>Bayangkan Anda seorang kasir di minimarket. Anda menjumlahkan total belanjaan (+), memberi potongan diskon (-), mengalikan jumlah barang (*), membagi biaya patungan (/), mencari tahu sisa permen kembalian (%), hingga menghitung bunga simpanan berganda (**). Di Python, komputer bertindak sebagai kalkulator super cepat yang dapat mengeksekusi jutaan operasi matematika dalam sekejap mata!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Konsep Inti &amp; Operator Aritmatika\n        </h4>\n        <p>Python memiliki 7 operator aritmatika bawaan yang sangat fleksibel:</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-2 text-slate-600\">\n            <li><code>+</code> (Penjumlahan): Menjumlahkan dua angka.</li>\n            <li><code>-</code> (Pengurangan): Mengurangkan angka kedua dari angka pertama.</li>\n            <li><code>*</code> (Perkalian): Mengalikan angka.</li>\n            <li><code>/</code> (Pembagian Nyata): Selalu menghasilkan tipe data <strong>float</strong> desimal (misal <code>10 / 2</code> &rarr; <code>5.0</code>).</li>\n            <li><code>//</code> (Pembagian Bulat / Floor Division): Membuang angka di belakang koma dan membulatkan ke bawah (misal <code>10 // 3</code> &rarr; <code>3</code>).</li>\n            <li><code>%</code> (Modulus): Menghasilkan sisa bagi (misal <code>10 % 3</code> &rarr; <code>1</code>). Sangat bermanfaat untuk mengecek bilangan ganjil/genap!</li>\n            <li><code>**</code> (Perpangkatan / Eksponen): Memangkatkan angka (misal <code>2 ** 3</code> &rarr; <code>8</code>).</li>\n        </ul>\n        <div class=\"mt-3 p-3 bg-blue-50 border border-blue-200 rounded-xl text-blue-900 text-xs\">\n            <strong>Aturan Prioritas (PEMDAS):</strong> Python mendahulukan Kurung <code>()</code>, Pangkat <code>**</code>, Kali/Bagi <code>* / // %</code>, baru Tambah/Kurang <code>+ -</code>.\n        </div>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Simulasi Pembagian Permen ke Siswa\ntotal_permen = 25\njumlah_anak = 4\n\n# Pembagian bulat: berapa permen yang didapat tiap anak\npermen_per_anak = total_permen // jumlah_anak\n\n# Modulus: berapa sisa permen yang tertinggal di toples\nsisa_permen = total_permen % jumlah_anak\n\nprint(\"Setiap anak mendapat:\", permen_per_anak, \"permen\")\nprint(\"Sisa permen di toples:\", sisa_permen, \"buah\")\n\n# Menghitung kuadrat (pangkat dua)\nsisi = 5\nluas = sisi ** 2\nprint(\"Luas persegi (5^2):\", luas)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error Pemula: Salah Urutan Operasi &amp; ZeroDivisionError\n        </div>\n        <p><strong>1. Mengabaikan Tanda Kurung:</strong></p>\n        <pre class=\"bg-rose-950/20 text-rose-900 p-2.5 rounded-xl font-mono text-xs mt-1\"><code># SALAH (prioritas pembagian dieksekusi lebih dulu):\nrata_rata = 70 + 80 + 90 / 3  # Hasilnya 180.0!\n\n# BENAR (tambahkan tanda kurung agar dijumlahkan dulu):\nrata_rata = (70 + 80 + 90) / 3  # Hasilnya 80.0</code></pre>\n        <p class=\"mt-2\"><strong>2. ZeroDivisionError:</strong> Membagi angka dengan 0 (misal <code>10 / 0</code> atau <code>10 % 0</code>) akan langsung mematikan program secara fatal.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Tombol operator matematika seperti <code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, dan <code>%</code> tersedia langsung di bilah toolbar tepat di atas keyboard sentuh HP Anda. Gunakan untuk mengetik ekspresi tanpa harus berpindah ke mode simbol keyboard bawaan HP.</p>\n        </div>\n    </div>\n</div>', 'a = 15\nb = 4\n\nprint(\"Penjumlahan :\", a + b)\nprint(\"Pembagian   :\", a / b)\nprint(\"Bagi Bulat  :\", a // b)\nprint(\"Sisa Bagi % :\", a % b)\nprint(\"Pangkat **  :\", a ** 2)', 1, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (6, 'Manakah operator Python yang digunakan untuk menghasilkan SISA BAGI dari dua bilangan bulat?', '// (Floor division)', '% (Modulus)', '/ (Pembagian pecahan)', '** (Perpangkatan)', 'B', 'Operator persen (%) di Python bertindak sebagai Modulus, yaitu menghasilkan sisa dari operasi pembagian bulat (misal 17 % 5 = 2).', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (6, 'Berapakah output dari kode berikut?\nhasil = 14 % 4 + 2 ** 3\nprint(hasil)', '10', '12', '8', '14', 'A', '14 % 4 bernilai 2 (karena 14 dibagi 4 menghasilkan 3 sisa 2). Lalu 2 ** 3 bernilai 8. Terakhir 2 + 8 = 10.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (6, 'Seorang siswa ingin menghitung rata-rata nilai tiga tugas:\nnilai1 = 80\nnilai2 = 90\nnilai3 = 70\nrata_rata = nilai1 + nilai2 + nilai3 / 3\nprint(rata_rata)\nMengapa output yang dihasilkan tidak sesuai ekspektasi?', 'Karena variabel nama tidak boleh menggunakan angka di akhir', 'Karena Python mengeksekusi nilai3 / 3 terlebih dahulu akibat urutan prioritas operator matematika', 'Karena nilai tidak bisa dibagi jika berupa integer', 'Karena fungsi print tidak bisa mencetak variabel bertipe float', 'B', 'Pembagian (/) memiliki prioritas lebih tinggi daripada penjumlahan (+). Untuk memperbaikinya, kelompokkan penjumlahan dengan kurung: (nilai1 + nilai2 + nilai3) / 3.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (6, 'Tantangan 2.1: Menghitung Luas dan Keliling', 'Diberikan panjang = 10 dan lebar = 5. Hitung luas (panjang * lebar) dan keliling (2 * (panjang + lebar)).\nCetak:\nLuas: 50\nKeliling: 30', 'panjang = 10\nlebar = 5\n# Hitung dan cetak\n', '[{\"name\": \"Cek Luas dan Keliling\", \"expected_output\": \"Luas: 50\nKeliling: 30\"}]', 'luas = panjang * lebar; keliling = 2 * (panjang + lebar)', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (7, 2, '2.2', '2.2 Mengambil Input & Type Casting', '2-2-input-type-casting', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Formulir Isian Pendaftaran\n        </div>\n        <p>Ketika Anda mengisi formulir kertas di sekolah, kolom \"Nama\", \"Nomor Sepatu\", dan \"Tinggi Badan\" semuanya ditulis menggunakan tinta pena di atas kertas. Bagi kertas, semua tulisan itu hanyalah teks! Jika petugas ingin menghitung rata-rata tinggi badan seluruh kelas di kalkulator, ia harus membaca tulisan teks tersebut lalu mengetikkan angkanya ke kalkulator. Inilah konsep dasar <code>input()</code> dan <strong>Type Casting</strong> (konversi tipe data) di pemrograman.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Konsep Inti &amp; Cara Kerja input()\n        </h4>\n        <p>Fungsi <code>input(\"Prompt Pesan: \")</code> digunakan untuk meminta pengguna mengetikkan data melalui keyboard. Program akan berhenti sementara (pause) menunggu pengguna menekan tombol Enter.</p>\n        <div class=\"mt-2 p-3 bg-rose-50 border border-rose-200 rounded-xl text-rose-950 font-semibold text-xs\">\n            <i class=\"fa-solid fa-circle-exclamation text-rose-600\"></i> HUKUM MUTLAK INPUT: Semua data yang masuk dari fungsi input() SELALU bertipe String (str), meskipun pengguna mengetikkan angka 100!\n        </div>\n        <p class=\"mt-2\">Agar bisa dihitung secara matematika, teks input harus di-casting (dikonversi) secara eksplisit menggunakan fungsi pembungkus:</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-1 text-slate-600\">\n            <li><code>int()</code>: Mengubah teks angka bulat menjadi integer (misal: <code>int(\"25\")</code> &rarr; <code>25</code>).</li>\n            <li><code>float()</code>: Mengubah teks desimal menjadi float (misal: <code>float(\"75.5\")</code> &rarr; <code>75.5</code>).</li>\n            <li><code>str()</code>: Mengubah angka menjadi teks kembali.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Mengambil input teks (nama siswa)\nnama = input(\"Masukkan nama Anda: \")\n\n# Mengambil input angka dan langsung melakukan type casting ke integer\ntahun_lahir = int(input(\"Masukkan tahun lahir Anda: \"))\n\n# Menghitung usia\ntahun_sekarang = 2026\nusia = tahun_sekarang - tahun_lahir\n\nprint(\"Halo,\", nama)\nprint(\"Tahun ini usia Anda adalah:\", usia, \"tahun\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error Pemula: Menjumlahkan Input Teks Mentah\n        </div>\n        <p>Jika Anda lupa menambahkan <code>int()</code> atau <code>float()</code>, Python akan memperlakukan angka sebagai teks dan menyambungkannya (concatenation) alih-alih menjumlahkannya:</p>\n        <pre class=\"bg-rose-950/20 text-rose-900 p-2.5 rounded-xl font-mono text-xs mt-1\"><code>a = input(\"Angka 1: \") # Misal diketik 10\nb = input(\"Angka 2: \") # Misal diketik 20\n\nprint(a + b) # OUTPUT: \"1020\" BUKAN 30!</code></pre>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Saat menjalankan kode dengan <code>input()</code> di browser HP pada PyLMS, kotak dialog interaktif akan muncul. Ketik jawaban Anda lalu ketuk tombol OK atau Enter pada keyboard HP untuk melanjutkan eksekusi program.</p>\n        </div>\n    </div>\n</div>', 'nama = input(\"Masukkan nama Anda: \")\ntahun_lahir = int(input(\"Masukkan tahun lahir: \"))\numur = 2026 - tahun_lahir\n\nprint(\"Halo\", nama, \"umur Anda adalah\", umur, \"tahun\")', 2, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (7, 'Tipe data apakah yang SELALU dihasilkan oleh fungsi bawaan input() di Python?', 'Integer (int)', 'String (str)', 'Float (float)', 'Tergantung apakah pengguna mengetik huruf atau angka', 'B', 'Fungsi input() di Python selalu mengembalikan nilai bertipe String (str), apapun karakter yang diketikkan pengguna melalui keyboard.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (7, 'Perhatikan kode berikut:\nx = input(\"Masukkan x: \")  # Pengguna mengetik 25\ny = input(\"Masukkan y: \")  # Pengguna mengetik 35\nprint(x + y)\nApakah output yang tercetak di layar?', '60', '2535', 'TypeError: unsupported operand', 'None', 'B', 'Karena x dan y bertipe string (teks), tanda plus (+) akan menggabungkan kedua teks menjadi \"2535\", bukan menjumlahkannya secara matematika.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (7, 'Bagaimanakah cara memperbaiki kode berikut agar dapat menghitung keliling lingkaran desimal dengan benar?\njari = input(\"Jari-jari: \")\nkeliling = 2 * 3.14 * jari', 'jari = str(input(\"Jari-jari: \"))', 'jari = float(input(\"Jari-jari: \"))', 'jari = round(input(\"Jari-jari: \"))', 'keliling = int(jari) + 3.14', 'B', 'Jari-jari lingkaran bisa berupa angka desimal, sehingga harus di-casting menggunakan float(input(...)) agar dapat dikalikan dengan float 3.14.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (7, 'Tantangan 2.2: Pengganda Angka', 'Ambil satu angka input dari user, kalikan dengan 2, lalu cetak hasilnya dalam format:\nHasil: <nilai>', 'angka = int(input())\n# Kalikan dengan 2 dan cetak\n', '[{\"name\": \"Uji Angka 7\", \"inputs\": [\"7\"], \"expected_output\": \"Hasil: 14\"}, {\"name\": \"Uji Angka 25\", \"inputs\": [\"25\"], \"expected_output\": \"Hasil: 50\"}]', 'print(f\"Hasil: {angka * 2}\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (8, 2, '2.3', '2.3 Debugging: Mengatasi Error Tipe Data', '2-3-debugging-tipe-data', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Memasukkan Koin ke Lubang Kaset\n        </div>\n        <p>Bayangkan Anda memiliki mesin cuci otomatis koin. Mesin hanya menerima koin logam berbentuk bulat. Jika seseorang memasukkan selembar uang kertas atau batu ke dalam lubang koin, mesin akan macet dan berbunyi alarm error! Di Python, error tipe data terjadi saat Anda menyuruh komputer melakukan operasi pada benda yang tidak kompatibel.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Anatomi TypeError &amp; ValueError\n        </h4>\n        <p>Dalam pengolahan data pemula, dua error ini adalah yang paling sering ditemui:</p>\n        <ul class=\"list-disc pl-5 space-y-2 mt-2 text-slate-600\">\n            <li>\n                <strong>TypeError:</strong> Terjadi saat operator diterapkan pada tipe data yang tidak cocok.\n                <br><span class=\"text-rose-600 font-mono text-xs\">TypeError: can only concatenate str (not \"int\") to str</span>\n                <br>Contoh: <code>\"Umur saya: \" + 17</code>. Python bingung: apakah harus mengubah angka jadi teks atau teks jadi angka?\n            </li>\n            <li>\n                <strong>ValueError:</strong> Terjadi saat fungsinya benar, tetapi isi nilainya tidak valid untuk dikonversi.\n                <br><span class=\"text-rose-600 font-mono text-xs\">ValueError: invalid literal for int() with base 10: \'budi\'</span>\n                <br>Contoh: <code>int(\"budi\")</code> atau <code>int(\"85.5\")</code>. Komputer tidak tahu cara mengubah kata \"budi\" menjadi bilangan bulat.\n            </li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Cara Mengatasi Error\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Solusi 1: Menggunakan fungsi str() sebelum penggabungan (+)\nskor = 95\npesan = \"Skor Anda adalah \" + str(skor)\nprint(pesan)\n\n# Solusi 2: Gunakan pemisah koma pada print() (Otomatis & Aman)\nprint(\"Skor Anda adalah\", skor)\n\n# Solusi 3: Konversi desimal bertahap jika input berupa teks desimal\nteks_angka = \"85.75\"\n# int(teks_angka) -> AKAN ERROR ValueError!\nnilai_float = float(teks_angka) # Sukses jadi 85.75\nnilai_bulat = int(nilai_float)   # Sukses jadi 85\nprint(\"Hasil konversi:\", nilai_bulat)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Aturan Emas Debugging: Baca Baris Terakhir Error\n        </div>\n        <p>Saat terminal PyLMS memunculkan teks merah panjang (Traceback), jangan panik! Langsung scroll ke <strong>baris paling bawah</strong>. Di sanalah nama error (misal <code>ValueError</code>) dan nomor baris penyebab error tertera dengan jelas.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Jika layar output tertutup error, Anda dapat menekan tombol <strong>Clear Output</strong> atau scroll ke bawah untuk melihat nomor baris kode yang ditunjuk oleh panah merah interpreter.</p>\n        </div>\n    </div>\n</div>', '# Kode di bawah memiliki bug penggabungan teks\na = input()\nb = input()\n# Perbaiki agar menjumlahkan secara matematika\nprint(\"Jumlah:\", a + b)', 3, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (8, 'Perintah manakah di bawah ini yang akan memicu terjadinya ValueError di Python?', 'float(\"45.5\")', 'int(\"sembilan\")', 'str(100)', 'int(\"150\")', 'B', 'Fungsi int(\"sembilan\") akan menghasilkan ValueError karena kata alfabet \"sembilan\" tidak dapat diterjemahkan menjadi representasi angka numerik.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (8, 'Perhatikan baris kode berikut:\ntotal = \"Nilai total: \" + 100\nApakah jenis error yang akan dilaporkan oleh interpreter Python?', 'SyntaxError', 'TypeError', 'ZeroDivisionError', 'IndexError', 'B', 'Python melarang penggabungan teks string dan integer secara langsung dengan operator +. Hal ini memicu TypeError: can only concatenate str (not \"int\") to str.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (8, 'Seorang murid memiliki variabel str: teks = \"99.8\". Jika ia ingin mengubahnya menjadi bilangan bulat (integer), langkah paling tepat adalah:', 'int(teks)', 'int(float(teks))', 'round(teks)', 'str(int(teks))', 'B', 'int(\"99.8\") langsung akan menyebabkan ValueError karena mengandung titik desimal. Teks harus diubah ke float dahulu dengan float(teks), baru diubah ke integer dengan int().', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (8, 'Tantangan 2.3: Perbaiki Bug Penjumlahan Input', 'Perbaiki program agar menerima 2 baris input angka, lalu mencetak jumlah matematikanya:\nJumlah: <hasil>', 'a = int(input())\nb = int(input())\nprint(f\"Jumlah: {a + b}\")', '[{\"name\": \"Uji 15 + 25\", \"inputs\": [\"15\", \"25\"], \"expected_output\": \"Jumlah: 40\"}]', 'Pastikan menggunakan int(input()) untuk kedua variabel.', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (9, 2, '2.4', '2.4 F-Strings: Format Teks Modern', '2-4-fstrings-format-modern', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Piagam Sertifikat Berformat Otomatis\n        </div>\n        <p>Bayangkan Anda mencetak sertifikat juara lomba. Desain sertifikat sudah memiliki bingkai dan teks baku: <em>\"Diberikan kepada [NAMA], atas pencapaian skor [SKOR] poin\"</em>. Anda hanya perlu menyisipkan nama pemenang ke dalam kotak kurung tersebut tanpa merombak ulang seluruh teks. Inilah fitur <strong>f-string</strong> (Formatted String Literals), senjata paling elegan dan modern di Python!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Konsep Inti &amp; Keunggulan f-string\n        </h4>\n        <p>Diperkenalkan sejak Python 3.6, f-string memungkinkan Anda menyisipkan variabel dan ekspresi logika langsung ke dalam teks dengan sintaks yang sangat bersih:</p>\n        <ol class=\"list-decimal pl-5 space-y-1 mt-2 text-slate-600\">\n            <li>Tambahkan huruf <code>f</code> tepat di depan tanda kutip pembuka string: <code>f\"...\"</code>.</li>\n            <li>Bungkus variabel atau perhitungan matematika di dalam kurung kurawal <code>{ }</code>.</li>\n            <li>Anda tidak perlu lagi melakukan type casting manual <code>str()</code> atau menghubungkan puluhan tanda tambah <code>+</code>!</li>\n            <li>Mendukung pemformatan angka presisi, misalnya <code>{nilai:.2f}</code> untuk menampilkan tepat 2 angka di belakang koma.</li>\n        </ol>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>produk = \"Kopi Susu Gula Aren\"\nharga = 18000\njumlah = 3\ndiskon = 0.1 # Diskon 10%\n\ntotal_kotor = harga * jumlah\ntotal_bayar = total_kotor * (1 - diskon)\n\n# Menggunakan f-string modern\nprint(f\"Struk Belanja:\")\nprint(f\"- Item   : {produk}\")\nprint(f\"- Qty    : {jumlah} x Rp {harga:,}\")\nprint(f\"- Diskon : {diskon * 100:.0f}%\")\nprint(f\"- Total  : Rp {total_bayar:,.2f}\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error Pemula: Lupa Huruf f di Depan Kutip\n        </div>\n        <p>Jika Anda lupa menuliskan huruf <code>f</code> sebelum tanda kutip pembuka, Python akan menganggap kurung kurawal sebagai teks biasa:</p>\n        <pre class=\"bg-rose-950/20 text-rose-900 p-2.5 rounded-xl font-mono text-xs mt-1\"><code>nama = \"Fadhil\"\n\n# SALAH (lupa f):\nprint(\"Halo {nama}, selamat datang!\")\n# Output: Halo {nama}, selamat datang! (Kurung kurawal tercetak mentah)\n\n# BENAR:\nprint(f\"Halo {nama}, selamat datang!\")\n# Output: Halo Fadhil, selamat datang!</code></pre>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Tanda kurung kurawal <code>{</code> dan <code>}</code> serta tanda kutip dua <code>\"</code> terletak bersebelahan di bilah alat bantu simbol PyLMS. Ketuk tombol <code>{ }</code> untuk langsung menyisipkan sepasang kurung kurawal sekaligus.</p>\n        </div>\n    </div>\n</div>', 'barang = \"Buku Tulis\"\nharga = 5000\njumlah = 3\ntotal = harga * jumlah\n\nprint(f\"Barang : {barang}\")\nprint(f\"Total  : Rp {total}\")', 4, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (9, 'Karakter apakah yang wajib diletakkan tepat di depan tanda kutip pembuka string agar fitur f-string dapat aktif?', 'Huruf s', 'Huruf f', 'Tanda dollar ($)', 'Tanda pagar (#)', 'B', 'Awalan huruf f (atau F) menandakan f-string (formatted string literal) di Python.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (9, 'Perhatikan potongan kode berikut:\nitem = \"Buku Tulis\"\nharga = 5000\nprint(f\"Beli 2 {item} = Rp {harga * 2}\")\nApakah output yang dihasilkan kode tersebut?', 'Beli 2 Buku Tulis = Rp {harga * 2}', 'Beli 2 Buku Tulis = Rp 10000', 'Beli 2 item = Rp 10000', 'SyntaxError: invalid syntax', 'B', 'Di dalam f-string, ekspresi matematika seperti {harga * 2} akan langsung dihitung nilainya sehingga tercetak Rp 10000.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (9, 'Seorang programmer ingin menampilkan angka phi dengan tepat 2 digit desimal di f-string:\nphi = 3.14159265\nManakah format penulisan yang benar di dalam f-string?', 'print(f\"Nilai phi: {phi:2d}\")', 'print(f\"Nilai phi: {phi:.2f}\")', 'print(f\"Nilai phi: {phi%2}\")', 'print(f\"Nilai phi: {round:2:phi}\")', 'B', 'Spesifikasi format .2f di dalam kurung kurawal f-string ({phi:.2f}) membulatkan dan membatasi output float menjadi tepat 2 angka di belakang koma.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (9, 'Tantangan 2.4: Cetak Struk Belanja dengan F-String', 'Diberikan produk = \"Pensil\", qty = 4, harga = 2000. Cetak tepat:\nBeli 4 Pensil seharga Rp 8000', 'produk = \"Pensil\"\nqty = 4\nharga = 2000\n# Cetak dengan f-string\n', '[{\"name\": \"Cek Struk Pensil\", \"expected_output\": \"Beli 4 Pensil seharga Rp 8000\"}]', 'print(f\"Beli {qty} {produk} seharga Rp {qty * harga}\")', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (10, 2, '2.5', '2.5 Boss Challenge: Konverter Suhu Multi-Satuan', '2-5-boss-challenge-suhu', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-trophy text-amber-600\"></i> 1. Uji Kompetensi Part 2: Stasiun Cuaca Mandiri\n        </div>\n        <p>Selamat telah menyelesaikan materi kalkulasi dan input data! Di Boss Challenge kali ini, Anda ditantang membuat aplikasi kalkulator suhu stasiun cuaca yang menerima input temperatur Celcius dari pengguna, lalu secara otomatis mengonversinya ke tiga skala internasional sekaligus: <strong>Fahrenheit</strong>, <strong>Reamur</strong>, dan <strong>Kelvin</strong> dengan format tampilan rapi 2 angka di belakang koma.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Formula &amp; Aturan Perhitungan\n        </h4>\n        <p>Gunakan rumus konversi fisika standar dari Celcius (C):</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-2 text-slate-600\">\n            <li><strong>Fahrenheit (F):</strong> <code>(C * 9/5) + 32</code></li>\n            <li><strong>Reamur (R):</strong> <code>C * 4/5</code></li>\n            <li><strong>Kelvin (K):</strong> <code>C + 273.15</code></li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Solusi\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Program Konverter Suhu Cuaca\nprint(\"=== STASIUN MONITORING CUACA ===\")\ncelcius = float(input(\"Masukkan suhu dalam Celcius: \"))\n\n# Perhitungan konversi\nfahrenheit = (celcius * 9/5) + 32\nreamur = celcius * 4/5\nkelvin = celcius + 273.15\n\n# Tampilan hasil menggunakan f-string terformat 2 desimal\nprint(\"-\" * 32)\nprint(f\"Hasil Konversi Suhu ({celcius:.1f}°C):\")\nprint(f\"1. Fahrenheit : {fahrenheit:.2f}°F\")\nprint(f\"2. Reamur     : {reamur:.2f}°R\")\nprint(f\"3. Kelvin     : {kelvin:.2f} K\")\nprint(\"-\" * 32)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Pemisah Desimal Koma vs Titik\n        </div>\n        <p>Di Indonesia kita terbiasa menulis desimal dengan tanda koma (misal <code>27,5</code>). Namun di Python, tanda koma berfungsi sebagai pemisah argumen! Selalu gunakan tanda <strong>titik</strong> (<code>27.5</code>) saat mengetikkan angka desimal di kode maupun pada input interaktif.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Uji coba program Anda dengan memasukkan angka <code>0</code> (titik beku air). Jika Fahrenheit bernilai 32.0°F dan Kelvin bernilai 273.15 K, berarti rumus kalkulasi Anda telah 100% akurat!</p>\n        </div>\n    </div>\n</div>', 'celcius = float(input())\n# Hitung fahrenheit dan reamur\n', 5, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (10, 'Mengapa input suhu pengguna harus dikonversi dengan float(input(...)) dan bukan int(input(...))?', 'Karena int() tidak bisa menerima input dari keyboard', 'Agar program dapat menerima angka suhu pecahan desimal seperti 36.5 atau 27.8 derajat', 'Karena fungsi float berjalan lebih cepat dari int', 'Karena suhu selalu bernilai negatif', 'B', 'Suhu di dunia nyata seringkali berbentuk desimal (misalnya 36.5°C). Penggunaan float() memungkinkan program menerima bilangan bulat maupun desimal tanpa memicu crash ValueError.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (10, 'Jika suhu Celcius adalah 100°C (titik didih air), berapakah nilai suhu tersebut dalam skala Fahrenheit berdasarkan rumus (C * 9/5) + 32?', '180.0°F', '212.0°F', '100.0°F', '244.0°F', 'B', '(100 * 9/5) + 32 = (180) + 32 = 212.0°F.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (10, 'Seorang murid menulis rumus konversi Reamur sebagai berikut:\nr = c * 4 / 5\nNamun saat c = 20, ia ingin mencetak hasilnya ke layar menggunakan format f-string. Manakah baris print yang tepat?', 'print(f\"Reamur: {r:.2f}°R\")', 'print(\"Reamur: {r:.2f}°R\")', 'print(f\"Reamur: r:.2f\")', 'print(f\"Reamur: \" + {r})', 'A', 'Sintaks f\"Reamur: {r:.2f}°R\" mengaktifkan f-string, menyisipkan variabel r dengan format 2 desimal, dan mencetak satuan °R.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (10, 'Tantangan 2.5 (Boss): Konverter Suhu Lengkap', 'Program menerima satu angka input suhu Celcius. Cetak tepat 2 baris:\nFahrenheit: <nilai>\nReamur: <nilai>', 'celcius = float(input())\nfah = (celcius * 9/5) + 32\nrea = celcius * 4/5\nprint(f\"Fahrenheit: {fah}\")\nprint(f\"Reamur: {rea}\")', '[{\"name\": \"Uji 100 C\", \"inputs\": [\"100\"], \"expected_output\": \"Fahrenheit: 212.0\nReamur: 80.0\"}, {\"name\": \"Uji 0 C\", \"inputs\": [\"0\"], \"expected_output\": \"Fahrenheit: 32.0\nReamur: 0.0\"}]', 'Gunakan rumus konversi dan cetak 2 baris terpisah.', 50);
INSERT INTO modules (part_number, title, slug, description, badge_name, badge_icon, order_index) VALUES (3, 'Percabangan (Kondisi Logika)', 'percabangan-logika', 'Membuat program mengambil keputusan menggunakan struktur if, elif, else, and, or, not.', 'Logic Master', 'fa-code-branch', 3);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (11, 3, '3.1', '3.1 Operator Pembanding (==, !=, <, >, <=, >=)', '3-1-operator-pembanding', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Palang Pintu Gerbang Tol Otomatis\n        </div>\n        <p>Bayangkan palang gerbang tol otomatis. Ketika mobil Anda menempelkan kartu e-toll, sensor memeriksa: <em>\"Apakah saldo kartu lebih besar atau sama dengan Rp 15.000?\"</em>. Jawabannya hanya ada dua kemungkinan di dunia: <strong>YA (True)</strong> atau <strong>TIDAK (False)</strong>. Di Python, operator pembanding adalah mata dan telinga komputer untuk membuat keputusan berbasis fakta!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Daftar Operator Pembanding Python\n        </h4>\n        <p>Setiap operasi pembandingan SELALU menghasilkan tipe data <strong>Boolean</strong> (<code>True</code> atau <code>False</code>):</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-2 text-slate-600\">\n            <li><code>==</code> (Sama dengan): Memeriksa apakah nilai kiri dan kanan identik.</li>\n            <li><code>!=</code> (Tidak sama dengan): Bernilai True jika kedua nilai berbeda.</li>\n            <li><code>&gt;</code> (Lebih besar dari): Memeriksa apakah nilai kiri lebih besar.</li>\n            <li><code>&lt;</code> (Lebih kecil dari): Memeriksa apakah nilai kiri lebih kecil.</li>\n            <li><code>&gt;=</code> (Lebih besar atau sama dengan): Minimal bernilai sama.</li>\n            <li><code>&lt;=</code> (Lebih kecil atau sama dengan): Maksimal bernilai sama.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>kkm = 75\nnilai_siswa = 82\numur = 16\n\n# Evaluasi nilai perbandingan\napakah_lulus = nilai_siswa >= kkm\napakah_punya_ktp = umur >= 17\napakah_sempurna = nilai_siswa == 100\n\nprint(\"Nilai Siswa      :\", nilai_siswa)\nprint(\"Apakah Lulus KKM :\", apakah_lulus)     # True\nprint(\"Boleh Buat KTP   :\", apakah_punya_ktp) # False\nprint(\"Nilai Sempurna   :\", apakah_sempurna)  # False</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Paling Fatal Pemula: Beda = dan ==\n        </div>\n        <p>Ini adalah kesalahan nomor 1 bagi programmer pemula di seluruh dunia:</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-1 text-rose-900\">\n            <li>Tanda <code>=</code> (Satu buah) adalah <strong>Assignment</strong>: Memberi/mengisi nilai ke dalam variabel (misal: <code>skor = 100</code>).</li>\n            <li>Tanda <code>==</code> (Dua buah) adalah <strong>Comparison</strong>: Menguji apakah kedua nilai sama (misal: <code>skor == 100</code>).</li>\n        </ul>\n        <p class=\"mt-1 text-xs text-rose-800\">Menuliskan <code>if skor = 100:</code> akan langsung menghasilkan <code>SyntaxError: invalid syntax</code>!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Tombol <code>==</code>, <code>!=</code>, <code>&lt;=</code>, dan <code>&gt;=</code> telah disediakan sebagai satu tombol praktis di atas keyboard HP Anda pada PyLMS agar Anda tidak perlu mengetik dua karakter secara terpisah.</p>\n        </div>\n    </div>\n</div>', 'nilai = 80\nkkm = 75\n\nprint(\"Apakah tuntas?\", nilai >= kkm)\nprint(\"Apakah sempurna?\", nilai == 100)', 1, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (11, 'Manakah operator Python yang digunakan untuk menguji apakah dua nilai TIDAK SAMA DENGAN?', '<>', '!=', '!==', 'not ==', 'B', 'Di Python standar modern, tanda seru diikuti sama dengan (!=) merepresentasikan operator pertidaksamaan (not equal).', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (11, 'Berapakah output dari evaluasi kode berikut?\na = 25\nb = 30\nhasil = (a + 5) == b\nprint(hasil)', 'True', 'False', '30', 'SyntaxError', 'A', 'a + 5 bernilai 30. Karena 30 == 30 bernilai benar, maka hasil evaluasi perbandingan adalah True.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (11, 'Seorang murid menulis baris pemeriksaan password:\npassword_benar = \"smk123\"\ninput_user = \"smk123\"\nif input_user = password_benar:\n    print(\"Akses Diterima\")\nError apakah yang akan dimunculkan oleh Python?', 'TypeError: str cannot be assigned', 'SyntaxError: invalid syntax. Maybe you meant \'==\'?', 'NameError: name input_user is not defined', 'Program berjalan tanpa error', 'B', 'Dalam pernyataan kondisi if, Anda wajib menggunakan operator perbandingan == (dua tanda sama dengan), bukan operator pengisian nilai =.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (11, 'Tantangan 3.1: Pengecekan Angka Positif', 'Ambil satu angka input integer. Jika angka > 0, cetak \"POSITIF\". Jika tidak, cetak \"BUKAN POSITIF\".', 'angka = int(input())\nif angka > 0:\n    print(\"POSITIF\")\nelse:\n    print(\"BUKAN POSITIF\")', '[{\"name\": \"Uji 10\", \"inputs\": [\"10\"], \"expected_output\": \"POSITIF\"}, {\"name\": \"Uji -5\", \"inputs\": [\"-5\"], \"expected_output\": \"BUKAN POSITIF\"}]', 'Gunakan if angka > 0:', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (12, 3, '3.2', '3.2 Struktur if, elif, dan else', '3-2-if-elif-else', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Lampu Lalu Lintas Persimpangan\n        </div>\n        <p>Bayangkan Anda berkendara mendekati persimpangan jalan:\n        <br><strong>JIKA (if)</strong> lampu Merah &rarr; Kendaraan Berhenti.\n        <br><strong>ATAU JIKA (elif)</strong> lampu Kuning &rarr; Kendaraan Bersiap Pelan.\n        <br><strong>SELAIN ITU (else)</strong> &rarr; Kendaraan Jalan Terus (Hijau).\n        <br>Hanya satu warna lampu yang aktif dalam satu waktu. Begitulah cara struktur percabangan <code>if-elif-else</code> mengarahkan jalannya program Anda!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Sintaks &amp; Aturan Indentasi\n        </h4>\n        <p>Di Python, blok kode di dalam kondisi ditandai dengan <strong>titik dua (:)</strong> di akhir baris dan <strong>indentasi</strong> (menjorok masuk 4 spasi):</p>\n        <ol class=\"list-decimal pl-5 space-y-1 mt-2 text-slate-600\">\n            <li><code>if kondisi:</code> Dievaluasi pertama kali.</li>\n            <li><code>elif kondisi:</code> (Singkatan dari <em>else if</em>) Dievaluasi HANYA jika kondisi di atasnya bernilai False. Anda boleh memasang sebanyak mungkin elif.</li>\n            <li><code>else:</code> Dijalankan sebagai penampung terakhir bila SEMUA kondisi di atasnya bernilai False.</li>\n        </ol>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>nilai = int(input(\"Masukkan nilai ujian (0-100): \"))\n\nif nilai >= 90:\n    predikat = \"A (Sangat Memuaskan)\"\nelif nilai >= 80:\n    predikat = \"B (Baik)\"\nelif nilai >= 75:\n    predikat = \"C (Cukup - Batas KKM)\"\nelif nilai >= 60:\n    predikat = \"D (Kurang - Remedial)\"\nelse:\n    predikat = \"E (Wajib Mengulang)\"\n\nprint(f\"Hasil Evaluasi: {predikat}\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Lupa Titik Dua &amp; IndentationError\n        </div>\n        <p>Dua penyebab utama kode macet pada percabangan:</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-1 text-rose-900\">\n            <li><strong>Lupa Titik Dua (:)</strong>: Setiap baris <code>if</code>, <code>elif</code>, dan <code>else</code> WAJIB diakhiri tanda titik dua.</li>\n            <li><strong>IndentationError: expected an indented block</strong>: Baris kode di dalam blok kondisi harus menjorok masuk ke dalam.</li>\n        </ul>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Editor PyLMS secara otomatis menambahkan indentasi saat Anda menekan Enter setelah tanda titik dua <code>:</code>. Jika indentasi hilang, gunakan tombol <strong>TAB</strong> di bilah alat untuk memajukan baris kode.</p>\n        </div>\n    </div>\n</div>', 'suhu = 38\n\nif suhu >= 38:\n    print(\"Kondisi: Demam Tinggi\")\nelif suhu >= 37:\n    print(\"Kondisi: Hangat\")\nelse:\n    print(\"Kondisi: Normal\")', 2, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (12, 'Karakter apakah yang wajib diletakkan di akhir baris pernyataan if, elif, dan else di Python?', 'Titik koma (;)', 'Titik dua (:)', 'Tanda kurung kurawal ({)', 'Tanda panah (->)', 'B', 'Di Python, setiap header blok kontrol (if, elif, else, for, while, def) wajib diakhiri tanda titik dua (:).', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (12, 'Perhatikan program berikut:\nskor = 78\nif skor >= 85:\n    hasil = \"Sangat Baik\"\nelif skor >= 75:\n    hasil = \"Baik\"\nelse:\n    hasil = \"Cukup\"\nprint(hasil)\nApakah output program tersebut?', 'Sangat Baik', 'Baik', 'Cukup', 'Baik Sangat Baik', 'B', 'skor (78) tidak memenuhi >= 85, tetapi memenuhi kondisi kedua yaitu skor >= 75. Karena itu cabang elif pertama kali dieksekusi menghasilkan \"Baik\".', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (12, 'Mengapa kode berikut memicu IndentationError saat dijalankan?\numur = 18\nif umur >= 17:\nprint(\"Dewasa\")\nelse:\nprint(\"Anak-anak\")', 'Karena tidak ada tanda kurung pada umur >= 17', 'Karena perintah print tidak menjorok masuk (terindentasi) di bawah klausa if dan else', 'Karena variabel umur berupa integer', 'Karena else harus diganti dengan elif', 'B', 'Python menggunakan indentasi (spasi/tab) untuk menentukan cakupan blok kode. Perintah print harus menjorok 4 spasi ke kanan di bawah if dan else.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (12, 'Tantangan 3.2: Penentu Grade Nilai', 'Buat program penentu grade:\nNilai >= 85: \"GRADE A\"\nNilai >= 70: \"GRADE B\"\nLainnya: \"GRADE C\"', 'nilai = int(input())\nif nilai >= 85:\n    print(\"GRADE A\")\nelif nilai >= 70:\n    print(\"GRADE B\")\nelse:\n    print(\"GRADE C\")', '[{\"name\": \"Uji 90\", \"inputs\": [\"90\"], \"expected_output\": \"GRADE A\"}, {\"name\": \"Uji 75\", \"inputs\": [\"75\"], \"expected_output\": \"GRADE B\"}, {\"name\": \"Uji 50\", \"inputs\": [\"50\"], \"expected_output\": \"GRADE C\"}]', 'Gunakan if-elif-else terurut dari nilai terbesar.', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (13, 3, '3.3', '3.3 Operator Logika (and, or, not)', '3-3-operator-logika-and-or', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Syarat Rekrutmen Magang Industri\n        </div>\n        <p>Sebuah perusahaan teknologi membuka lowongan magang dengan dua kriteria berbeda:\n        <br><strong>Jalur A (AND):</strong> Harus Siswa Jurusan RPL <strong>DAN</strong> Nilai Algoritma minimal 80. (Dua syarat ini WAJIB terpenuhi bersamaan).\n        <br><strong>Jalur B (OR):</strong> Memiliki Portofolio Aplikasi <strong>ATAU</strong> Juara Lomba LKS. (Cukup salah satu saja terpenuhi, pelamar sudah lolos seleksi).\n        <br>Inilah cara operator logika menggabungkan multi-kondisi!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Tabel Kebenaran: and, or, not\n        </h4>\n        <p>Python menggunakan kata bahasa Inggris baku tanpa simbol aneh:</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-2 text-slate-600\">\n            <li><code>and</code>: Menghasilkan <strong>True HANYA JIKA kedua kondisi</strong> bernilai True. Jika salah satu saja False, hasilnya langsung False.</li>\n            <li><code>or</code>: Menghasilkan <strong>True jika SALAH SATU atau KEDUA kondisi</strong> bernilai True. Hanya menghasilkan False jika keduanya False.</li>\n            <li><code>not</code>: Membalikkan nilai Boolean. <code>not True</code> menghasilkan <code>False</code>, dan <code>not False</code> menghasilkan <code>True</code>.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>nilai_teori = 82\nnilai_praktik = 78\nsudah_kumpul_laporan = True\n\n# Syarat Kelulusan Uji Sertifikasi:\n# 1. Nilai teori minimal 75 DAN praktik minimal 75\n# 2. Serta laporan sudah dikumpulkan\nif nilai_teori >= 75 and nilai_praktik >= 75 and sudah_kumpul_laporan:\n    print(\"SELAMAT: Anda Lolos Sertifikasi Kompetensi!\")\nelse:\n    print(\"MOHON MAAF: Syarat sertifikasi belum lengkap.\")\n\n# Pengecekan tiket diskon (Anak di bawah 5 tahun ATAU Lansia di atas 60)\numur = 4\nif umur < 5 or umur >= 60:\n    print(\"Tiket Gratis untuk Balita/Lansia\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Menggunakan Simbol Bahasa Lain (&&, ||)\n        </div>\n        <p>Bagi yang pernah belajar C++ atau JavaScript, jangan gunakan simbol <code>&&</code> atau <code>||</code> di Python! Python akan memunculkan <code>SyntaxError</code>. Selalu gunakan kata <strong>and</strong> dan <strong>or</strong> huruf kecil.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Rentang nilai dapat ditulis secara berantai seperti rumus matematika di Python! Contoh: <code>70 <= nilai <= 100</code> adalah penulisan ringkas yang sah untuk <code>nilai >= 70 and nilai <= 100</code>.</p>\n        </div>\n    </div>\n</div>', 'kehadiran = 85\nnilai_tugas = 78\n\nif kehadiran >= 80 and nilai_tugas >= 75:\n    print(\"LULUS\")\nelse:\n    print(\"REMEDIAL\")', 3, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (13, 'Kondisi manakah yang menyebabkan operator \'and\' menghasilkan nilai True?', 'Jika salah satu kondisi bernilai True', 'Hanya jika SELURUH kondisi bernilai True', 'Jika semua kondisi bernilai False', 'Jika kondisi pertama bernilai False', 'B', 'Operator and mewajibkan seluruh kondisi bernilai True agar evaluasi total bernilai True.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (13, 'Perhatikan ekspresi logika berikut:\np = True\nq = False\nhasil = not q and not (p and q)\nprint(hasil)\nApakah output yang dihasilkan?', 'True', 'False', 'None', 'Error', 'A', 'not q adalah True. (p and q) bernilai False, sehingga not (p and q) bernilai True. Maka True and True menghasilkan True.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (13, 'Seorang pengembang ingin mengecek apakah umur seseorang berada di antara 13 sampai 19 tahun (Remaja):\numur = 15\nif umur >= 13 or umur <= 19:\n    print(\"Remaja\")\nMengapa penggunaan operator \'or\' di atas dianggap sebagai bug logika?', 'Karena akan menghasilkan SyntaxError', 'Karena ekspresi tersebut akan SELALU bernilai True untuk angka berapa pun (misal umur 5 atau 50 tahun tetap True)', 'Karena umur 15 bukan remaja', 'Karena operator or tidak bisa dipakai pada angka', 'B', 'Angka 5 memenuhi umur <= 19, dan angka 50 memenuhi umur >= 13. Akibat operator or, seluruh angka menjadi True. Seharusnya menggunakan operator and: umur >= 13 and umur <= 19.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (13, 'Tantangan 3.3: Seleksi Penerima Diskon Kafe', 'Siswa berhak diskon jika umur < 18 ATAU memiliki status member True. Input baris 1: umur (int), baris 2: member (\"ya\" / \"tidak\"). Jika berhak diskon, cetak \"DAPAT DISKON\", jika tidak cetak \"HARGA NORMAL\".', 'umur = int(input())\nmember = input()\nif umur < 18 or member == \"ya\":\n    print(\"DAPAT DISKON\")\nelse:\n    print(\"HARGA NORMAL\")', '[{\"name\": \"Uji Umur 16 Non Member\", \"inputs\": [\"16\", \"tidak\"], \"expected_output\": \"DAPAT DISKON\"}, {\"name\": \"Uji Umur 25 Non Member\", \"inputs\": [\"25\", \"tidak\"], \"expected_output\": \"HARGA NORMAL\"}]', 'Gunakan operator or: if umur < 18 or member == \"ya\":', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (14, 3, '3.4', '3.4 Percabangan Bersarang (Nested if)', '3-4-nested-if-bersarang', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Sistem Pintu Masuk Bandara\n        </div>\n        <p>Ketika Anda memasuki bandara untuk penerbangan internasional:\n        <br><strong>Pintu 1 (Luar):</strong> Petugas memeriksa apakah Anda punya tiket pesawat. Jika <em>Tidak</em>, langsung ditolak di pintu gerbang luar.\n        <br><strong>Pintu 2 (Dalam):</strong> Jika Anda punya tiket, Anda diizinkan masuk ke loket imigrasi untuk memeriksa paspor & visa.\n        <br>Pemeriksaan tahap kedua hanya dilakukan jika tahap pertama telah lolos. Inilah konsep <strong>Nested if</strong> (percabangan bersarang)!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Konsep &amp; Indentasi Bertingkat\n        </h4>\n        <p>Nested if adalah struktur kondisi <code>if</code> yang berada di dalam blok indentasi <code>if</code> lainnya. Setiap tingkatan bersarang membutuhkan tambahan 4 spasi indentasi ke dalam:</p>\n        <pre class=\"bg-slate-900 text-slate-100 p-3 rounded-xl font-mono text-xs\"><code>if kondisi_utama:\n    # Indentasi level 1 (4 spasi)\n    if sub_kondisi:\n        # Indentasi level 2 (8 spasi)\n        print(\"Lolos kedua level!\")\n    else:\n        print(\"Gagal di level kedua.\")\nelse:\n    print(\"Gagal di level pertama.\")</code></pre>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata: Simulasi Login Portal Siswa\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>username_terdaftar = \"smkwikrama\"\npassword_terdaftar = \"python2026\"\n\ninput_user = input(\"Username: \")\ninput_pass = input(\"Password: \")\n\n# Level 1: Cek keberadaan akun username\nif input_user == username_terdaftar:\n    # Level 2: Cek kecocokan password hanya jika username ditemukan\n    if input_pass == password_terdaftar:\n        print(\"Login Berhasil! Selamat datang di Dashboard.\")\n    else:\n        print(\"Error: Password Anda salah!\")\nelse:\n    print(\"Error: Akun Username tidak ditemukan dalam sistem.\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: \"Dangling Else\" Akibat Salah Spasi\n        </div>\n        <p>Jika indentasi blok <code>else</code> bergeser sedikit saja, Python akan memasangkannya dengan pernyataan <code>if</code> yang salah, mengubah seluruh alur logika program tanpa menghasilkan pesan error (silent bug)!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Perhatikan garis titik-titik vertikal di area editor kode PyLMS. Garis tersebut menunjukkan keselarasan kolom indentasi agar Anda tahu dengan tepat blok <code>if</code> mana yang berpasangan dengan blok <code>else</code>.</p>\n        </div>\n    </div>\n</div>', 'pin_benar = 1234\nsaldo = 50000\n\ninput_pin = 1234\ntarik = 20000\n\nif input_pin == pin_benar:\n    if tarik <= saldo:\n        print(\"Tarik tunai berhasil!\")\n    else:\n        print(\"Saldo tidak cukup!\")\nelse:\n    print(\"PIN salah!\")', 4, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (14, 'Apakah yang dimaksud dengan istilah \'Nested if\' dalam pemrograman Python?', 'Pernyataan if yang tidak memerlukan kondisi', 'Pernyataan if yang diletakkan di dalam blok pernyataan if lain', 'Perulangan while yang diganti dengan if', 'Fungsi print yang diulang berkali-kali', 'B', 'Nested if adalah percabangan bersarang di mana sebuah blok if berada di dalam cakupan blok if yang sudah ada.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (14, 'Perhatikan potongan kode berikut:\nskor = 90\nkehadiran = 70\nif skor >= 80:\n    if kehadiran >= 75:\n        print(\"Lulus Ujian\")\n    else:\n        print(\"Remedial Kehadiran\")\nelse:\n    print(\"Remedial Teori\")\nApakah teks yang akan dicetak di layar?', 'Lulus Ujian', 'Remedial Kehadiran', 'Remedial Teori', 'Tidak mencetak apa pun', 'B', 'skor (90) lolos kondisi luar (>= 80). Namun kehadiran (70) gagal kondisi dalam (>= 75), sehingga mengeksekusi cabang else dalam: \"Remedial Kehadiran\".', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (14, 'Berapa jumlah spasi standar yang dibutuhkan untuk baris kode pada tingkat bersarang kedua (Level 2) di Python?', '2 spasi', '4 spasi', '8 spasi (dua kali indentasi)', '16 spasi', 'C', 'Setiap level indentasi standar di Python adalah 4 spasi (PEP 8). Tingkat bersarang kedua membutuhkan 4 + 4 = 8 spasi.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (14, 'Tantangan 3.4: Validasi Gerbang Masuk', 'Input baris 1: status kartu (\"aktif\"/\"nonaktif\"). Input baris 2: saldo tiket (int). Jika kartu \"aktif\", periksa saldo: jika saldo >= 5000 cetak \"PINTU TERBUKA\", jika saldo < 5000 cetak \"SALDO KURANG\". Jika kartu bukan \"aktif\", cetak \"KARTU TIDAK VALID\".', 'kartu = input()\nsaldo = int(input())\nif kartu == \"aktif\":\n    if saldo >= 5000:\n        print(\"PINTU TERBUKA\")\n    else:\n        print(\"SALDO KURANG\")\nelse:\n    print(\"KARTU TIDAK VALID\")', '[{\"name\": \"Uji Aktif Cukup Saldo\", \"inputs\": [\"aktif\", \"10000\"], \"expected_output\": \"PINTU TERBUKA\"}, {\"name\": \"Uji Kartu Rusak\", \"inputs\": [\"blokir\", \"5000\"], \"expected_output\": \"KARTU TIDAK VALID\"}]', 'Gunakan percabangan bersarang if kartu == \"aktif\": lalu if saldo >= 5000:', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (15, 3, '3.5', '3.5 Boss Challenge: Sistem Evaluasi Siswa & KKM', '3-5-boss-challenge-evaluasi-kkm', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-trophy text-amber-600\"></i> 1. Uji Kompetensi Part 3: Sistem Akademik Rombel\n        </div>\n        <p>Saatnya membuktikan penguasaan logika dan percabangan Anda! Anda ditugaskan membangun program evaluasi kelulusan siswa SMK yang menggabungkan verifikasi multi-syarat: <strong>Nilai Ujian Akademik</strong>, <strong>Persentase Kehadiran Absensi</strong>, dan <strong>Predikat Sikap</strong>.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Kriteria &amp; Ketentuan Kelulusan\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Syarat Mutlak:</strong> Kehadiran harus &gt;= 85%. Jika kehadiran di bawah 85%, siswa langsung dinyatakan <em>\"TIDAK LULUS (Kehadiran Rendah)\"</em> tanpa melihat nilai.</li>\n            <li><strong>Jika Kehadiran Memenuhi Syarat:</strong>\n                <ul class=\"list-circle pl-5 mt-1 space-y-1 text-slate-500\">\n                    <li>Nilai &gt;= 85: <em>\"LULUS DENGAN PUJIAN (Predikat A)\"</em></li>\n                    <li>Nilai &gt;= 75: <em>\"LULUS MEMENUHI KKM (Predikat B)\"</em></li>\n                    <li>Nilai &lt; 75: <em>\"REMEDIAL AKADEMIK (Belum Capai KKM)\"</em></li>\n                </ul>\n            </li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Solusi\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>print(\"=== SISTEM EVALUASI SISWA WIKRAMA ===\")\nnama = input(\"Nama Siswa : \")\nnilai = float(input(\"Nilai Ujian : \"))\nabsen = float(input(\"Persentase Kehadiran (%): \"))\n\nprint(\"\\n\" + \"=\" * 36)\nprint(f\"Laporan Hasil Belajar: {nama}\")\nprint(f\"Nilai: {nilai:.1f} | Kehadiran: {absen:.1f}%\")\nprint(\"-\" * 36)\n\n# Evaluasi Berjenjang dengan Nested if\nif absen >= 85:\n    if nilai >= 85:\n        status = \"LULUS DENGAN PUJIAN (Predikat A)\"\n    elif nilai >= 75:\n        status = \"LULUS MEMENUHI KKM (Predikat B)\"\n    else:\n        status = \"REMEDIAL AKADEMIK (Belum KKM)\"\nelse:\n    status = \"TIDAK LULUS (Kehadiran di bawah 85%)\"\n\nprint(f\"Status Kelulusan : {status}\")\nprint(\"=\" * 36)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Membandingkan String dengan Angka\n        </div>\n        <p>Jangan lupa mengubah input kehadiran dan nilai dengan <code>float(...)</code>. Jika Anda membiarkannya berupa string teks, Python akan memicu <code>TypeError: \'&gt;=\' not supported between instances of \'str\' and \'int\'</code>.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Setelah menulis kode di editor PyLMS, lakukan uji coba dengan minimal 3 kasus data: (1) Siswa teladan (nilai 95, hadir 100%), (2) Siswa pintar tapi bolos (nilai 95, hadir 70%), dan (3) Siswa rajin tapi remidi (nilai 65, hadir 95%).</p>\n        </div>\n    </div>\n</div>', 'nilai = int(input())\nkehadiran = int(input())\nsikap = input()\n\n# Tulis logika kelulusan Anda di bawah', 5, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (15, 'Mengapa pemeriksaan kehadiran diposisikan pada blok if paling luar pada sistem evaluasi ini?', 'Karena kehadiran lebih sulit dihitung', 'Sebagai filter utama (gatekeeper), karena jika kehadiran tidak mencapai 85%, siswa otomatis tidak lulus tanpa perlu memeriksa nilai ujian', 'Karena nilai ujian tidak boleh berupa float', 'Agar program berjalan dalam perulangan tak terbatas', 'B', 'Dalam logika bisnis sekolah, kehadiran adalah syarat mutlak (prasyarat). Memeriksanya di gerbang awal membuat alur program lebih efisien dan jelas.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (15, 'Seorang siswa bernama Rizky memperoleh nilai ujian 98, namun persentase kehadirannya hanya 82%. Berdasarkan logika program di atas, apakah status akhir Rizky?', 'LULUS DENGAN PUJIAN (Predikat A)', 'LULUS MEMENUHI KKM (Predikat B)', 'TIDAK LULUS (Kehadiran di bawah 85%)', 'REMEDIAL AKADEMIK', 'C', 'Karena absen Rizky (82%) tidak memenuhi syarat absen >= 85%, program langsung meloncat ke blok else luar: \"TIDAK LULUS (Kehadiran di bawah 85%)\".', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (15, 'Bagaimanakah penulisan baris input yang aman jika pengguna memasukkan nilai desimal seperti 84.5?', 'nilai = int(input(\"Nilai: \"))', 'nilai = float(input(\"Nilai: \"))', 'nilai = str(input(\"Nilai: \"))', 'nilai = input(float(\"Nilai: \"))', 'B', 'Fungsi float(input(...)) dapat menerima nilai bilangan bulat maupun pecahan desimal tanpa memicu ValueError saat desimal dimasukkan.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (15, 'Tantangan 3.5 (Boss): Sistem Kelulusan Mandiri', 'Input baris 1: nilai (int), baris 2: kehadiran (int), baris 3: sikap (str). Jika nilai >= 75 dan kehadiran >= 80 dan (sikap == \"A\" or sikap == \"B\"), cetak \"STATUS: LULUS\". Jika tidak, cetak \"STATUS: TIDAK LULUS\".', 'nilai = int(input())\nkehadiran = int(input())\nsikap = input()\n\nif nilai >= 75 and kehadiran >= 80 and (sikap == \"A\" or sikap == \"B\"):\n    print(\"STATUS: LULUS\")\nelse:\n    print(\"STATUS: TIDAK LULUS\")', '[{\"name\": \"Uji Lulus\", \"inputs\": [\"85\", \"90\", \"A\"], \"expected_output\": \"STATUS: LULUS\"}, {\"name\": \"Uji Nilai Kurang\", \"inputs\": [\"70\", \"95\", \"A\"], \"expected_output\": \"STATUS: TIDAK LULUS\"}]', 'Perhatikan tanda kurung pada (sikap == \"A\" or sikap == \"B\") agar logika tidak tertukar.', 50);
INSERT INTO modules (part_number, title, slug, description, badge_name, badge_icon, order_index) VALUES (4, 'Perulangan (Loops & Iterasi)', 'perulangan-python', 'Menjalankan instruksi berulang kali dengan for loop, while loop, range, break, dan continue.', 'Loop Wizard', 'fa-arrows-rotate', 4);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (16, 4, '4.1', '4.1 Perulangan for & Fungsi range()', '4-1-for-loop-range', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Pemanggilan Absensi Berhitung di Lapangan\n        </div>\n        <p>Bayangkan seorang komandan upacara di sekolah memberi instruksi: <em>\"Siswa barisan depan, hitung dari 1 sampai 10, mulai!\"</em>. Siswa berurutan menyebutkan: \"Satu!\", \"Dua!\", hingga \"Sepuluh!\". Anda tidak perlu menulis perintah print sepuluh kali secara manual. Di Python, <strong>for loop</strong> bersama fungsi <code>range()</code> bertindak sebagai komandan otomatis yang mengulang perintah dengan jumlah putaran yang terukur!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Anatomi Fungsi range(start, stop, step)\n        </h4>\n        <p>Fungsi <code>range()</code> menghasilkan deret urutan angka. Memiliki 3 parameter penting:</p>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><code>range(stop)</code>: Mulai dari <code>0</code> hingga <code>stop - 1</code>. Misal <code>range(5)</code> menghasilkan <code>0, 1, 2, 3, 4</code> (tepat 5 putaran).</li>\n            <li><code>range(start, stop)</code>: Mulai dari <code>start</code> hingga <code>stop - 1</code>. Misal <code>range(1, 6)</code> menghasilkan <code>1, 2, 3, 4, 5</code>.</li>\n            <li><code>range(start, stop, step)</code>: Melompat sebesar <code>step</code>. Misal <code>range(2, 11, 2)</code> menghasilkan bilangan genap: <code>2, 4, 6, 8, 10</code>.</li>\n        </ul>\n        <div class=\"mt-2 p-2.5 bg-rose-50 border border-rose-200 rounded-xl text-rose-900 text-xs\">\n            <strong>Aturan Mutlak Python:</strong> Angka <code>stop</code> bersifat <em>eksklusif</em> (tidak diikutsertakan). Jika ingin berhenti di angka 10, batas stop harus ditulis <code>11</code>!\n        </div>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata: Tabel Perkalian Otomatis\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Mencetak Tabel Perkalian 7 (dari 1 x 7 sampai 10 x 7)\nangka = 7\nprint(f\"=== TABEL PERKALIAN {angka} ===\")\n\nfor i in range(1, 11):\n    hasil = i * angka\n    print(f\"{i} x {angka} = {hasil}\")\n\nprint(\"Perhitungan perkalian selesai!\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Kesalahan Off-by-One\n        </div>\n        <p>Kesalahan paling sering terjadi adalah saat programmer ingin mencetak angka 1 sampai 5, tetapi hanya menulis <code>range(1, 5)</code>. Program hanya akan berjalan sampai 4! Selalu tambahkan <code>+ 1</code> pada batas akhir bila ingin angka target ikut terproses.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Untuk membuat hitung mundur roket peluncuran, Anda cukup memberi nilai langkah negatif pada step: <code>range(10, 0, -1)</code>. Cobalah ketik di HP Anda!</p>\n        </div>\n    </div>\n</div>', '# Mencetak bilangan ganjil 1 sampai 9\nfor n in range(1, 10, 2):\n    print(n)', 1, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (16, 'Berapa kali blok kode di dalam \'for i in range(6):\' akan dieksekusi?', '5 kali (angka 0 sampai 4)', '6 kali (angka 0 sampai 5)', '7 kali (angka 0 sampai 6)', 'Tidak tentu', 'B', 'range(6) menghasilkan 6 angka berurutan dimulai dari 0 sampai 5. Jadi blok kode dijalankan tepat 6 kali.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (16, 'Perhatikan potongan kode perulangan berikut:\nfor x in range(3, 15, 4):\n    print(x, end=\" \")\nApakah output yang dicetak ke layar?', '3 7 11 15', '3 7 11', '3 6 9 12', '4 8 12', 'B', 'Mulai dari 3, lompat 4: 3 + 4 = 7, 7 + 4 = 11. Angka berikutnya adalah 15, namun karena 15 adalah batas stop (eksklusif), maka 15 tidak ikut dicetak. Output: 3 7 11.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (16, 'Seorang murid ingin mencetak angka 1 sampai 10:\nfor n in range(1, 10):\n    print(n)\nTernyata angka 10 tidak muncul. Bagaimanakah cara memperbaikinya?', 'Ubah range(1, 10) menjadi range(1, 11)', 'Ubah range(1, 10) menjadi range(0, 10)', 'Tambahkan step: range(1, 10, 2)', 'Ganti fungsi range() dengan int()', 'A', 'Batas akhir (stop) pada range() tidak diikutsertakan. Untuk mencetak hingga angka 10, batas akhir harus ditulis 11: range(1, 11).', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (16, 'Tantangan 4.1: Cetak Deret Angka Kelipatan 3', 'Gunakan for loop dan range untuk mencetak angka kelipatan 3 dari 3 sampai 9, masing-masing di baris baru (3, 6, 9).', 'for i in range(3, 10, 3):\n    print(i)', '[{\"name\": \"Cek Kelipatan 3\", \"expected_output\": \"3\n6\n9\"}]', 'Gunakan range(3, 10, 3)', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (17, 4, '4.2', '4.2 Perulangan while & Kondisi Terminasi', '4-2-while-loop-terminasi', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Pengisian Baterai Ponsel Pintar\n        </div>\n        <p>Saat Anda mencolokkan kabel charger ke HP Anda, sistem operasi menjalankan instruksi: <em>\"SELAMA (while) persentase baterai masih kurang dari 100%, terus alirkan arus listrik dan tampilkan animasi petir!\"</em>. Kita tidak tahu pasti berapa menit tepatnya baterai akan penuh, tetapi kita tahu PASTI kapan proses harus berhenti: saat baterai menyentuh angka 100%. Inilah hakikat perulangan <code>while</code>!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Tiga Pilar Wajib Perulangan while\n        </h4>\n        <p>Agar perulangan while berjalan teratur dan tidak macet, 3 elemen ini wajib ada:</p>\n        <ol class=\"list-decimal pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Inisialisasi (Start):</strong> Nilai awal variabel counter sebelum perulangan dimulai (misal: <code>baterai = 95</code>).</li>\n            <li><strong>Kondisi Terminasi:</strong> Pengujian logika yang dicek sebelum tiap putaran (misal: <code>while baterai &lt; 100:</code>).</li>\n            <li><strong>Pembaruan Nilai (Update/Increment):</strong> Perubahan nilai variabel di dalam loop agar mendekati kondisi berhenti (misal: <code>baterai += 1</code>).</li>\n        </ol>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata: Simulasi Pengisian Daya HP\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># 1. Inisialisasi awal\nbaterai = 96\nprint(\"Mengisi daya ponsel...\")\n\n# 2. Kondisi terminasi\nwhile baterai < 100:\n    print(f\"Status Baterai: {baterai}% [Sedang Mengisi]\")\n    # 3. Update nilai (increment)\n    baterai += 1\n\nprint(f\"Status Baterai: {baterai}% [BATERAI PENUH! Cabut Charger]\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Lupa Menuliskan Increment\n        </div>\n        <p>Jika Anda lupa menuliskan baris <code>baterai += 1</code>, maka nilai baterai akan selamanya bernilai 96. Akibatnya, kondisi <code>96 &lt; 100</code> akan selalu bernilai <code>True</code> dan program akan mencetak teks tanpa henti sampai memori browser Anda penuh!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Operator gabungan <code>+= 1</code> adalah singkatan dari <code>variabel = variabel + 1</code>. Sangat hemat ketikan saat menulis kode di layar sentuh ponsel!</p>\n        </div>\n    </div>\n</div>', 'cacah = 1\nwhile cacah <= 3:\n    print(\"Hitungan:\", cacah)\n    cacah += 1', 2, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (17, 'Kapan perulangan while di Python akan menghentikan eksekusinya?', 'Saat baris kode mencapai 100 baris', 'Saat kondisi logika yang diuji bernilai False', 'Saat pengguna menekan sembarang tombol', 'Setelah 10 putaran secara otomatis', 'B', 'Perulangan while mengevaluasi kondisi sebelum tiap putaran. Begitu kondisi bernilai False, loop akan langsung berhenti.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (17, 'Perhatikan program berikut:\nhitungan = 1\nwhile hitungan <= 3:\n    print(hitungan, end=\" \")\n    hitungan += 1\nApakah output yang dihasilkan?', '1 2 3', '1 2 3 4', '0 1 2 3', '1 1 1 ... tak terhingga', 'A', 'Putaran 1: cetak 1, hitungan jadi 2. Putaran 2: cetak 2, hitungan jadi 3. Putaran 3: cetak 3, hitungan jadi 4. Putaran 4: 4 <= 3 bernilai False, loop selesai.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (17, 'Apa yang terjadi pada kode berikut?\nangka = 5\nwhile angka > 0:\n    print(\"Hitung:\", angka)\n    # Tidak ada pengurangan angka', 'Program langsung berhenti tanpa output', 'Program mengalami Infinite Loop (perulangan tanpa henti) karena angka selamanya bernilai 5', 'Python otomatis menghentikan loop di angka 0', 'Muncul pesan TypeError', 'B', 'Karena nilai angka tidak pernah diubah (decrement), kondisi angka > 0 selalu True, menciptakan infinite loop.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (17, 'Tantangan 4.2: Hitung Mundur Meluncur', 'Gunakan perulangan while untuk mencetak angka dari 3 turun ke 1, lalu di baris terakhir cetak \"MELUNCUR!\".\nOutput:\n3\n2\n1\nMELUNCUR!', 'x = 3\nwhile x >= 1:\n    print(x)\n    x -= 1\nprint(\"MELUNCUR!\")', '[{\"name\": \"Cek Hitung Mundur\", \"expected_output\": \"3\n2\n1\nMELUNCUR!\"}]', 'Gunakan x = 3, while x >= 1: print(x); x -= 1', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (18, 4, '4.3', '4.3 Debugging: Mengatasi Infinite Loop', '4-3-debugging-infinite-loop', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Mobil Berputar di Bundaran Tanpa Pintu Keluar\n        </div>\n        <p>Bayangkan Anda mengemudi di bundaran lalu lintas kota, tetapi semua plang jalan keluar ditutup. Anda akan berputar-putar di lingkaran tersebut selamanya sampai bensin habis! Di dunia komputasi, situasi ini disebut <strong>Infinite Loop</strong>. Komputer terus mengeksekusi instruksi berulang-ulang dengan kecepatan miliaran siklus per detik hingga membuat aplikasi freeze atau browser HP Anda hang!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Penyebab Umum Infinite Loop\n        </h4>\n        <p>Infinite loop hampir selalu disebabkan oleh salah satu dari 3 kesalahan logika berikut:</p>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Arah Langkah Terbalik:</strong> Nilai awal <code>x = 1</code>, kondisi <code>while x &gt; 0:</code> tapi Anda menulis <code>x += 1</code> (nilainya semakin membesar menjauhi 0).</li>\n            <li><strong>Kondisi Pertidaksamaan Tepat:</strong> Menggunakan <code>while x != 10:</code> dengan kenaikan <code>x += 2</code> dimulai dari angka ganjil (<code>1, 3, 5, 7, 9, 11...</code>) sehingga angka 10 terlewati selamanya!</li>\n            <li><strong>Kondisi Statis:</strong> Menuliskan <code>while True:</code> tanpa menyertakan perintah <code>break</code> di dalamnya.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Cara Mencegah &amp; Memperbaiki\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># CONTOH KODE RUSAK (Jangan dijalankan):\n# n = 1\n# while n != 10:\n#     n += 2  # n akan jadi 1, 3, 5, 7, 9, 11 (melewati 10!)\n\n# PERBAIKAN AMAN:\n# Gunakan operator lebih kecil (<) alih-alih tidak sama dengan (!=)\nn = 1\nwhile n < 10:\n    print(f\"Langkah n: {n}\")\n    n += 2\n\nprint(f\"Selesai dengan aman di n = {n}\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Apa yang Harus Dilakukan Jika Terjebak Infinite Loop di HP?\n        </div>\n        <p>Jika Anda tidak sengaja memicu infinite loop di HP dan tombol browser tidak merespon:\n        <br>1. Jangan panik, ketuk tombol <strong>Stop / Interupt</strong> merah di samping tombol Run.\n        <br>2. Jika tab browser membeku (freeze), muat ulang (refresh) halaman peramban Anda.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Biasakan selalu menggunakan perbandingan rentang batas seperti <code>&lt;</code> atau <code>&lt;=</code> daripada <code>!=</code> agar perulangan tetap berhenti meski angka melompat melebihi batas.</p>\n        </div>\n    </div>\n</div>', '# Perbaiki kode di bawah agar tidak macet\ni = 1\ntotal = 0\nwhile i <= 4:\n    total += i\n    i += 1\nprint(\"Total:\", total)', 3, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (18, 'Mengapa kondisi \'while x != 10:\' dengan pembaruan \'x += 3\' yang dimulai dari x = 0 berbahaya?', 'Karena angka x bernilai desimal', 'Karena x akan bernilai 0, 3, 6, 9, 12... sehingga angka 10 terlewati dan loop tidak pernah berhenti', 'Karena operator += tidak didukung dalam while', 'Karena angka 10 adalah bilangan genap', 'B', 'Nilai x melompati angka 10 (dari 9 langsung ke 12), sehingga kondisi x != 10 akan selalu bernilai True selamanya.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (18, 'Perhatikan potongan kode berikut:\na = 10\nwhile a > 0:\n    a -= 4\nprint(a)\nBerapakah nilai akhir a yang dicetak setelah loop selesai?', '0', '-2', '2', 'Loop tidak pernah selesai', 'B', 'Putaran 1: a = 10 - 4 = 6. Putaran 2: a = 6 - 4 = 2. Putaran 3: a = 2 - 4 = -2. Pada putaran berikutnya -2 > 0 bernilai False, loop berhenti dan mencetak -2.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (18, 'Manakah strategi terbaik untuk mencegah risiko terjadinya infinite loop pada perulangan while?', 'Selalu menggunakan operator \'==\' pada kondisi terminasi', 'Memastikan ada variabel counter yang bergerak mendekati kondisi batas dan menggunakan batas batas perbandingan (< atau <=)', 'Tidak pernah menggunakan variabel di dalam kondisi', 'Menghapus tanda titik dua di akhir header while', 'B', 'Memastikan variabel counter diperbarui ke arah titik henti dan memakai perbandingan batas (< atau <=) adalah metode teraman.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (18, 'Tantangan 4.3: Perbaiki Akumulator While Loop', 'Perbaiki while loop agar menghitung total penjumlahan angka dari 1 sampai 5 (1+2+3+4+5 = 15) dan mencetak:\nJumlah: 15', 'i = 1\ntotal = 0\nwhile i <= 5:\n    total += i\n    i += 1\nprint(f\"Jumlah: {total}\")', '[{\"name\": \"Cek Jumlah 1 s/d 5\", \"expected_output\": \"Jumlah: 15\"}]', 'Pastikan while berjalan dari i = 1 sampai i <= 5 dan di dalam loop ada i += 1.', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (19, 4, '4.4', '4.4 Kontrol Loop: break & continue', '4-4-break-continue-pola', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Rem Darurat Kereta vs Antrian VIP Fast-Track\n        </div>\n        <p>Bayangkan dua situasi di perjalanan kereta komuter:\n        <br><strong>BREAK (Rem Darurat):</strong> Tiba-tiba ada pohon tumbang di rel depan. Masinis langsung menarik rem darurat; seluruh perjalanan kereta <strong>berhenti total saat itu juga</strong>.\n        <br><strong>CONTINUE (Fast-Track):</strong> Di antrian loket tiket, petugas melihat pengunjung dengan tiket VIP digital. Petugas berkata: <em>\"Bapak lewat jalur samping saja!\"</em>. Loket tidak tutup, petugas langsung <strong>meloncat ke pengunjung antrian berikutnya</strong>.\n        <br>Inilah dua pengendali sakti alur perulangan di Python!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Perbedaan Kunci: break vs continue\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-2 mt-2 text-slate-600\">\n            <li>\n                <strong>break:</strong> Menghentikan perulangan secara permanen dan langsung melompat keluar dari seluruh blok perulangan ke baris kode setelahnya.\n            </li>\n            <li>\n                <strong>continue:</strong> Menghentikan <em>putaran yang sedang berjalan</em>, melewatkan baris kode di bawahnya, dan langsung melompat ke awal putaran berikutnya.\n            </li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># CONTOH 1: CONTINUE (Melewatkan angka genap untuk cetak ganjil saja)\nprint(\"Daftar Angka Ganjil:\")\nfor i in range(1, 10):\n    if i % 2 == 0:\n        continue # Lompat langsung ke angka berikutnya jika genap\n    print(i, end=\" \") # Hanya tercetak: 1 3 5 7 9\n\nprint(\"\\n\" + \"-\" * 30)\n\n# CONTOH 2: BREAK (Mencari nomor undian pemenang lalu berhenti)\ntarget_juara = 7\nfor nomor in range(1, 20):\n    if nomor == target_juara:\n        print(f\"Nomor Pemenang {nomor} Ditemukan! Hentikan pencarian.\")\n        break\n    print(f\"Memeriksa kupon #{nomor}...\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Menulis break di Luar Perulangan\n        </div>\n        <p>Perintah <code>break</code> dan <code>continue</code> HANYA boleh ditulis di dalam struktur perulangan (<code>for</code> atau <code>while</code>). Menulis <code>break</code> di luar loop (misalnya di dalam <code>if</code> biasa tanpa ada loop di atasnya) akan menyebabkan <code>SyntaxError: \'break\' outside loop</code>.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Kombinasi <code>while True:</code> dengan kondisi <code>if input == \"selesai\": break</code> adalah pola arsitektur paling populer untuk membuat menu aplikasi interaktif di perangkat bergerak!</p>\n        </div>\n    </div>\n</div>', '# Mencetak pola segitiga bintang\nfor baris in range(1, 4):\n    print(\"*\" * baris)', 4, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (19, 'Pernyataan manakah yang paling akurat menggambarkan efek dari kata kunci \'continue\'?', 'Mengakhiri seluruh perulangan saat itu juga', 'Melewatkan sisa instruksi pada putaran saat ini dan langsung melanjutkan ke iterasi putaran berikutnya', 'Mengulangi putaran yang sama dari awal tanpa mengubah counter', 'Menghapus variabel di memori', 'B', 'continue tidak mematikan loop, melainkan hanya melompati sisa kode pada putaran aktif tersebut dan lanjut ke putaran berikutnya.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (19, 'Perhatikan program berikut:\nfor k in range(1, 6):\n    if k == 3:\n        continue\n    if k == 5:\n        break\n    print(k, end=\" \")\nApakah output yang dicetak?', '1 2 4', '1 2 3 4', '1 2 4 5', '1 2', 'A', 'k=1 dicetak. k=2 dicetak. k=3 dilewati oleh continue. k=4 dicetak. k=5 memicu break sehingga loop berhenti sebelum mencetak 5. Hasil: 1 2 4.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (19, 'Mengapa kode berikut memicu SyntaxError saat dijalankan?\nnilai = 80\nif nilai >= 75:\n    print(\"Lulus\")\n    break', 'Karena nilai bertipe integer', 'Karena kata kunci break hanya boleh digunakan di dalam struktur perulangan (for atau while)', 'Karena tidak ada blok else', 'Karena indentasi print salah', 'B', 'SyntaxError: \'break\' outside loop muncul karena break diletakkan di dalam percabangan if murni tanpa berada di dalam struktur perulangan.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (19, 'Tantangan 4.4: Cetak Pola Segitiga 3 Tingkat', 'Gunakan loop untuk mencetak pola bintang berikut:\n*\n**\n***', 'for i in range(1, 4):\n    print(\"*\" * i)', '[{\"name\": \"Cek Segitiga Bintang\", \"expected_output\": \"*\n**\n***\"}]', 'Gunakan print(\"*\" * i) di dalam loop range(1, 4)', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (20, 4, '4.5', '4.5 Boss Challenge: Simulator Kasir Perulangan', '4-5-boss-challenge-pin-atm', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-trophy text-amber-600\"></i> 1. Uji Kompetensi Part 4: Mesin Kasir Minimarket Cerdas\n        </div>\n        <p>Di Boss Challenge kali ini, Anda ditantang membuat simulator kasir toko yang dapat menerima input harga barang belanjaan secara terus-menerus tanpa batas menggunakan perulangan <code>while True</code> sampai kasir mengetikkan angka <code>0</code> untuk mengakhiri transaksi, lalu menghitung total belanja dan diskon!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Ketentuan &amp; Aturan Bisnis Kasir\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1 mt-2 text-slate-600\">\n            <li>Pengguna memasukkan harga barang satu per satu.</li>\n            <li>Jika harga diinput <code>0</code>, perulangan berhenti (<code>break</code>).</li>\n            <li>Jika pengguna tidak sengaja memasukkan angka negatif, abaikan dengan peringatan dan lanjutkan (<code>continue</code>).</li>\n            <li>Jika total belanja &gt;= Rp 100.000, berikan diskon otomatis sebesar 10%.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Solusi\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>print(\"=== SIMULATOR KASIR TOKO WIKRAMA ===\")\nprint(\"Ketik angka 0 jika belanjaan sudah selesai diinput.\\n\")\n\ntotal_belanja = 0\njumlah_item = 0\n\nwhile True:\n    harga = int(input(f\"Harga barang ke-{jumlah_item + 1}: Rp \"))\n    \n    # Syarat berhenti\n    if harga == 0:\n        break\n        \n    # Validasi harga negatif\n    if harga < 0:\n        print(\"[!] Harga tidak valid, ulangi input!\")\n        continue\n        \n    total_belanja += harga\n    jumlah_item += 1\n\n# Perhitungan diskon\ndiskon = 0\nif total_belanja >= 100000:\n    diskon = total_belanja * 0.10\n\ntotal_bayar = total_belanja - diskon\n\nprint(\"\\n\" + \"=\" * 32)\nprint(\"STRUK PEMBELIAN\")\nprint(f\"Total Item    : {jumlah_item} barang\")\nprint(f\"Subtotal      : Rp {total_belanja:,}\")\nprint(f\"Diskon (10%)  : Rp {int(diskon):,}\")\nprint(f\"TOTAL AKHIR   : Rp {int(total_bayar):,}\")\nprint(\"=\" * 32)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Meletakkan Inisialisasi Total di Dalam Loop\n        </div>\n        <p>Kesalahan fatal yang sering terjadi: meletakkan baris <code>total_belanja = 0</code> di DALAM blok perulangan <code>while</code>. Jika itu terjadi, nilai total belanja akan selalu ter-reset kembali ke 0 setiap kali barang baru dimasukkan!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Format ribuan rapi seperti <code>Rp 100,000</code> dapat dibuat instan dengan menambahkan <code>:,</code> di dalam f-string: <code>{total_bayar:,}</code>.</p>\n        </div>\n    </div>\n</div>', 'pin_benar = \"1234\"\npercobaan = 0\nberhasil = False\n\nwhile percobaan < 3:\n    pin_masuk = input()\n    percobaan += 1\n    if pin_masuk == pin_benar:\n        print(\"AKSES DITERIMA\")\n        berhasil = True\n        break\n\nif not berhasil:\n    print(\"KARTU DIBLOKIR\")', 5, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (20, 'Di manakah posisi yang benar untuk mendeklarasikan variabel akumulator seperti \'total_belanja = 0\'?', 'Di dalam perulangan while paling atas', 'Di luar SEBELUM perulangan while dimulai', 'Setelah kata kunci break', 'Di dalam blok continue', 'B', 'Variabel penampung akumulasi wajib diinisialisasi sebelum loop dimulai, agar nilainya terus bertambah dan tidak di-reset ulang ke 0 pada setiap putaran.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (20, 'Seorang kasir memasukkan harga berturut-turut: 40000, 70000, lalu 0. Berapakah total yang harus dibayar konsumen setelah mendapatkan diskon 10% (karena belanja >= 100.000)?', 'Rp 110.000', 'Rp 99.000', 'Rp 100.000', 'Rp 88.000', 'B', 'Total belanja = 40.000 + 70.000 = 110.000. Diskon 10% = 11.000. Total bayar = 110.000 - 11.000 = Rp 99.000.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (20, 'Perhatikan skenario di mana pengguna memasukkan angka negatif (-5000) lalu program mengeksekusi \'continue\'. Mengapa input negatif tersebut tidak diakumulasikan ke total_belanja?', 'Karena Python melarang angka negatif', 'Karena perintah continue langsung melompati baris total_belanja += harga dan kembali ke awal loop', 'Karena variabel harga otomatis terhapus', 'Karena program langsung memanggil break', 'B', 'Instruksi continue melewatkan baris-baris di bawahnya (yaitu akumulasi harga dan jumlah item), sehingga data tidak valid aman dilewati.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (20, 'Tantangan 4.5 (Boss): Simulator Keamanan PIN', 'Buat simulator PIN dengan PIN benar \"1234\" dan maksimal 3x coba. Jika benar cetak \"AKSES DITERIMA\", jika 3x gagal cetak \"KARTU DIBLOKIR\".', 'pin_benar = \"1234\"\npercobaan = 0\nberhasil = False\nwhile percobaan < 3:\n    pin_masuk = input()\n    percobaan += 1\n    if pin_masuk == pin_benar:\n        print(\"AKSES DITERIMA\")\n        berhasil = True\n        break\nif not berhasil:\n    print(\"KARTU DIBLOKIR\")', '[{\"name\": \"PIN Langsung Benar\", \"inputs\": [\"1234\"], \"expected_output\": \"AKSES DITERIMA\"}, {\"name\": \"PIN 3x Salah\", \"inputs\": [\"0000\", \"1111\", \"2222\"], \"expected_output\": \"KARTU DIBLOKIR\"}]', 'Gunakan while percobaan < 3: dan periksa input setiap putaran.', 50);
INSERT INTO modules (part_number, title, slug, description, badge_name, badge_icon, order_index) VALUES (5, 'Struktur Data (List & Dictionary)', 'struktur-data', 'Menyimpan dan mengelola kumpulan data majemuk dengan List, Tuple, Set, dan Dictionary.', 'Data Alchemist', 'fa-boxes-stacked', 5);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (21, 5, '5.1', '5.1 List: Indexing & Slicing', '5-1-list-indexing-slicing', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Lemari Laci Bernomor Urut\n        </div>\n        <p>Bayangkan Anda memiliki lemari laci berkas di ruang tata usaha. Setiap laci dapat menyimpan dokumen apa saja, dan di bagian depan laci tertempel stiker nomor urut: <code>0, 1, 2, 3, ...</code>. Jika ingin mengambil dokumen di laci teratas, Anda cukup menyebut nomor <code>0</code>. Di Python, <strong>List</strong> adalah lemari laci serbaguna yang bisa menyimpan ratusan data sekaligus dalam satu wadah rapi!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Karakteristik, Indexing &amp; Slicing\n        </h4>\n        <p>List didefinisikan menggunakan <strong>tanda kurung siku [ ]</strong> dengan pemisah koma antar elemen:</p>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Zero-based Indexing:</strong> Indeks elemen pertama SELALU dimulai dari angka <code>0</code>, bukan 1! Elemen kedua adalah indeks 1, dan seterusnya.</li>\n            <li><strong>Negative Indexing:</strong> Python mengizinkan indeks negatif untuk menghitung mundur dari belakang. Indeks <code>-1</code> selalu menunjuk elemen paling terakhir!</li>\n            <li><strong>Slicing [start:stop]:</strong> Memotong sebagian elemen list. Elemen pada batas <code>stop</code> tidak diikutsertakan.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Membuat list bahasa pemrograman\nbahasa = [\"Python\", \"JavaScript\", \"PHP\", \"Kotlin\", \"Java\"]\n\n# Mengakses elemen tunggal\nprint(\"Elemen Pertama [0] :\", bahasa[0])  # Python\nprint(\"Elemen Terakhir [-1]:\", bahasa[-1]) # Java\n\n# Mengambil potongan (slicing) 3 elemen pertama\nfavorit = bahasa[0:3]\nprint(\"Tiga Bahasa Favorit:\", favorit)    # [\'Python\', \'JavaScript\', \'PHP\']\n\n# Mengetahui total item dengan len()\nprint(\"Jumlah bahasa yang tersedia:\", len(bahasa))</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Mengira Indeks Mulai dari 1\n        </div>\n        <p>Jika list memiliki 3 elemen (<code>[\"A\", \"B\", \"C\"]</code>) dan Anda memanggil <code>data[1]</code>, Anda BUKAN mendapatkan huruf \"A\", melainkan huruf \"B\"! Ingat selalu: laci pertama adalah laci nomor <strong>0</strong>.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Tombol <code>[ ]</code> tersedia langsung di bilah toolbar PyLMS. Anda cukup mengetuk tombol tersebut untuk membuat sepasang kurung siku tanpa repot mencari di keyboard HP.</p>\n        </div>\n    </div>\n</div>', 'bahasa = [\"Python\", \"HTML\", \"CSS\", \"JavaScript\"]\nprint(\"Bahasa pertama :\", bahasa[0])\nprint(\"Bahasa terakhir:\", bahasa[-1])\nprint(\"Jumlah bahasa  :\", len(bahasa))', 1, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (21, 'Berapakah nomor indeks untuk mengakses elemen pertama dalam list di Python?', '1', '0', '-1', 'None', 'B', 'Sistem indeks list di Python menganut zero-based indexing, di mana elemen pertama selalu menempati indeks 0.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (21, 'Perhatikan potongan kode slicing berikut:\nkendaraan = [\"Motor\", \"Mobil\", \"Sepeda\", \"Bus\", \"Kereta\"]\nsub = kendaraan[1:4]\nprint(sub)\nApakah output yang dihasilkan?', '[\'Motor\', \'Mobil\', \'Sepeda\']', '[\'Mobil\', \'Sepeda\', \'Bus\']', '[\'Mobil\', \'Sepeda\', \'Bus\', \'Kereta\']', '[\'Motor\', \'Kereta\']', 'B', 'Slicing [1:4] mengambil indeks 1 (\"Mobil\"), 2 (\"Sepeda\"), dan 3 (\"Bus\"). Indeks ke-4 (\"Kereta\") tidak diikutsertakan karena batas stop eksklusif.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (21, 'Manakah cara paling ringkas dan aman untuk mengambil elemen TERAKHIR dari list data tanpa perlu menghitung panjang list secara manual?', 'data[last]', 'data[-1]', 'data[end]', 'data[100]', 'B', 'Python mendukung negative indexing, di mana indeks -1 secara otomatis menunjuk ke elemen paling ujung/terakhir dari suatu sequence/list.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (21, 'Tantangan 5.1: Mengakses Elemen List', 'Diberikan list data = [\"Merah\", \"Kuning\", \"Hijau\"]. Cetak elemen pertama dan terakhir dalam format:\nAwal: Merah\nAkhir: Hijau', 'data = [\"Merah\", \"Kuning\", \"Hijau\"]\nprint(f\"Awal: {data[0]}\")\nprint(f\"Akhir: {data[-1]}\")', '[{\"name\": \"Cek Awal dan Akhir\", \"expected_output\": \"Awal: Merah\nAkhir: Hijau\"}]', 'Gunakan data[0] dan data[-1]', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (22, 5, '5.2', '5.2 Manipulasi List: append(), pop(), sort()', '5-2-manipulasi-list', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Gerbong Kereta Logistik\n        </div>\n        <p>Bayangkan rangkaian gerbong kereta barang di stasiun:\n        <br>- Menautkan satu gerbong baru di ujung paling belakang dinamakan <strong>append()</strong>.\n        <br>- Melepas gerbong terakhir untuk dibongkar muatannya dinamakan <strong>pop()</strong>.\n        <br>- Menyusun ulang seluruh gerbong dari muatan teringan ke terberat dinamakan <strong>sort()</strong>.\n        <br>List di Python bersifat <em>mutable</em> (bisa diubah, ditambah, atau dikurangi sesuka hati kapan saja!).</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Method Manipulasi List Populer\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><code>list.append(nilai)</code>: Menambahkan nilai baru ke posisi paling akhir list.</li>\n            <li><code>list.insert(indeks, nilai)</code>: Menyisipkan nilai pada posisi indeks tertentu.</li>\n            <li><code>list.pop()</code>: Menghapus dan mengambil elemen paling belakang. Jika diberi argumen <code>list.pop(0)</code>, ia menghapus elemen pada indeks tersebut.</li>\n            <li><code>list.remove(nilai)</code>: Menghapus elemen pertama yang cocok dengan nilai tersebut.</li>\n            <li><code>list.sort()</code>: Mengurutkan list secara langsung (ascending: A-Z atau angka terkecil ke terbesar).</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata: Manajemen Antrian Siswa\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>antrian = [\"Fadhil\", \"Siti\", \"Budi\"]\nprint(\"Antrian Awal :\", antrian)\n\n# Siswa baru mendaftar di antrian belakang\nantrian.append(\"Zahra\")\nprint(\"Setelah Tambah:\", antrian)\n\n# Pasien/Siswa pertama dilayani dan keluar dari antrian\nyang_dilayani = antrian.pop(0)\nprint(f\"Sedang Melayani: {yang_dilayani}\")\nprint(\"Sisa Antrian   :\", antrian)\n\n# Mengurutkan sisa antrian sesuai abjad\nantrian.sort()\nprint(\"Antrian Terurut Abjad:\", antrian)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Menulis data = data.append(...)\n        </div>\n        <p>Method seperti <code>append()</code> dan <code>sort()</code> bekerja secara <em>in-place</em> (mengubah list aslinya langsung) dan mengembalikan nilai <code>None</code>. Jika Anda menulis <code>data = data.append(10)</code>, variabel data Anda akan berubah menjadi <strong>None</strong> dan isi list lenyap!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Cukup panggil <code>data.append(x)</code> tanpa tanda penugasan sama dengan (<code>=</code>) di depannya.</p>\n        </div>\n    </div>\n</div>', 'angka = [40, 10, 30, 20]\nangka.append(50)\nangka.sort()\nprint(\"List terurut:\", angka)', 2, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (22, 'Method manakah yang digunakan untuk menambahkan elemen baru ke posisi paling akhir dari sebuah list?', 'list.push()', 'list.append()', 'list.add()', 'list.insert_end()', 'B', 'Di Python, append() adalah method resmi bawaan list untuk menambahkan satu item ke ujung akhir list.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (22, 'Perhatikan program berikut:\nangka = [7, 2, 9]\nangka.append(4)\nangka.sort()\nprint(angka)\nApakah output yang dihasilkan?', '[7, 2, 9, 4]', '[2, 4, 7, 9]', '[9, 7, 4, 2]', 'None', 'B', 'angka.append(4) menjadikan list [7, 2, 9, 4]. Kemudian method sort() mengurutkan elemen dari terkecil ke terbesar menjadi [2, 4, 7, 9].', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (22, 'Seorang murid menulis kode:\nnilai = [80, 90, 75]\nnilai = nilai.append(85)\nprint(nilai)\nMengapa output di terminal mencetak \'None\'?', 'Karena angka 85 tidak valid', 'Karena method append() memodifikasi list secara langsung dan tidak mengembalikan nilai (return None)', 'Karena fungsi print salah', 'Karena list nilai sudah penuh', 'B', 'append() melakukan in-place modification. Nilai baliknya adalah None. Dengan menulis nilai = nilai.append(85), variabel nilai ditimpa dengan None.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (22, 'Tantangan 5.2: Tambah & Urutkan Nilai', 'Buat list nilai = [80, 65, 90]. Tambahkan angka 75 ke dalam list menggunakan append(), urutkan dengan sort(), lalu cetak nilai terkecil (indeks ke-0):\nTerkecil: 65', 'nilai = [80, 65, 90]\nnilai.append(75)\nnilai.sort()\nprint(f\"Terkecil: {nilai[0]}\")', '[{\"name\": \"Cek Nilai Terkecil\", \"expected_output\": \"Terkecil: 65\"}]', 'append 75, lalu sort(), lalu print(f\"Terkecil: {nilai[0]}\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (23, 5, '5.3', '5.3 Debugging: Mengatasi IndexError', '5-3-debugging-index-error', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Membuka Laci Nomor 10 di Lemari 3 Laci\n        </div>\n        <p>Bayangkan Anda menyuruh teman Anda: <em>\"Tolong ambilkan map di laci nomor 10!\"</em>. Teman Anda menatap lemari dengan bingung karena lemari tersebut hanya memiliki 3 laci (laci 0, 1, dan 2). Teman Anda akan memprotes: \"Laci nomor 10 tidak ada!\". Di Python, situasi ini memicu <strong>IndexError: list index out of range</strong>!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Mengapa IndexError Bisa Terjadi?\n        </h4>\n        <p>IndexError terjadi ketika kode program berusaha mengakses indeks yang berada di luar jangkauan ukuran list:</p>\n        <div class=\"p-3 bg-slate-900 text-slate-100 rounded-xl font-mono text-xs\">\n            skor = [85, 90, 78] # len(skor) adalah 3.<br>\n            # Indeks yang sah HANYA: 0, 1, 2<br>\n            skor[3] # CRASH! IndexError: list index out of range\n        </div>\n        <p class=\"mt-2 text-xs\">Ingat aturan emas: <strong>Indeks maksimum yang valid adalah selalu len(list) - 1</strong>.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Cara Mencegah &amp; Menangani IndexError\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>daftar_siswa = [\"Ahmad\", \"Budi\", \"Citra\"]\n\ntarget_indeks = int(input(\"Pilih nomor indeks (0-2): \"))\n\n# Metode 1: Pemeriksaan batas aman menggunakan len()\nif 0 <= target_indeks < len(daftar_siswa):\n    print(f\"Siswa pada indeks {target_indeks}: {daftar_siswa[target_indeks]}\")\nelse:\n    print(f\"Error: Indeks {target_indeks} di luar batas! Maksimal adalah {len(daftar_siswa)-1}\")\n\n# Metode 2: Menggunakan for item in list (Tanpa perlu repot urusan indeks)\nprint(\"\\nSeluruh Siswa:\")\nfor siswa in daftar_siswa:\n    print(\"-\", siswa)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Perulangan for i in range(len(list) + 1)\n        </div>\n        <p>Banyak siswa pemula menulis <code>for i in range(len(data) + 1):</code> karena mengira butuh menambah satu. Perulangan akan berhasil di putaran-putaran awal, lalu tiba-tiba meledak (crash) di putaran paling akhir saat menyentuh <code>data[len(data)]</code>!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Gunakan perulangan langsung: <code>for item in my_list:</code>. Pola ini 100% bebas dari risiko IndexError dan jauh lebih bersih diketik di ponsel.</p>\n        </div>\n    </div>\n</div>', 'siswa = [\"Ahmad\", \"Bella\", \"Citra\"]\n# Perbaiki agar tidak IndexError\nfor i in range(len(siswa)):\n    print(f\"Siswa #{i+1}: {siswa[i]}\")', 3, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (23, 'Jika sebuah list memiliki 4 elemen, berapakah nomor indeks maksimum yang sah untuk diakses?', '4', '3', '5', 'Tidak terbatas', 'B', 'Karena indeks dimulai dari 0, list dengan 4 elemen memiliki indeks yang sah: 0, 1, 2, dan 3. Indeks maksimumnya adalah len - 1 = 3.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (23, 'Perhatikan potongan kode berikut:\nkota = [\"Jakarta\", \"Bandung\", \"Surabaya\"]\nprint(kota[3])\nApakah pesan error yang akan muncul di layar terminal?', 'KeyError: 3', 'IndexError: list index out of range', 'ValueError: invalid list', 'TypeError: list indices must be integers', 'B', 'List hanya memiliki elemen hingga indeks 2. Memanggil kota[3] melebihi batas jangkauan list sehingga menimbulkan IndexError.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (23, 'Manakah cara perulangan yang paling aman untuk mencetak seluruh isi list data tanpa risiko menimbulkan IndexError?', 'for i in range(len(data) + 1): print(data[i])', 'for item in data: print(item)', 'for i in range(100): print(data[i])', 'while len(data) >= 0: print(data[0])', 'B', 'Iterasi langsung `for item in data:` mengekstrak elemen satu per satu dari koleksi secara otomatis tanpa manipulasi angka indeks, sehingga bebas IndexError.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (23, 'Tantangan 5.3: Iterasi List yang Aman', 'Diberikan list skor = [10, 20, 30]. Perbaiki perulangan agar mencetak ketiga elemen tersebut secara aman baris demi baris.', 'skor = [10, 20, 30]\nfor s in skor:\n    print(s)', '[{\"name\": \"Cek 3 Baris Skor\", \"expected_output\": \"10\n20\n30\"}]', 'Gunakan for s in skor: print(s)', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (24, 5, '5.4', '5.4 Dictionary: Pasangan Key - Value', '5-4-dictionary-key-value', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Buku Kontak Telepon di Smartphone\n        </div>\n        <p>Di aplikasi kontak telepon smartphone Anda, Anda tidak mencari nomor teman dengan menghafal \"Kontak nomor urut 37\". Anda mencari berdasarkan <strong>Nama Teman (Key / Kunci)</strong>, lalu aplikasi akan menampilkan <strong>Nomor Telepon (Value / Nilai)</strong> miliknya. Di Python, struktur data ini disebut <strong>Dictionary</strong> (kamus pasangan Key-Value)!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Sintaks &amp; Cara Mengakses Dictionary\n        </h4>\n        <p>Dictionary dibuat menggunakan kurung kurawal <code>{ }</code>, dengan format <code>kunci : nilai</code>:</p>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Key (Kunci):</strong> Harus unik (tidak boleh ada kunci kembar) dan biasanya berupa String teks.</li>\n            <li><strong>Value (Nilai):</strong> Boleh berupa tipe data apa saja: string, integer, float, boolean, bahkan list!</li>\n            <li><strong>Akses Nilai:</strong> Menggunakan <code>dict[key]</code> atau metode aman <code>dict.get(key, nilai_default)</code>.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata: Data Siswa Terstruktur\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Mendefinisikan profil siswa SMK\nsiswa = {\n    \"nis\": \"123098\",\n    \"nama\": \"Ahmad Fadhil\",\n    \"jurusan\": \"Pengembangan Perangkat Lunak (PPLG)\",\n    \"nilai\": 88.5,\n    \"aktif\": True\n}\n\n# Mengakses data\nprint(\"Nama Siswa :\", siswa[\"nama\"])\nprint(\"Jurusan    :\", siswa[\"jurusan\"])\n\n# Memperbarui data yang ada\nsiswa[\"nilai\"] = 92.0\n\n# Menambahkan key-value baru\nsiswa[\"peringkat\"] = 1\n\n# Mengakses dengan get() aman (tidak akan crash jika key tidak ada)\ntelepon = siswa.get(\"no_hp\", \"Nomor Belum Terdaftar\")\nprint(\"Kontak HP  :\", telepon)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: KeyError Saat Memanggil Key Gaib\n        </div>\n        <p>Jika Anda memanggil <code>siswa[\"alamat\"]</code> padahal kunci \"alamat\" tidak ada di dictionary, program akan langsung crash dengan <code>KeyError: \'alamat\'</code>. Solusinya: selalu gunakan method <code>.get(\"alamat\", \"Default\")</code> jika Anda tidak yakin kunci tersebut pasti ada.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Tanda petik dan kurung kurawal <code>{ }</code> serta titik dua <code>:</code> dapat Anda ketik secara beruntun menggunakan tombol pintas simbol di PyLMS.</p>\n        </div>\n    </div>\n</div>', 'profil = {\n    \"nama\": \"Siti\",\n    \"kelas\": \"X-1\",\n    \"skor\": 95\n}\n\nprint(\"Nama:\", profil[\"nama\"])\nprint(\"Skor:\", profil[\"skor\"])', 4, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (24, 'Struktur apakah yang digunakan untuk menyimpan pasangan data pada tipe Dictionary di Python?', 'Index - Content', 'Key - Value (Kunci - Nilai)', 'Row - Column', 'Variable - Function', 'B', 'Dictionary di Python selalu menyimpan data dalam pasangan Key - Value yang dipisahkan oleh tanda titik dua (:).', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (24, 'Perhatikan program berikut:\nbiodata = {\"nama\": \"Rian\", \"usia\": 16}\nbiodata[\"usia\"] = 17\nbiodata[\"kelas\"] = \"XI RPL\"\nprint(len(biodata))\nBerapakah panjang (jumlah item) dictionary biodata sekarang?', '2', '3', '4', 'SyntaxError', 'B', 'Awalnya memiliki 2 key (\"nama\", \"usia\"). biodata[\"usia\"] = 17 hanya mengubah nilai yang ada. biodata[\"kelas\"] menambah 1 key baru. Total key menjadi 3.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (24, 'Bagaimanakah cara mengambil nilai dari kunci \"email\" pada dictionary akun tanpa risiko memicu KeyError jika kunci tersebut belum dibuat?', 'akun[\"email\"]', 'akun.get(\"email\", \"Tidak Ada\")', 'akun.find(\"email\")', 'akun.pop(\"email\")', 'B', 'Method dict.get(key, default) mengembalikan nilai kunci jika ada, atau nilai default jika kunci tidak ditemukan, tanpa menimbulkan KeyError.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (24, 'Tantangan 5.4: Membuat Profil Dictionary', 'Buat dictionary dengan key \"produk\" bernilai \"Buku\" dan key \"harga\" bernilai 15000. Cetak:\nProduk: Buku - Rp 15000', 'item = {\"produk\": \"Buku\", \"harga\": 15000}\nprint(f\"Produk: {item[\'produk\']} - Rp {item[\'harga\']}\")', '[{\"name\": \"Cek Profil Produk\", \"expected_output\": \"Produk: Buku - Rp 15000\"}]', 'Gunakan item[\"produk\"] dan item[\"harga\"] di dalam f-string.', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (25, 5, '5.5', '5.5 Boss Challenge: Analisis Nilai Rombel', '5-5-boss-challenge-analisis-nilai', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-trophy text-amber-600\"></i> 1. Uji Kompetensi Part 5: Rekapitulasi Rapor Digital Kelas\n        </div>\n        <p>Di Boss Challenge ini, Anda akan menggabungkan kekuatan <strong>List</strong> dan <strong>Dictionary</strong> untuk membangun sistem analisis nilai satu rombel kelas. Program akan menghitung statistik penting: <strong>Nilai Tertinggi</strong>, <strong>Nilai Terendah</strong>, <strong>Rata-Rata Kelas</strong>, serta mencantumkan nama siswa peraih juara 1!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Fungsi Bawaan Statistik Python\n        </h4>\n        <p>Untuk mengolah data numerik dalam list, Python menyediakan fungsi bawaan super efisien:</p>\n        <ul class=\"list-disc pl-5 space-y-1 mt-2 text-slate-600\">\n            <li><code>sum(list_angka)</code>: Menghitung total jumlah seluruh angka.</li>\n            <li><code>max(list_angka)</code>: Mengambil nilai terbesar/tertinggi.</li>\n            <li><code>min(list_angka)</code>: Mengambil nilai terkecil/terendah.</li>\n            <li><code>len(list)</code>: Menghitung total banyaknya data.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Solusi\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Data Nilai Siswa (List of Dictionaries)\nkelas_pplg = [\n    {\"nama\": \"Ahmad Fadhil\", \"nilai\": 88.0},\n    {\"nama\": \"Siti Nurhaliza\", \"nilai\": 95.5},\n    {\"nama\": \"Budi Pratama\", \"nilai\": 74.0},\n    {\"nama\": \"Zahra Amalia\", \"nilai\": 91.0}\n]\n\n# Ekstrak seluruh nilai ke dalam list tunggal\ndaftar_nilai = [siswa[\"nilai\"] for siswa in kelas_pplg]\n\ntotal_siswa = len(kelas_pplg)\nnilai_tertinggi = max(daftar_nilai)\nnilai_terendah = min(daftar_nilai)\nrata_rata = sum(daftar_nilai) / total_siswa\n\nprint(\"=== REKAP NILAI KELAS PPLG WIKRAMA ===\")\nprint(f\"Total Siswa Terdaftar : {total_siswa} orang\")\nprint(f\"Rata-Rata Kelas       : {rata_rata:.2f}\")\nprint(f\"Nilai Tertinggi       : {nilai_tertinggi:.1f}\")\nprint(f\"Nilai Terendah        : {nilai_terendah:.1f}\")\nprint(\"-\" * 38)\n\n# Menemukan siswa peraih nilai tertinggi\nfor siswa in kelas_pplg:\n    if siswa[\"nilai\"] == nilai_tertinggi:\n        print(f\"Juara Kelas : {siswa[\\\"nama\\\"]} (Nilai {siswa[\\\"nilai\\\"]})\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Membagi dengan Nol pada List Kosong\n        </div>\n        <p>Jika list data tidak memiliki elemen sama sekali (<code>len == 0</code>), rumus <code>sum(data) / len(data)</code> akan menyebabkan <strong>ZeroDivisionError</strong>. Selalu pastikan jumlah siswa lebih besar dari 0 sebelum melakukan pembagian rata-rata!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Pola struktur data <em>List of Dictionaries</em> seperti contoh di atas adalah standar yang persis digunakan dalam komunikasi API dan database web modern (format JSON).</p>\n        </div>\n    </div>\n</div>', 'daftar_nilai = []\nfor _ in range(3):\n    daftar_nilai.append(int(input()))\n\n# Hitung rata-rata dan tertinggi', 5, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (25, 'Fungsi bawaan Python manakah yang paling cepat untuk mencari nilai terbesar dari sekumpulan angka di dalam list?', 'highest()', 'max()', 'top()', 'sort_max()', 'B', 'Fungsi bawaan max(iterable) mengembalikan elemen dengan nilai terbesar dalam suatu koleksi data.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (25, 'Diberikan list nilai = [70, 80, 90, 100]. Berapakah nilai rata-rata dari list tersebut jika dihitung dengan rumus sum(nilai) / len(nilai)?', '80.0', '85.0', '90.0', '340.0', 'B', 'sum(nilai) = 70 + 80 + 90 + 100 = 340. len(nilai) = 4. Maka 340 / 4 = 85.0.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (25, 'Mengapa programmer harus memeriksa apakah panjang list lebih dari 0 sebelum menghitung rata-rata?', 'Agar tipe data tidak berubah', 'Untuk mencegah terjadinya ZeroDivisionError jika list ternyata kosong (panjang 0)', 'Karena list kosong tidak bisa di-print', 'Agar fungsi max() menghasilkan nilai default', 'B', 'Jika list kosong, len(list) bernilai 0. Membagi apapun dengan 0 akan langsung memicu ZeroDivisionError yang menghentikan program.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (25, 'Tantangan 5.5 (Boss): Analisis Nilai Siswa', 'Ambil 3 angka input integer ke dalam list. Cetak 2 baris:\nRata-rata: <nilai desimal>\nTertinggi: <nilai>', 'daftar_nilai = [int(input()), int(input()), int(input())]\nprint(f\"Rata-rata: {sum(daftar_nilai)/len(daftar_nilai)}\")\nprint(f\"Tertinggi: {max(daftar_nilai)}\")', '[{\"name\": \"Uji 80, 90, 100\", \"inputs\": [\"80\", \"90\", \"100\"], \"expected_output\": \"Rata-rata: 90.0\nTertinggi: 100\"}]', 'Gunakan sum() dan max()', 50);
INSERT INTO modules (part_number, title, slug, description, badge_name, badge_icon, order_index) VALUES (6, 'Fungsi & Modularitas Kode', 'fungsi-modularitas', 'Merapikan kode agar reusable menggunakan fungsi def, parameter, return, dan variable scope.', 'Function Architect', 'fa-cubes', 6);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (26, 6, '6.1', '6.1 Mendefinisikan Fungsi dengan def', '6-1-def-parameter', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Resep Rahasia yang Disimpan di Buku Catatan\n        </div>\n        <p>Bayangkan Anda seorang juru masak di restoran. Setiap kali ada pesanan \"Nasi Goreng Spesial\", Anda tidak perlu menulis ulang 20 langkah bumbu dari nol di selembar kertas baru. Anda cukup membuka resep bernama <strong>masak_nasi_goreng()</strong> yang sudah tersimpan rapi, lalu menjalankannya. Di pemrograman, <strong>Fungsi</strong> adalah resep kode yang kita bungkus sekali agar bisa dipanggil berkali-kali kapan pun dibutuhkan!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Anatomi Kata Kunci def &amp; Parameter\n        </h4>\n        <p>Fungsi dibuat menggunakan kata kunci <code>def</code> (singkatan dari <em>define</em>), diikuti nama fungsi, tanda kurung parameter, dan titik dua:</p>\n        <pre class=\"bg-slate-900 text-slate-100 p-3 rounded-xl font-mono text-xs\"><code>def nama_fungsi(parameter1, parameter2):\n    # Blok kode yang akan dijalankan saat fungsi dipanggil (terindentasi)\n    instruksi_kode</code></pre>\n        <p class=\"mt-2 text-xs\">Prinsip utama rekayasa perangkat lunak yang diwujudkan fungsi adalah <strong>DRY (Don\'t Repeat Yourself)</strong>: jangan pernah menuliskan kode yang sama berulang kali!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Mendefinisikan fungsi salam pembuka\ndef sapa_siswa(nama, jurusan):\n    print(\"=\" * 35)\n    print(f\"Halo, Selamat Datang {nama}!\")\n    print(f\"Kompetensi Keahlian : {jurusan}\")\n    print(\"=\" * 35)\n\n# Memanggil fungsi berkali-kali dengan data berbeda\nsapa_siswa(\"Ahmad Fadhil\", \"PPLG (RPL)\")\nsapa_siswa(\"Siti Nurhaliza\", \"Teknik Komputer & Jaringan\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Memanggil Fungsi Sebelum Didefinisikan\n        </div>\n        <p>Karena interpreter Python membaca kode dari atas ke bawah, Anda TIDAK BISA memanggil fungsi di baris atas jika blok <code>def</code>-nya baru ditulis di baris bawah. Hal itu akan memicu <code>NameError: name \'sapa_siswa\' is not defined</code>. Selalu tempatkan definisi fungsi di bagian atas file kode Anda!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Ketik <code>def</code> dengan mudah menggunakan tombol pintas di bilah simbol PyLMS. Pastikan selalu ada tanda titik dua <code>:</code> di akhir baris deklarasi fungsi.</p>\n        </div>\n    </div>\n</div>', 'def perkenalan(nama, rombel):\n    print(f\"Halo, saya {nama} dari {rombel}.\")\n\nperkenalan(\"Rian\", \"PPLG X-1\")', 1, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (26, 'Kata kunci (keyword) resmi apakah yang digunakan untuk mendeklarasikan fungsi baru di Python?', 'function', 'func', 'def', 'define', 'C', 'Di Python, kata kunci resmi untuk membuat atau mendefinisikan fungsi adalah \'def\'.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (26, 'Perhatikan program berikut:\ndef hitung_luas_persegi(sisi):\n    print(sisi * sisi)\n\nhitung_luas_persegi(6)\nApakah output yang dihasilkan kode di atas?', '12', '36', '6', 'TypeError', 'B', 'Parameter sisi diisi argumen 6. Di dalam fungsi dieksekusi print(6 * 6), menghasilkan output 36.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (26, 'Mengapa kode berikut menghasilkan NameError saat dijalankan?\ntampilkan_pesan()\n\ndef tampilkan_pesan():\n    print(\"Halo Dunia\")', 'Karena fungsi tidak memiliki parameter', 'Karena pemanggilan fungsi ditulis sebelum blok fungsi itu sendiri didefinisikan dengan def', 'Karena nama fungsi mengandung underscore', 'Karena fungsi tidak memiliki return', 'B', 'Python mengeksekusi kode secara linier baris demi baris dari atas. Fungsi harus didefinisikan terlebih dahulu sebelum dapat dipanggil.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (26, 'Tantangan 6.1: Fungsi Cetak Header', 'Buat fungsi bernama cetak_header(judul) yang mencetak \"=== JUDUL ===\". Kemudian panggil fungsi tersebut dengan argumen \"PYTHON\".', 'def cetak_header(judul):\n    print(f\"=== {judul} ===\")\n\ncetak_header(\"PYTHON\")', '[{\"name\": \"Cek Header Python\", \"expected_output\": \"=== PYTHON ===\"}]', 'def cetak_header(judul): print(f\"=== {judul} ===\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (27, 6, '6.2', '6.2 Nilai Kembalian (return) vs print()', '6-2-return-vs-print', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Koki Restoran vs Papan Pengumuman\n        </div>\n        <p>Bayangkan Anda memesan jus jeruk di kafe:\n        <br>- <strong>Fungsi dengan return:</strong> Koki memeras jeruk di dapur, lalu <em>menyerahkan gelas jus jeruk itu ke tangan Anda</em> (return). Anda bebas meminumnya, mencampurnya dengan es, atau menyimpannya di ransel.\n        <br>- <strong>Fungsi hanya dengan print():</strong> Koki memeras jeruk di dapur, lalu ia meminumnya sendiri sambil berteriak: <em>\"Jusnya manis!\"</em> (print). Anda sebagai pelanggan tidak mendapatkan apa-apa di tangan Anda!\n        <br>Itulah perbedaan mutlak antara mencetak ke layar (print) vs mengembalikan nilai (return)!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Mengapa return Sangat Penting?\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><code>return</code> mengirimkan nilai hasil perhitungan kembali ke baris pemanggil, sehingga hasilnya bisa <strong>disimpan di variabel</strong> atau <strong>dihitung lebih lanjut</strong> dalam rumus lain.</li>\n            <li>Saat interpreter menemukan perintah <code>return</code>, eksekusi fungsi <strong>segera berhenti</strong> saat itu juga (perintah di bawah return tidak akan dijalankan).</li>\n            <li>Jika sebuah fungsi tidak memiliki kata kunci <code>return</code>, fungsi tersebut secara diam-diam mengembalikan nilai <code>None</code>!</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># FUNGSI A (Pakai return): Nilainya bisa diolah lagi\ndef hitung_diskon(harga, persen):\n    potongan = harga * (persen / 100)\n    return potongan # Mengembalikan angka potongan\n\n# FUNGSI B (Hanya print): Nilainya hilang di layar\ndef cetak_salam(nama):\n    print(f\"Selamat pagi, {nama}\")\n    # Tidak ada return, mengembalikan None otomatis\n\n# Menggunakan hasil return untuk perhitungan total bayar\nharga_baju = 150000\ndiskon_didapat = hitung_diskon(harga_baju, 20) # 30000\ntotal_bayar = harga_baju - diskon_didapat\n\nprint(f\"Harga Asli : Rp {harga_baju:,}\")\nprint(f\"Diskon     : Rp {diskon_didapat:,}\")\nprint(f\"Bayar      : Rp {total_bayar:,}\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Mengoperasikan Hasil print()\n        </div>\n        <p>Jika fungsi Anda hanya menggunakan <code>print()</code> dan Anda mencoba menjumlahkannya:\n        <br><code class=\"text-rose-900 bg-rose-100 p-1 rounded font-mono text-xs\">hasil = fungsi_print() + 10</code>\n        <br>Python akan meledak dengan error: <code>TypeError: unsupported operand type(s) for +: \'NoneType\' and \'int\'</code>. Ingat: fungsi tanpa return bernilai None!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Aturan praktis: jika tujuannya menghitung sesuatu, selalu gunakan <code>return</code>. Gunakan <code>print()</code> hanya saat ingin menampilkan tulisan visual ke layar pengguna.</p>\n        </div>\n    </div>\n</div>', 'def hitung_diskon(total, persen):\n    return total * (persen / 100)\n\npotongan = hitung_diskon(100000, 10)\nprint(\"Potongan:\", potongan)', 2, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (27, 'Apakah yang dikembalikan (return value) secara otomatis oleh sebuah fungsi Python jika di dalamnya sama sekali tidak ada kata kunci return?', 'Angka 0', 'Teks string kosong \"\"', 'Nilai None', 'Nilai False', 'C', 'Di Python, fungsi apa pun yang tidak mengeksekusi pernyataan return secara eksplisit akan otomatis mengembalikan objek None.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (27, 'Perhatikan program berikut:\ndef kali_dua(n):\n    return n * 2\n\ntotal = kali_dua(5) + kali_dua(3)\nprint(total)\nBerapakah output yang dicetak?', '16', '10', '8', 'TypeError', 'A', 'kali_dua(5) mengembalikan 10. kali_dua(3) mengembalikan 6. total = 10 + 6 = 16.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (27, 'Seorang murid membuat fungsi:\ndef tambah(a, b):\n    print(a + b)\n\nx = tambah(4, 6)\ny = x * 2\nMengapa pada baris \'y = x * 2\' terjadi TypeError: unsupported operand type for *: \'NoneType\' and \'int\'?', 'Karena x bernilai None, sebab fungsi tambah hanya menggunakan print() dan lupa mengembalikan nilai dengan return', 'Karena angka 4 dan 6 adalah integer', 'Karena perkalian dengan 2 dilarang', 'Karena fungsi tambah harus memiliki 3 parameter', 'A', 'Karena fungsi tambah hanya memanggil print(a+b) tanpa return, pemanggilan fungsi menghasilkan None. Mengalikan None dengan angka 2 memicu TypeError.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (27, 'Tantangan 6.2: Fungsi Luas Persegi Panjang', 'Buat fungsi bernama luas_persegi(p, l) yang mengembalikan (return) p * l. Panggil fungsi tersebut dengan nilai 8 dan 5, lalu cetak hasilnya:\nLuas: 40', 'def luas_persegi(p, l):\n    return p * l\n\nprint(f\"Luas: {luas_persegi(8, 5)}\")', '[{\"name\": \"Cek Luas 8 x 5\", \"expected_output\": \"Luas: 40\"}]', 'Gunakan return p * l', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (28, 6, '6.3', '6.3 Debugging: Variabel Lokal vs Global', '6-3-debugging-scope-variabel', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Buku Catatan Pribadi di Kamar vs Mading Sekolah\n        </div>\n        <p>Bayangkan dua papan tulis:\n        <br>- <strong>Variabel Lokal:</strong> Papan tulis kecil di dalam kamar tidur pribadi Anda (di dalam fungsi). Orang luar dari koridor tidak bisa melihat apalagi membaca isi papan itu. Begitu kamar dibongkar, tulisan papan itu hilang.\n        <br>- <strong>Variabel Global:</strong> Majalah Dinding (Mading) besar di lobi utama sekolah (di luar fungsi). Seluruh siswa dan guru di sekolah dapat melihat dan membaca isinya dari mana saja.\n        <br>Inilah konsep <strong>Scope (Lingkup Variabel)</strong> dalam rekayasa perangkat lunak!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Aturan Cakupan Variabel (Scope)\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Variabel Lokal:</strong> Dideklarasikan di dalam blok fungsi. Hanya hidup selama fungsi dieksekusi, dan HANYA bisa diakses dari dalam fungsi itu sendiri.</li>\n            <li><strong>Variabel Global:</strong> Dideklarasikan di luar fungsi (di file utama). Dapat dibaca oleh semua fungsi.</li>\n            <li>Jika ingin memodifikasi variabel global dari DALAM fungsi, Python mewajibkan deklarasi <code>global nama_variabel</code>. Namun, best practice merekomendasikan melewatkan data via parameter dan return alih-alih mengubah variabel global secara liar!</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Variabel Global (Bisa dibaca dari mana saja)\nsekolah = \"SMK Wikrama 1 Garut\"\n\ndef tampilkan_info_siswa():\n    # Variabel Lokal (Hanya ada di dalam fungsi ini)\n    nama = \"Ahmad Fadhil\"\n    kelas = \"X PPLG\"\n    print(f\"Siswa : {nama} ({kelas})\")\n    print(f\"Asal  : {sekolah}\") # Membaca variabel global aman!\n\ntampilkan_info_siswa()\n\n# Mencoba mengakses variabel lokal dari luar:\n# print(nama) # ERROR! NameError: name \'nama\' is not defined</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: UnboundLocalError\n        </div>\n        <p>Jika Anda membaca dan mencoba mengubah variabel global di dalam fungsi tanpa kata kunci <code>global</code>:\n        <br><code class=\"text-rose-900 bg-rose-100 p-1 rounded font-mono text-xs\">UnboundLocalError: cannot access local variable \'skor\' where it is not associated with a value</code>\n        <br>Python berasumsi Anda ingin membuat variabel lokal baru karena ada penugasan (=), namun bingung karena nilainya dibaca sebelum diisi.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Selalu kirim data ke dalam fungsi melalui <strong>parameter</strong>, dan bawa data keluar melalui <strong>return</strong>. Cara ini 100% aman dan membuat kode mudah dites di layar ponsel.</p>\n        </div>\n    </div>\n</div>', '# Variabel global\nbonus = 5000\n\ndef hitung_gaji(pokok):\n    # bonus bisa dibaca dari global\n    return pokok + bonus\n\nprint(\"Gaji:\", hitung_gaji(50000))', 3, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (28, 'Di manakah variabel lokal dapat diakses di dalam program Python?', 'Di seluruh file dari baris mana pun', 'Hanya di dalam blok fungsi tempat variabel tersebut dideklarasikan', 'Hanya setelah perintah return', 'Hanya oleh fungsi yang memiliki kata kunci global', 'B', 'Variabel lokal memiliki ruang lingkup terbatas (local scope) hanya di dalam blok fungsi tempat ia diciptakan.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (28, 'Perhatikan program berikut:\nx = 10\n\ndef ubah():\n    x = 20\n    print(\"Dalam fungsi:\", x)\n\nubah()\nprint(\"Luar fungsi:\", x)\nBerapakah nilai x yang dicetak di \'Luar fungsi\'?', '20', '10', 'None', 'Error: UnboundLocalError', 'B', 'Baris x = 20 di dalam fungsi membuat variabel lokal x yang terpisah dari variabel global x. Di luar fungsi, nilai x global tetap 10.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (28, 'Mengapa pemanggilan print(nama) di luar fungsi memicu NameError pada kode berikut?\ndef daftar():\n    nama = \"Wikrama\"\n\ndaftar()\nprint(nama)', 'Karena fungsi daftar belum selesai dieksekusi', 'Karena variabel nama adalah variabel lokal yang telah dihancurkan dari memori setelah fungsi daftar() selesai berjalan', 'Karena nama variabel tidak boleh bertipe string', 'Karena fungsi tidak memiliki parameter', 'B', 'Variabel lokal hanya hidup selama eksekusi fungsi berlangsung. Di luar fungsi, identifier nama tidak dikenal oleh interpreter.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (28, 'Tantangan 6.3: Perbaiki Akses Nilai Fungsi', 'Perbaiki kode agar fungsi mengembalikan total harga (harga + ongkir) dan dicetak di luar fungsi:\nTotal: 25000', 'def hitung_total():\n    harga = 20000\n    ongkir = 5000\n    return harga + ongkir\n\nprint(f\"Total: {hitung_total()}\")', '[{\"name\": \"Cek Total 25000\", \"expected_output\": \"Total: 25000\"}]', 'Kembalikan harga + ongkir dengan return', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (29, 6, '6.4', '6.4 Default Arguments & Multiple Returns', '6-4-default-args-multiple-returns', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Paket Makanan Cepat Saji dengan Minuman Default\n        </div>\n        <p>Bayangkan Anda memesan paket nasi ayam di kasir:\n        <br>- Jika Anda tidak menyebutkan minuman, kasir otomatis memberi Anda <strong>Es Teh Manis</strong> (Nilai Default).\n        <br>- Tetapi jika Anda minta khusus: <em>\"Minumnya ganti Jus Mangga ya!\"</em>, kasir akan menggantinya sesuai permintaan Anda.\n        <br>- Dan saat pesanan jadi, nampan kasir mengembalikan dua piring sekaligus: <strong>[Ayam, Jus Mangga]</strong> (Multiple Return!).\n        <br>Python mendukung kedua fitur hebat ini secara elegan!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Aturan Default Argument &amp; Multiple Return\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Default Arguments:</strong> Memberikan nilai cadangan pada parameter fungsi menggunakan tanda sama dengan (misal <code>diskon=0.05</code>). Parameter ini menjadi opsional saat dipanggil.</li>\n            <li><strong>Aturan Posisi:</strong> Parameter default WAJIB diletakkan di posisi paling belakang setelah parameter wajib!</li>\n            <li><strong>Multiple Returns:</strong> Fungsi Python dapat mengembalikan banyak nilai sekaligus dipisahkan tanda koma: <code>return nilai1, nilai2</code> (dikembalikan dalam bentuk Tuple).</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata: Analisis Bangun Datar\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Fungsi dengan default argument (satuan default \"cm\")\n# dan multiple returns (mengembalikan luas dan keliling sekaligus)\ndef hitung_persegi_panjang(panjang, lebar, satuan=\"cm\"):\n    luas = panjang * lebar\n    keliling = 2 * (panjang + lebar)\n    return luas, keliling, satuan\n\n# Memanggil dengan nilai default (satuan otomatis \"cm\")\nl1, k1, s1 = hitung_persegi_panjang(10, 5)\nprint(f\"Persegi A : Luas = {l1} {s1}², Keliling = {k1} {s1}\")\n\n# Memanggil dengan mengubah default menjadi \"meter\"\nl2, k2, s2 = hitung_persegi_panjang(8, 4, satuan=\"meter\")\nprint(f\"Persegi B : Luas = {l2} {s2}², Keliling = {k2} {s2}\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Menaruh Parameter Default di Depan\n        </div>\n        <p>Jangan pernah menulis parameter yang memiliki default value sebelum parameter biasa:\n        <br><code class=\"text-rose-900 bg-rose-100 p-1 rounded font-mono text-xs\">def hitung(diskon=0.1, harga): # SALAH BESAR!</code>\n        <br>Python akan memunculkan <code>SyntaxError: non-default argument \'harga\' follows default argument</code>.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Teknik unpacking: <code>a, b = fungsi()</code> memungkinkan Anda menangkap hasil multiple return langsung ke dua variabel terpisah hanya dalam 1 baris kode praktis.</p>\n        </div>\n    </div>\n</div>', 'def hitung_pajak(harga, persen=10):\n    return harga * (persen / 100)\n\nprint(\"Pajak default:\", hitung_pajak(100000))\nprint(\"Pajak khusus :\", hitung_pajak(100000, 5))', 4, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (29, 'Di manakah parameter yang memiliki nilai bawaan (default argument) WAJIB diletakkan pada deklarasi fungsi?', 'Di urutan paling depan sebelum parameter lain', 'Di urutan paling belakang setelah semua parameter tanpa nilai default', 'Bebas di posisi mana saja', 'Di luar tanda kurung', 'B', 'Aturan sintaks Python menetapkan bahwa non-default arguments tidak boleh mengikuti default arguments. Jadi default arguments selalu di posisi belakang.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (29, 'Perhatikan fungsi berikut:\ndef hitung_skor(poin, bonus=10):\n    return poin + bonus\n\nprint(hitung_skor(50))\nprint(hitung_skor(50, 25))\nApakah dua angka output yang dicetak?', '50 dan 75', '60 dan 75', '60 dan 60', 'TypeError', 'B', 'Pemanggilan pertama menggunakan bonus default (10) sehingga 50 + 10 = 60. Pemanggilan kedua mengganti bonus menjadi 25 sehingga 50 + 25 = 75.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (29, 'Mengapa deklarasi fungsi berikut memicu SyntaxError saat kode diperiksa interpreter?\ndef buat_pesanan(diskon=0.05, menu, jumlah):\n    pass', 'Karena ada kata kunci pass di dalamnya', 'Karena parameter default \'diskon=0.05\' diletakkan di depan parameter non-default \'menu\' dan \'jumlah\'', 'Karena nama fungsi mengandung underscore', 'Karena nilai 0.05 berupa pecahan float', 'B', 'SyntaxError: non-default argument follows default argument muncul karena parameter wajib (menu dan jumlah) ditulis setelah parameter default (diskon).', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (29, 'Tantangan 6.4: Fungsi Konversi Detik ke Menit', 'Buat fungsi bernama detik_ke_menit(detik) yang mengembalikan 2 nilai (tuple): menit dan sisa detik (detik // 60, detik % 60). Panggil dengan argumen 130, cetak: \"Menit: 2, Detik: 10\".', 'def detik_ke_menit(d):\n    return d // 60, d % 60\n\nm, s = detik_ke_menit(130)\nprint(f\"Menit: {m}, Detik: {s}\")', '[{\"name\": \"Cek 130 detik\", \"expected_output\": \"Menit: 2, Detik: 10\"}]', 'return d // 60, d % 60', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (30, 6, '6.5', '6.5 Boss Challenge: Sistem Kasir Kafe Modular', '6-5-boss-challenge-kasir-modular', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-trophy text-amber-600\"></i> 1. Uji Kompetensi Part 6: Arsitektur Kasir Berbasis Modul Fungsi\n        </div>\n        <p>Di Boss Challenge kali ini, Anda ditantang menyusun program kasir kafe modern dengan standar arsitektur profesional. Tidak boleh ada perhitungan yang menumpuk di file utama! Seluruh logika harus dipecah menjadi fungsi-fungsi modular yang independen dan mudah diuji.</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Rancangan Struktur Fungsi Modular\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1 mt-2 text-slate-600\">\n            <li><code>hitung_subtotal(harga, jumlah)</code>: Menghitung total kotor pesanan.</li>\n            <li><code>hitung_diskon(subtotal, kode_promo=\"\")</code>: Jika kode_promo == \"WIKRAMA10\", beri diskon 10%. Jika tidak, diskon 0.</li>\n            <li><code>hitung_pajak(setelah_diskon, tarif_pajak=0.10)</code>: Menghitung pajak PB1 restoran (default 10%).</li>\n            <li><code>cetak_struk_modular(...)</code>: Menerima seluruh angka hasil dan mencetak invoice rapi.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Solusi\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># 1. Modul Kalkulasi Subtotal\ndef hitung_subtotal(harga, jumlah):\n    return harga * jumlah\n\n# 2. Modul Evaluasi Diskon Member\ndef hitung_diskon(subtotal, kode_promo=\"\"):\n    if kode_promo.upper() == \"WIKRAMA10\":\n        return subtotal * 0.10\n    return 0\n\n# 3. Modul Pajak Restoran (Default 10%)\ndef hitung_pajak(dasar_pengenaan, tarif=0.10):\n    return dasar_pengenaan * tarif\n\n# 4. Modul Format Struk\ndef cetak_struk(menu, qty, subtotal, diskon, pajak, total_akhir):\n    print(\"=\" * 36)\n    print(\"       KAFE KELAS INDUSTRI       \")\n    print(\"=\" * 36)\n    print(f\"Item Pesanan : {menu}\")\n    print(f\"Jumlah       : {qty} porsi\")\n    print(f\"Subtotal     : Rp {subtotal:,}\")\n    print(f\"Diskon Promo : Rp {int(diskon):,}\")\n    print(f\"Pajak Resto  : Rp {int(pajak):,}\")\n    print(\"-\" * 36)\n    print(f\"TOTAL AKHIR  : Rp {int(total_akhir):,}\")\n    print(\"=\" * 36)\n\n# === ALUR PROGRAM UTAMA ===\nitem = \"Kopi Susu Senja\"\nharga_satuan = 25000\njumlah_beli = 4\npromo = \"WIKRAMA10\"\n\n# Memanggil modul secara berurutan\nsub = hitung_subtotal(harga_satuan, jumlah_beli) # 100.000\ndisk = hitung_diskon(sub, promo)                 # 10.000\ndpp = sub - disk                                 # 90.000\npjk = hitung_pajak(dpp)                          # 9.000\ntotal = dpp + pjk                                # 99.000\n\ncetak_struk(item, jumlah_beli, sub, disk, pjk, total)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Keunggulan Arsitektur Modular\n        </div>\n        <p>Jika besok pemerintah menaikkan pajak resto menjadi 11%, Anda cukup mengubah satu angka di parameter <code>tarif=0.11</code> pada fungsi <code>hitung_pajak()</code> tanpa perlu merombak ribuan baris kode program lainnya!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Gunakan penamaan fungsi yang jelas dengan kata kerja di depan (misal: <code>hitung_...</code>, <code>cetak_...</code>, <code>validasi_...</code>) agar kode sangat mudah dibaca.</p>\n        </div>\n    </div>\n</div>', 'def hitung_subtotal(harga, qty):\n    return harga * qty\n\ndef hitung_total_akhir(subtotal, diskon):\n    return int(subtotal - (subtotal * diskon / 100))\n\n# Ambil input dan cetak', 5, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (30, 'Apakah keuntungan terbesar menyusun kode sistem kasir dalam bentuk fungsi-fungsi modular dibandingkan menuliskannya dalam satu file panjang?', 'Program akan berjalan lebih cepat seribu kali', 'Kode lebih mudah dirawat, mudah diperbaiki jika ada bug pada rumus tertentu, dan fungsi dapat digunakan kembali di program lain (reusable)', 'Ukuran file menjadi nol kilobyte', 'Program tidak lagi membutuhkan interpreter Python', 'B', 'Prinsip modularitas membuat kode rapi, mudah di-debug secara parsial, dan dapat dipakai berulang kali tanpa duplikasi kode.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (30, 'Jika subtotal belanja adalah Rp 100.000, diskon Rp 10.000 (sisa Rp 90.000), dan tarif pajak adalah 10% dari sisa belanja setelah diskon, berapakah nilai total_akhir yang harus dibayar konsumen?', 'Rp 100.000', 'Rp 99.000', 'Rp 90.000', 'Rp 81.000', 'B', 'Dasar pengenaan pajak = 100.000 - 10.000 = 90.000. Pajak 10% = 9.000. Total akhir = 90.000 + 9.000 = Rp 99.000.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (30, 'Seorang programmer lupa menulis \'return\' pada fungsi hitung_diskon(). Apa akibat langsung yang terjadi pada variabel disk yang menampung pemanggilan fungsi tersebut?', 'disk akan bernilai 0', 'disk akan bernilai None, sehingga baris berikutnya yang melakukan pengurangan matematika (sub - disk) akan memicu TypeError', 'Program otomatis mengulang fungsi', 'disk akan bernilai True', 'B', 'Fungsi tanpa return mengembalikan None. Operasi matematika sub - None akan memicu TypeError: unsupported operand type for -: \'int\' and \'NoneType\'.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (30, 'Tantangan 6.5 (Boss): Kasir Modular Terintegrasi', 'Implementasikan kedua fungsi di atas. Input: baris 1 harga (10000), baris 2 qty (3), baris 3 diskon (10). Cetak:\nTotal Akhir: Rp 27000', 'def hitung_subtotal(harga, qty):\n    return harga * qty\n\ndef hitung_total_akhir(subtotal, diskon):\n    return int(subtotal - (subtotal * diskon / 100))\n\nh = int(input())\nq = int(input())\nd = int(input())\nsub = hitung_subtotal(h, q)\ntot = hitung_total_akhir(sub, d)\nprint(f\"Total Akhir: Rp {tot}\")', '[{\"name\": \"Uji Diskon 10%\", \"inputs\": [\"10000\", \"3\", \"10\"], \"expected_output\": \"Total Akhir: Rp 27000\"}]', 'sub = hitung_subtotal(h, q); tot = hitung_total_akhir(sub, d)', 50);
INSERT INTO modules (part_number, title, slug, description, badge_name, badge_icon, order_index) VALUES (7, 'File I/O & Penanganan Error', 'file-dan-error', 'Membaca dan menulis data ke file dengan open(), serta menangani exception dengan try-except.', 'File Guardian', 'fa-shield-halved', 7);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (31, 7, '7.1', '7.1 Penanganan Error: try & except', '7-1-try-except-error', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Sabuk Pengaman & Kantong Udara Mobil\n        </div>\n        <p>Saat Anda mengendarai mobil di jalan raya, Anda tidak bisa menjamin 100% tidak akan pernah ada lubang atau pengereman mendadak. Karena itu mobil dilengkapi sabuk pengaman dan airbag. Jika terjadi benturan, sistem pengaman aktif melindungi penumpang sehingga perjalanan tidak berakhir fatal. Di Python, blok <strong>try & except</strong> adalah airbag penyelamat agar aplikasi Anda tidak mendadak mati (crash) saat terjadi kesalahan input pengguna!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Mekanisme try &amp; except\n        </h4>\n        <p>Blok penanganan eksepsi (Exception Handling) bekerja dengan prinsip:</p>\n        <ol class=\"list-decimal pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><code>try:</code> Jalankan blok kode yang berisiko menimbulkan error (misalnya konversi input angka atau pembagian matematika).</li>\n            <li><code>except NamaError:</code> Jika error tersebut terjadi di dalam blok try, alihkan eksekusi ke blok ini untuk menampilkan pesan peringatan ramah tanpa mematikan program!</li>\n            <li><code>finally:</code> (Opsional) Blok yang SELALU dieksekusi baik saat program sukses maupun saat terjadi error.</li>\n        </ol>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata: Input Angka Anti-Crash\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>print(\"=== KALKULATOR PEMBAGIAN AMAN ===\")\n\ntry:\n    angka1 = float(input(\"Masukkan angka pembilang: \"))\n    angka2 = float(input(\"Masukkan angka penyebut : \"))\n    \n    hasil = angka1 / angka2\n    print(f\"Hasil Pembagian: {hasil:.2f}\")\n\nexcept ValueError:\n    print(\"[ERROR] Input tidak valid! Anda harus memasukkan angka, bukan huruf.\")\n\nexcept ZeroDivisionError:\n    print(\"[ERROR] Kesalahan fatal: Angka penyebut tidak boleh nol (0)!\")\n\nprint(\"Program selesai dengan aman tanpa crash.\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: \"Bare Except\" yang Terlalu Luas\n        </div>\n        <p>Jangan menuliskan <code>except:</code> kosong tanpa menyebutkan tipe errornya. Hal itu disebut <em>Bare Except</em> dan merupakan bad practice karena akan menangkap semua hal termasuk perintah penghentian keyboard (Ctrl+C), sehingga membuat kode sulit di-debug!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Kombinasikan perulangan <code>while True</code> dengan <code>try-except</code> untuk membuat input yang otomatis meminta pengguna mengetik ulang hingga inputnya benar.</p>\n        </div>\n    </div>\n</div>', 'try:\n    a = int(input())\n    print(100 // a)\nexcept ZeroDivisionError:\n    print(\"ERROR: NOL\")', 1, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (31, 'Apakah tujuan utama penggunaan blok try dan except dalam aplikasi Python modern?', 'Membuat kode berjalan lebih cepat secara otomatis', 'Menangkap dan menangani potensi kesalahan (runtime error) secara anggun agar program tidak berhenti mendadak (crash)', 'Mengubah tipe data string menjadi integer', 'Menyimpan kode ke database MySQL', 'B', 'try-except berfungsi sebagai jaring pengaman untuk menangkap runtime exception sehingga program tetap berjalan stabil.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (31, 'Perhatikan potongan kode berikut:\ntry:\n    x = int(\"seratus\")\n    print(\"Sukses\")\nexcept ValueError:\n    print(\"Tangkap Error\")\nApakah teks yang dicetak di terminal?', 'Sukses', 'Tangkap Error', 'ValueError: invalid literal', 'None', 'B', 'int(\"seratus\") memicu ValueError. Blok except ValueError langsung menangkapnya dan mencetak \"Tangkap Error\", baris print(\"Sukses\") dilewati.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (31, 'Tipe exception apakah yang harus ditangkap jika pengguna memasukkan angka 0 pada operasi pembagian (misal: 100 / 0)?', 'TypeError', 'IndexError', 'ZeroDivisionError', 'KeyError', 'C', 'Membagi angka dengan 0 di Python secara spesifik memicu ZeroDivisionError.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (31, 'Tantangan 7.1: Tangkal Pembagian dengan Nol', 'Input satu angka integer x. Coba hitung 50 // x. Jika terjadi ZeroDivisionError, cetak \"GAGAL: BAGI NOL\". Jika normal, cetak \"HASIL: <nilai>\".', 'try:\n    x = int(input())\n    print(f\"HASIL: {50 // x}\")\nexcept ZeroDivisionError:\n    print(\"GAGAL: BAGI NOL\")', '[{\"name\": \"Uji Normal 5\", \"inputs\": [\"5\"], \"expected_output\": \"HASIL: 10\"}, {\"name\": \"Uji Nol\", \"inputs\": [\"0\"], \"expected_output\": \"GAGAL: BAGI NOL\"}]', 'try: print(f\"HASIL: {50 // x}\") except ZeroDivisionError: print(\"GAGAL: BAGI NOL\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (32, 7, '7.2', '7.2 Menulis File: open() Mode w & a', '7-2-menulis-file-open', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Buku Catatan Fisik vs Whiteboard\n        </div>\n        <p>Bayangkan Anda mencatat di ruang kelas:\n        <br>- <strong>Mode \'w\' (Write / Overwrite):</strong> Seperti menghapus total seluruh tulisan di papan tulis whiteboard, lalu menulis kalimat baru di atas papan yang sudah bersih. Catatan kemarin hilang!\n        <br>- <strong>Mode \'a\' (Append):</strong> Seperti menulis di halaman buku harian. Anda tidak merobek halaman kemarin; Anda hanya menambahkan baris tulisan baru di baris paling bawah.\n        <br>Di Python, fungsi <code>open()</code> memungkinkan program Anda menyimpan data secara permanen ke dalam file fisik di media penyimpanan!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Standar Industri: Konteks Manajer \'with open\'\n        </h4>\n        <p>Jangan pernah membuka file dengan <code>f = open(...)</code> lalu lupa menutupnya dengan <code>f.close()</code>. Standar resmi Python menggunakan statement <strong>with</strong>:</p>\n        <pre class=\"bg-slate-900 text-slate-100 p-3 rounded-xl font-mono text-xs\"><code>with open(\"nama_file.txt\", \"mode\", encoding=\"utf-8\") as f:\n    f.write(\"Teks yang ingin disimpan\\n\")</code></pre>\n        <p class=\"mt-2 text-xs\">Blok <code>with</code> menjamin file akan ditutup secara otomatis oleh sistem operasi segera setelah blok selesai, bahkan jika terjadi error sekalipun!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata: Buku Log Presensi Kelas\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Mode \"a\" (Append): Menambahkan catatan tanpa menghapus data lama\nnama_siswa = \"Ahmad Fadhil\"\nstatus = \"Hadir Tepat Waktu\"\n\nwith open(\"presensi.txt\", \"a\", encoding=\"utf-8\") as file:\n    file.write(f\"Siswa: {nama_siswa} | Status: {status}\\n\")\n\nprint(\"Catatan presensi berhasil disimpan ke dalam file!\")\n\n# Membaca isi file yang baru saja ditulis\nprint(\"\\n=== ISI FILE PRESENSI.TXT ===\")\nwith open(\"presensi.txt\", \"r\", encoding=\"utf-8\") as file:\n    isi = file.read()\n    print(isi)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Bahaya: Salah Pakai Mode \'w\'\n        </div>\n        <p>Hati-hati! Jika Anda ingin menambahkan baris catatan baru pada buku kas atau presensi tetapi tidak sengaja menggunakan mode <code>\"w\"</code> (write), SELURUH isi file yang lama akan terhapus seketika tanpa peringatan konfirmasi. Selalu gunakan mode <code>\"a\"</code> untuk pencatatan log bertahap!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Ingat selalu menambahkan karakter baris baru <code>\\n</code> di ujung teks <code>f.write(\"...\\n\")</code> agar catatan berikutnya berpindah ke baris di bawahnya.</p>\n        </div>\n    </div>\n</div>', 'with open(\"agenda.txt\", \"w\") as f:\n    f.write(\"Belajar Python Bab 7\n\")\n\nprint(\"File berhasil disimpan!\")', 2, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (32, 'Mode apakah yang harus dipilih pada fungsi open() jika Anda ingin MENAMBAHKAN teks baru di akhir file tanpa menghapus data yang sudah ada sebelumnya?', '\"w\" (Write)', '\"a\" (Append)', '\"r\" (Read)', '\"x\" (Exclusive)', 'B', 'Mode \"a\" (append) membuka file untuk penulisan dengan menempatkan kursor di akhir file, sehingga data lama tetap utuh terjaga.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (32, 'Mengapa penggunaan pernyataan \'with open(...) as f:\' sangat dianjurkan daripada pemanggilan open() biasa?', 'Karena with open membuat teks otomatis terenkripsi', 'Karena pernyataan with menjamin file akan ditutup secara otomatis (auto-close) dengan aman meskipun terjadi runtime error', 'Karena with open tidak memerlukan harddisk', 'Karena fungsi f.write() hanya bekerja di dalam with', 'B', 'Context manager with open(...) menangani pembersihan resource file secara otomatis (memanggil f.close()) saat blok selesai.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (32, 'Apa yang terjadi jika Anda membuka file bernama \"catatan.txt\" yang sudah berisi 100 baris menggunakan mode open(\"catatan.txt\", \"w\")?', 'Teks baru akan ditambahkan di baris 101', 'Seluruh 100 baris isi file lama akan terhapus dan ditimpa dari awal', 'Python memicu FileExistsError', 'Program akan membaca file tersebut', 'B', 'Mode \"w\" (write) memotong (truncate) panjang file menjadi 0 bytes, sehingga seluruh konten sebelumnya terhapus permanen.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (32, 'Tantangan 7.2: Tulis dan Baca Kembali File', 'Tulis teks \"SUKSES TERSIMPAN\" ke dalam file bernama \"log.txt\". Lalu baca dan cetak isinya ke layar.', 'with open(\"log.txt\", \"w\") as f:\n    f.write(\"SUKSES TERSIMPAN\")\nwith open(\"log.txt\", \"r\") as f:\n    print(f.read())', '[{\"name\": \"Cek Baca Tulis File\", \"expected_output\": \"SUKSES TERSIMPAN\"}]', 'Gunakan with open(\"log.txt\", \"w\") lalu with open(\"log.txt\", \"r\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (33, 7, '7.3', '7.3 Debugging: Mengatasi FileNotFoundError', '7-3-debugging-file-not-found', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Mengambil Buku dari Rak yang Belum Pernah Dibeli\n        </div>\n        <p>Bayangkan Anda menyuruh adik Anda: <em>\"Tolong ambilkan novel Harry Potter jilid 8 di rak kamar!\"</em>. Adik Anda mencari ke seluruh sudut rak dan tidak menemukannya karena buku itu memang belum pernah Anda beli. Adik Anda akan berteriak: \"Bukunya tidak ada sama sekali!\". Di Python, situasi ini memicu <strong>FileNotFoundError: [Errno 2] No such file or directory</strong>!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Mengapa FileNotFoundError Terjadi?\n        </h4>\n        <p>Error ini terjadi ketika Anda mencoba membuka file dalam mode baca <code>\"r\"</code>, namun:</p>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li>File tersebut memang belum pernah dibuat sebelumnya.</li>\n            <li>Ada salah ketik (typo) pada nama file atau ekstensi (misal: <code>data.txt</code> diketik <code>dataa.txt</code>).</li>\n            <li>Nama file sensitif terhadap huruf besar dan kecil (case-sensitive) di Linux/Android/Hosting (misal: <code>Nilai.txt</code> vs <code>nilai.txt</code>).</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Cara Membaca File yang Kebal Error\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>nama_berkas = \"pengaturan.txt\"\n\n# Membaca dengan proteksi try-except FileNotFoundError\ntry:\n    with open(nama_berkas, \"r\", encoding=\"utf-8\") as f:\n        konten = f.read()\n        print(\"Isi Konfigurasi:\")\n        print(konten)\n\nexcept FileNotFoundError:\n    print(f\"[PERINGATAN] File {nama_berkas} belum ditemukan!\")\n    print(\"Membuat file konfigurasi baru dengan nilai default...\")\n    \n    # Otomatis buat file baru jika belum ada\n    with open(nama_berkas, \"w\", encoding=\"utf-8\") as f:\n        f.write(\"mode_gelap=True\\nukuran_font=14\\n\")\n    print(\"File baru berhasil dibuat otomatis!\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Perbedaan Mode \'r\' vs \'w\' Terhadap File yang Belum Ada\n        </div>\n        <p>Mode <code>\"w\"</code> dan <code>\"a\"</code> akan <strong>secara otomatis membuatkan file baru</strong> jika file yang diminta belum ada. Sebaliknya, mode <code>\"r\"</code> (read) <strong>WAJIB menuntut file sudah ada</strong> terlebih dahulu, atau ia akan memicu FileNotFoundError.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Selalu gunakan huruf kecil (lowercase) untuk penamaan file data seperti <code>data_siswa.txt</code> guna menghindari masalah perbedaan sistem operasi.</p>\n        </div>\n    </div>\n</div>', 'try:\n    with open(\"tidak_ada.txt\", \"r\") as f:\n        print(f.read())\nexcept FileNotFoundError:\n    print(\"STATUS: FILE KOSONG\")', 3, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (33, 'Kondisi manakah yang menyebabkan fungsi open(\"laporan.txt\", \"r\") memicu pesan FileNotFoundError?', 'Karena file laporan.txt berisi terlalu banyak teks', 'Karena file \"laporan.txt\" belum ada di direktori kerja yang ditentukan saat dibuka dalam mode baca (read)', 'Karena file laporan.txt bertipe teks', 'Karena mode \"r\" hanya untuk file gambar', 'B', 'Mode \"r\" mewajibkan file target sudah ada di storage. Jika tidak ditemukan, Python melempar FileNotFoundError.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (33, 'Perhatikan program berikut:\ntry:\n    with open(\"database_rahasia.txt\", \"r\") as f:\n        print(f.read())\nexcept FileNotFoundError:\n    print(\"Cadangan diaktifkan\")\nJika file database_rahasia.txt tidak ditemukan di disk, apakah yang tercetak?', 'Error fatal dan program crash', 'Cadangan diaktifkan', 'None', 'Isi file kosong', 'B', 'Blok except FileNotFoundError menangkap eksepsi ketiadaan file dan mengeksekusi print(\"Cadangan diaktifkan\") secara aman.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (33, 'Mode penulisan file manakah yang secara otomatis membuatkan file baru jika file yang dituju belum ada di penyimpanan?', 'Hanya mode \"r\"', 'Mode \"w\" dan mode \"a\"', 'Hanya mode \"rb\"', 'Tidak ada mode yang bisa membuat file baru otomatis', 'B', 'Baik mode \"w\" (write) maupun \"a\" (append) akan membuat file baru jika file dengan nama tersebut belum eksis di disk.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (33, 'Tantangan 7.3: Tangkal FileNotFoundError', 'Coba buka file bernama \"data_siswa.txt\" mode \"r\". Jika file tidak ditemukan (FileNotFoundError), cetak \"STATUS: DATA BELUM DIBUAT\".', 'try:\n    with open(\"data_siswa.txt\", \"r\") as f:\n        print(f.read())\nexcept FileNotFoundError:\n    print(\"STATUS: DATA BELUM DIBUAT\")', '[{\"name\": \"Cek Tangkal File Hilang\", \"expected_output\": \"STATUS: DATA BELUM DIBUAT\"}]', 'Gunakan blok try-except FileNotFoundError', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (34, 7, '7.4', '7.4 Modul Standar: math, random & datetime', '7-4-modul-standar-python', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Kotak Perkakas Tukang Serbaguna\n        </div>\n        <p>Seorang tukang kayu profesional yang ingin membangun rumah tidak perlu menambang bijih besi untuk membuat palu dan gergaji sendiri. Ia cukup membuka kotak perkakasnya, mengambil obeng dan meteran, lalu langsung bekerja. Filosofi Python dikenal dengan sebutan <strong>\"Batteries Included\"</strong>: Python sudah menyediakan ratusan modul bawaan siap pakai untuk matematika, angka acak, tanggal, dan internet tanpa perlu menginstal aplikasi pihak ketiga!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Tiga Modul Bawaan Paling Populer\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>import math:</strong> Fungsi matematika lanjutan: <code>math.sqrt(x)</code> (akar kuadrat), <code>math.ceil(x)</code> (pembulatan ke atas), <code>math.pi</code> (konstanta pi 3.14159...).</li>\n            <li><strong>import random:</strong> Generator angka & pilihan acak: <code>random.randint(1, 6)</code> (lempar dadu 1-6), <code>random.choice(list)</code> (memilih satu pemenang undian secara acak).</li>\n            <li><strong>import datetime:</strong> Mengambil tanggal, jam, menit, detik saat ini: <code>datetime.datetime.now()</code>.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata: Generator Kuis &amp; Struk\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>import math\nimport random\nimport datetime\n\n# 1. Matematika\nakar = math.sqrt(81)\nprint(f\"Akar kuadrat dari 81 adalah: {akar:.0f}\")\n\n# 2. Pengacakan (Simulasi Undian Juara Siswa)\nsiswa = [\"Fadhil\", \"Siti\", \"Budi\", \"Zahra\", \"Rian\"]\npemenang = random.choice(siswa)\ndadu = random.randint(1, 6)\nprint(f\"Pemenang undian hari ini: {pemenang} (Dadu #{dadu})\")\n\n# 3. Tanggal & Waktu Sekarang\nsekarang = datetime.datetime.now()\nformat_waktu = sekarang.strftime(\"%d-%m-%Y %H:%M:%S\")\nprint(f\"Waktu Transaksi : {format_waktu}\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error Fatal: \"Module Shadowing\"\n        </div>\n        <p>JANGAN PERNAH menamai file skrip Python Anda sama dengan nama modul bawaan, misalnya menamai file latihan Anda <code>random.py</code> atau <code>math.py</code>! Saat Anda menulis <code>import random</code>, Python akan mengimpor file latihan Anda sendiri alih-alih modul bawaan sistem, menyebabkan error <code>AttributeError: module has no attribute \'randint\'</code>.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Letakkan semua perintah <code>import ...</code> di baris paling atas dari file kode Anda agar mudah dibaca oleh programmer lain.</p>\n        </div>\n    </div>\n</div>', 'import math\nprint(\"Akar 49 :\", math.sqrt(49))\nprint(\"Nilai Pi:\", round(math.pi, 2))', 4, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (34, 'Fungsi modul bawaan manakah yang tepat digunakan untuk mensimulasikan lemparan dadu bernilai antara 1 sampai 6 secara acak?', 'math.random(1, 6)', 'random.randint(1, 6)', 'random.range(1, 6)', 'datetime.random(1, 6)', 'B', 'random.randint(a, b) menghasilkan bilangan bulat acak di mana kedua batas a dan b bersifat inklusif (termasuk 1 dan 6).', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (34, 'Perhatikan program berikut:\nimport math\nhasil = math.sqrt(64) + math.ceil(4.2)\nprint(hasil)\nBerapakah output yang dihasilkan?', '12.0', '13.0', '14.0', 'TypeError', 'B', 'math.sqrt(64) menghasilkan 8.0. math.ceil(4.2) membulatkan ke atas menjadi 5. Maka 8.0 + 5 = 13.0.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (34, 'Mengapa seorang siswa yang menamai file kodenya \'random.py\' mengalami AttributeError saat memanggil random.randint()?', 'Karena fungsi randint tidak ada di Python', 'Karena Python mengimpor file kodenya sendiri (Module Shadowing) alih-alih modul random asli bawaan pustaka standar Python', 'Karena modul random berbayar', 'Karena fungsi random hanya bisa diakses di sistem operasi Linux', 'B', 'Menamai file sama dengan nama modul standar menyebabkan Module Shadowing, di mana Python mengimpor file lokal tersebut sehingga fungsi standar tidak ditemukan.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (34, 'Tantangan 7.4: Menghitung Akar dengan math.sqrt', 'Ambil satu angka input float n (misal 64.0). Gunakan math.sqrt() untuk menghitung akarnya dan cetak:\nAkar: <nilai desimal>', 'import math\nn = float(input())\nprint(f\"Akar: {math.sqrt(n)}\")', '[{\"name\": \"Uji Akar 64\", \"inputs\": [\"64.0\"], \"expected_output\": \"Akar: 8.0\"}, {\"name\": \"Uji Akar 25\", \"inputs\": [\"25.0\"], \"expected_output\": \"Akar: 5.0\"}]', 'import math lalu print(f\"Akar: {math.sqrt(n)}\")', 40);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (35, 7, '7.5', '7.5 Boss Challenge: Catatan Transaksi Anti-Crash', '7-5-boss-challenge-catatan-file', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-trophy text-amber-600\"></i> 1. Uji Kompetensi Part 7: Black-Box Pencatat Transaksi\n        </div>\n        <p>Di Boss Challenge kali ini, Anda ditantang membuat sistem pencatatan transaksi kasir kelas industri yang memiliki ketahanan tinggi (robust). Program harus mampu menangani salah ketik pengguna tanpa crash, membangkitkan nomor resi unik acak, menyematkan tanggal transaksi, dan menyimpannya secara permanen ke file <code>transaksi.log</code> dengan mode append!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Kriteria Sistem\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1 mt-2 text-slate-600\">\n            <li>Input nominal harga wajib dilindungi <code>try-except ValueError</code>. Jika user mengetik huruf, minta input ulang.</li>\n            <li>Gunakan <code>random.randint(1000, 9999)</code> untuk membuat Nomor ID Transaksi.</li>\n            <li>Gunakan <code>datetime.datetime.now()</code> untuk mencatat stempel waktu real-time.</li>\n            <li>Simpan transaksi ke dalam file menggunakan <code>with open(\"transaksi.log\", \"a\")</code>.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Solusi\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>import random\nimport datetime\n\nprint(\"=== SISTEM TRANSAKSI ROBUST WIKRAMA ===\")\n\n# 1. Input Aman dengan Try-Except dalam Loop\nwhile True:\n    try:\n        nama_barang = input(\"Nama Barang : \").strip()\n        if not nama_barang:\n            print(\"[!] Nama barang tidak boleh kosong!\")\n            continue\n            \n        harga = int(input(\"Harga Satuan: Rp \"))\n        if harga <= 0:\n            print(\"[!] Harga harus lebih besar dari Rp 0!\")\n            continue\n            \n        break # Input valid, keluar dari loop\n    except ValueError:\n        print(\"[!] Error: Masukkan angka bulat yang sah untuk harga!\\n\")\n\n# 2. Generate Data Transaksi Otomatis\nid_transaksi = f\"TRX-{random.randint(1000, 9999)}\"\nwaktu = datetime.datetime.now().strftime(\"%Y-%m-%d %H:%M:%S\")\n\nbaris_log = f\"[{waktu}] ID: {id_transaksi} | Item: {nama_barang} | Total: Rp {harga:,}\\n\"\n\n# 3. Penyimpanan Permanen Anti-Data Loss\ntry:\n    with open(\"transaksi.log\", \"a\", encoding=\"utf-8\") as file:\n        file.write(baris_log)\n    print(\"\\n[SUKSES] Transaksi tersimpan ke transaksi.log\")\n    print(baris_log.strip())\nexcept Exception as e:\n    print(f\"[CRITICAL ERROR] Gagal menulis ke file: {e}\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Standar Aplikasi Produksi\n        </div>\n        <p>Aplikasi yang baik tidak pernah membiarkan pengguna melihat layar merah error sistem. Seluruh kemungkinan salah ketik dicegah dan ditangani dengan pesan instruktif.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Metode <code>.strip()</code> pada string berfungsi membuang spasi kosong tidak sengaja di awal atau akhir ketikan pengguna pada keyboard layar sentuh HP.</p>\n        </div>\n    </div>\n</div>', 'barang = input()\nharga = int(input())\n\nwith open(\"transaksi.txt\", \"w\") as f:\n    f.write(f\"{barang}: Rp {harga}\n\")\n\nprint(\"=== RIWAYAT TRANSAKSI ===\")\nwith open(\"transaksi.txt\", \"r\") as f:\n    print(f.read().strip())', 5, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (35, 'Mengapa perulangan while True yang dikombinasikan dengan try-except ValueError menjadi pola terbaik untuk validasi input angka di program kasir?', 'Karena menghapus semua data di memory', 'Karena jika pengguna salah mengetik huruf, program tidak mati dan dapat terus mengulang pertanyaan hingga pengguna memasukkan angka yang benar', 'Karena membuat kode otomatis tersambung ke printer struk', 'Karena memperkecil ukuran file log', 'B', 'Pola while True + try-except memastikan program tidak berhenti ketika terjadi ValueError, melainkan meminta input ulang sampai valid.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (35, 'Format kode apakah yang dihasilkan oleh f\"TRX-{random.randint(1000, 9999)}\" jika angka acak yang terpilih adalah 5821?', 'TRX-5821', 'TRX-{5821}', 'random-5821', '5821-TRX', 'A', 'Di dalam f-string ekspresi {random.randint(1000, 9999)} dievaluasi menjadi nilai angkanya (5821) sehingga menghasilkan teks \"TRX-5821\".', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (35, 'Apa fungsi dari method .strip() pada ekspresi nama_barang = input(\"...\").strip()?', 'Mengubah huruf kecil menjadi huruf besar', 'Menghapus spasi kosong berlebih di awal dan akhir teks input', 'Mengubah string menjadi angka', 'Menghapus file log', 'B', 'str.strip() menghapus whitespace (spasi, tab, newline) di bagian awal dan akhir string.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (35, 'Tantangan 7.5 (Boss): Log Transaksi Lengkap', 'Input baris 1 nama barang (misal \"Buku\"), baris 2 harga (15000). Simpan ke \"transaksi.txt\", lalu cetak:\n=== RIWAYAT TRANSAKSI ===\nBuku: Rp 15000', 'b = input()\nh = int(input())\nwith open(\"transaksi.txt\", \"w\") as f:\n    f.write(f\"{b}: Rp {h}\n\")\nprint(\"=== RIWAYAT TRANSAKSI ===\") \nwith open(\"transaksi.txt\", \"r\") as f:\n    print(f.read().strip())', '[{\"name\": \"Uji Catatan Buku\", \"inputs\": [\"Buku\", \"15000\"], \"expected_output\": \"=== RIWAYAT TRANSAKSI ===\nBuku: Rp 15000\"}]', 'Tulis ke file lalu baca kembali', 50);
INSERT INTO modules (part_number, title, slug, description, badge_name, badge_icon, order_index) VALUES (8, 'Proyek Akhir (Capstone Project)', 'proyek-akhir-capstone', 'Menggabungkan semua keahlian Python untuk membuat aplikasi utuh dan siap dinilai oleh Guru.', 'Python Junior Developer', 'fa-trophy', 8);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (36, 8, '8.1', '8.1 Panduan Arsitektur & Clean Code', '8-1-arsitektur-clean-code', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-lightbulb text-amber-600\"></i> 1. Analogi Dunia Nyata: Arsitektur Gedung Bertingkat vs Rumah Kardus\n        </div>\n        <p>Siapa pun bisa menumpuk kardus bekas menjadi gubuk mainan dalam 10 menit. Tetapi untuk membangun gedung sekolah berlantai 4 yang tahan gempa, Anda membutuhkan cetak biru arsitektur (blueprint), pembagian ruangan fungsional, dan saluran instalasi yang teratur. Di dunia industri software, <strong>Clean Code</strong> adalah pembeda antara programmer amatir dan insinyur perangkat lunak profesional!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Struktur Standar File Python Profesional\n        </h4>\n        <p>Urutan baku penyusunan file kode Python sesuai standar PEP 8:</p>\n        <ol class=\"list-decimal pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Dokumentasi &amp; Impor Modul:</strong> Docstring deskripsi program dan <code>import</code> pustaka di baris teratas.</li>\n            <li><strong>Konstanta Global:</strong> Variabel konfigurasi tetap dengan huruf kapital (misal: <code>PAJAK_RESTO = 0.10</code>).</li>\n            <li><strong>Definisi Fungsi-Fungsi:</strong> Setiap fungsi memiliki satu tugas spesifik (Single Responsibility Principle).</li>\n            <li><strong>Fungsi Utama main():</strong> Tempat orkestrasi alur aplikasi.</li>\n            <li><strong>Eksekusi Guard:</strong> Blok <code>if __name__ == \"__main__\":</code> di baris paling bawah.</li>\n        </ol>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Template Clean Code Python\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>\"\"\"\nAplikasi Manajemen Nilai Siswa\nDibuat oleh: Tim Pengembang Wikrama\n\"\"\"\nimport sys\n\n# Konstanta Konfigurasi\nNILAI_KKM = 75\nSEKOLAH = \"SMK Wikrama 1 Garut\"\n\ndef evaluasi_nilai(skor):\n    \"\"\"Menentukan apakah skor memenuhi batas KKM\"\"\"\n    return \"LULUS\" if skor >= NILAI_KKM else \"REMEDIAL\"\n\ndef main():\n    print(f\"=== SISTEM AKADEMIK {SEKOLAH} ===\")\n    nilai = 82\n    status = evaluasi_nilai(nilai)\n    print(f\"Siswa dengan nilai {nilai} dinyatakan: {status}\")\n\n# Guard Idiom: Hanya berjalan jika file ini dieksekusi langsung\nif __name__ == \"__main__\":\n    main()</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Bahaya \"Spaghetti Code\"\n        </div>\n        <p>Spaghetti code adalah sebutan untuk kode yang ditulis ratusan baris secara memanjang ke bawah tanpa menggunakan fungsi, mencampur input, logika bisnis, dan output dalam satu tumpukan rumit. Kode seperti ini sangat sulit diperbaiki saat ada bug dan mustahil dikerjakan secara tim!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Batasi panjang setiap fungsi maksimal 15-20 baris agar Anda dapat membaca satu fungsi utuh di layar ponsel tanpa harus scroll naik-turun berkali-kali.</p>\n        </div>\n    </div>\n</div>', 'def hitung_diskon(total):\n    \"\"\"Menghitung diskon 10% jika total belanja >= 50.000\"\"\"\n    if total >= 50000:\n        return total * 0.1\n    return 0', 1, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (36, 'Apakah fungsi dari blok pengaman \'if __name__ == \"__main__\":\' di baris paling bawah program Python?', 'Membuat kode dapat berjalan tanpa koneksi internet', 'Memastikan fungsi main() hanya dieksekusi saat file tersebut dijalankan secara langsung, bukan saat diimpor sebagai modul oleh file lain', 'Mengubah file menjadi format .exe', 'Menghapus variabel di memori', 'B', 'Guard idiom if __name__ == \"__main__\": membedakan eksekusi langsung (top-level script) dengan proses import oleh file eksternal.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (36, 'Berdasarkan konvensi Clean Code PEP 8, bagaimanakah penulisan nama variabel KONSTANTA (nilai tetap yang tidak boleh diubah)?', 'Huruf kecil bersambung (contoh: nilaikkm)', 'Semua huruf besar dengan garis bawah (contoh: NILAI_KKM)', 'CamelCase (contoh: nilaiKkm)', 'Diawali tanda dollar ($nilai_kkm)', 'B', 'Sesuai panduan gaya PEP 8 Python, konstanta didefinisikan menggunakan huruf kapital seluruhnya dengan pemisah underscore (UPPER_CASE).', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (36, 'Mengapa prinsip \"Single Responsibility\" (Satu fungsi hanya mengerjakan satu tugas spesifik) sangat ditekankan dalam Clean Code?', 'Agar fungsi lebih mudah dibaca, mudah diuji coba (testing), dan mudah digunakan kembali tanpa efek samping tak terduga', 'Agar ukuran file menjadi lebih besar', 'Karena Python melarang fungsi memiliki lebih dari 10 baris', 'Agar program tidak memerlukan variabel', 'A', 'Fungsi dengan tanggung jawab tunggal (single responsibility) jauh lebih modular, terhindar dari bug sampingan, dan mudah di-maintain.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (36, 'Tantangan 8.1: Uji Pemahaman Kode Bersih', 'Cetaklah tepat teks prinsip kode bersih:\nKODE BERSIH: RAPI, MODULAR, TERUJI', 'print(\"KODE BERSIH: RAPI, MODULAR, TERUJI\")', '[{\"name\": \"Cek Prinsip Clean Code\", \"expected_output\": \"KODE BERSIH: RAPI, MODULAR, TERUJI\"}]', 'print(\"KODE BERSIH: RAPI, MODULAR, TERUJI\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (37, 8, '8.2', '8.2 Jalur 1: Deep-Dive Game Teks Edukasi', '8-2-deep-dive-game-teks', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-gamepad text-amber-600\"></i> 1. Panduan Capstone Jalur 1: Game RPG Labirin Edukasi\n        </div>\n        <p>Di jalur ini, Anda membangun sebuah game petualangan berbasis teks interaktif (CLI RPG). Pemain mengendalikan seorang pahlawan siswa yang bertualang menjelajahi ruang bawah tanah komputer, memecahkan teka-teki logika pemrograman, bertarung melawan monster bug, dan mengumpulkan item ramuan kesehatan!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Arsitektur State Game\n        </h4>\n        <p>Status pahlawan dan monster dikelola menggunakan Dictionary:</p>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Pemain:</strong> <code>{\"nama\": \"Ksatria\", \"hp\": 100, \"attack\": 25, \"potion\": 2}</code></li>\n            <li><strong>Game Loop:</strong> Perulangan <code>while pemain[\"hp\"] &gt; 0 and monster[\"hp\"] &gt; 0:</code></li>\n            <li><strong>Pilihan Aksi Pemain:</strong> (1) Serang Monster, (2) Minum Ramuan (+30 HP), (3) Menyerah.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata Mini-RPG\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>import random\n\ndef main_game():\n    hero = {\"nama\": \"Ksatria Python\", \"hp\": 100, \"potion\": 2}\n    boss = {\"nama\": \"Monster SyntaxError\", \"hp\": 80}\n\n    print(f\"=== PERTARUNGAN DIMULAI: {hero[\'nama\']} vs {boss[\'nama\']} ===\")\n\n    while hero[\"hp\"] > 0 and boss[\"hp\"] > 0:\n        print(f\"\\nStatus: {hero[\'nama\']} (HP: {hero[\'hp\']}) | {boss[\'nama\']} (HP: {boss[\'hp\']})\")\n        print(\"Aksi: [1] Tebas Pedang  [2] Minum Ramuan (+30 HP)\")\n        pilihan = input(\"Pilih tindakan (1/2): \")\n\n        if pilihan == \"1\":\n            damage = random.randint(15, 30)\n            boss[\"hp\"] -= damage\n            print(f\"> Anda menebas {boss[\'nama\']} sebesar {damage} DMG!\")\n        elif pilihan == \"2\":\n            if hero[\"potion\"] > 0:\n                hero[\"hp\"] += 30\n                hero[\"potion\"] -= 1\n                print(f\"> Gluk gluk! HP Anda bertambah 30. Sisa ramuan: {hero[\'potion\']}\")\n            else:\n                print(\"> Ramuan Anda sudah habis!\")\n        else:\n            print(\"> Tindakan panik! Anda kehilangan giliran.\")\n\n        # Serangan balasan Monster jika masih hidup\n        if boss[\"hp\"] > 0:\n            serangan_boss = random.randint(10, 20)\n            hero[\"hp\"] -= serangan_boss\n            print(f\"> {boss[\'nama\']} menyerang balik sebesar {serangan_boss} DMG!\")\n\n    print(\"\\n\" + \"=\" * 35)\n    if hero[\"hp\"] > 0:\n        print(\"VICTORY! Anda berhasil menaklukkan Dungeon Bug!\")\n    else:\n        print(\"GAME OVER! Silakan perbaiki sintaks kode Anda.\")\n\nif __name__ == \"__main__\":\n    main_game()</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Monster Masih Menyerang Saat Sudah Mati\n        </div>\n        <p>Perhatikan baris <code>if boss[\"hp\"] &gt; 0:</code> sebelum serangan balasan boss. Jika pengecekan ini tidak ada, monster yang HP-nya sudah 0 akan tetap menyerang dan bisa membunuh pemain di ronde yang sama (Bug Zombie)!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Tambahkan karakter ASCII art sederhana seperti pedang <code>--===&gt;</code> atau bintang untuk membuat game teks Anda tampak keren di layar ponsel.</p>\n        </div>\n    </div>\n</div>', 'def mulai_game():\n    hp = 3\n    skor = 0\n    print(\"Game Teks Siap Dimulai!\")', 2, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (37, 'Struktur data apakah yang paling ideal untuk menyimpan status pahlawan game (nama, hp, attack, jumlah potion)?', 'Dictionary (Pasangan key-value)', 'String tunggal', 'Integer', 'List kosong', 'A', 'Dictionary memungkinkan pengaksesan atribut status pahlawan dengan nama yang jelas seperti hero[\"hp\"] atau hero[\"potion\"].', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (37, 'Jika HP awal Hero adalah 100 dan ia menerima serangan 3 kali masing-masing sebesar 22, 18, dan 25 poin kerusakan, berapakah sisa HP Hero?', '45', '35', '25', '0', 'B', 'Total serangan = 22 + 18 + 25 = 65. Sisa HP = 100 - 65 = 35.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (37, 'Mengapa pemeriksaan \'if boss[\"hp\"] > 0:\' penting dilakukan sebelum monster meluncurkan serangan balik?', 'Agar loop berjalan lebih cepat', 'Untuk mencegah monster yang telah mati (HP <= 0) tetap menyerang pemain pada giliran tersebut (Zombie Bug)', 'Agar pemain mendapat potion tambahan', 'Karena Python melarang nilai negatif pada integer', 'B', 'Pemeriksaan HP memastikan entitas yang sudah kehabisan darah tidak lagi dapat mengambil tindakan giliran.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (37, 'Tantangan 8.2: Mini Health Bar Game', 'Buat fungsi render_hp(hp) yang mengembalikan simbol hati \"â™¥ \" sebanyak jumlah hp. Jika hp = 3, kembalikan \"â™¥ â™¥ â™¥ \". Cetak: \"Darah: â™¥ â™¥ â™¥ \"', 'def render_hp(hp):\n    return (\"â™¥ \" * hp).strip()\n\nprint(f\"Darah: {render_hp(3)}\")', '[{\"name\": \"Cek Darah 3\", \"expected_output\": \"Darah: u2665 u2665 u2665\"}]', 'return (\"â™¥ \" * hp).strip()', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (38, 8, '8.3', '8.3 Jalur 2: Deep-Dive Kasir Toko & File Struk', '8-3-deep-dive-kasir-struk', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-cash-register text-amber-600\"></i> 1. Panduan Capstone Jalur 2: Sistem POS Toko &amp; Cetak Struk\n        </div>\n        <p>Di jalur ini, Anda membangun aplikasi kasir Point of Sale (POS) lengkap untuk Toko Ritel atau Kantin Siswa. Program memiliki menu katalog produk, keranjang transaksi multi-item, perhitungan diskon bertingkat, validasi uang tunai pembayaran, hingga ekspor struk resmi ke file teks permanen <code>struk.txt</code>!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Struktur Modul Aplikasi Kasir\n        </h4>\n        <ul class=\"list-disc pl-5 space-y-1.5 mt-2 text-slate-600\">\n            <li><strong>Katalog Produk:</strong> Dictionary daftar barang dan harga satuan.</li>\n            <li><strong>Keranjang Belanja:</strong> List of dictionaries yang mencatat nama item, kuantitas (qty), dan subtotal barang.</li>\n            <li><strong>Validasi Pembayaran:</strong> Jika uang tunai yang diberikan pembeli lebih kecil dari total tagihan, sistem menolak dan meminta kekurangan uang.</li>\n            <li><strong>File Struk:</strong> Menyimpan salinan invoice transaksi ke media penyimpanan dengan rapi.</li>\n        </ul>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>katalog = {\n    \"1\": {\"nama\": \"Buku Pemrograman Python\", \"harga\": 65000},\n    \"2\": {\"nama\": \"Flashdisk SanDisk 32GB\", \"harga\": 50000},\n    \"3\": {\"nama\": \"Mouse Wireless Logitech\", \"harga\": 85000}\n}\n\nkeranjang = []\n\nprint(\"=== KATALOG TOKO TEKNOLOGI WIKRAMA ===\")\nfor kode, barang in katalog.items():\n    print(f\"[{kode}] {barang[\'nama\']} - Rp {barang[\'harga\']:,}\")\n\n# Simulasi belanja 1 buku dan 1 mouse\nkeranjang.append({\"nama\": katalog[\"1\"][\"nama\"], \"qty\": 1, \"subtotal\": 65000})\nkeranjang.append({\"nama\": katalog[\"3\"][\"nama\"], \"qty\": 1, \"subtotal\": 85000})\n\ntotal_belanja = sum(item[\"subtotal\"] for item in keranjang)\nuang_bayar = 200000\nkembalian = uang_bayar - total_belanja\n\nprint(\"\\n\" + \"=\" * 36)\nprint(\"STRUK PEMBELIAN RESMI\")\nfor item in keranjang:\n    print(f\"{item[\'nama\']} x{item[\'qty\']} : Rp {item[\'subtotal\']:,}\")\nprint(\"-\" * 36)\nprint(f\"Total Belanja : Rp {total_belanja:,}\")\nprint(f\"Tunai         : Rp {uang_bayar:,}\")\nprint(f\"Kembalian     : Rp {kembalian:,}\")\nprint(\"=\" * 36)</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Pembayaran Kurang\n        </div>\n        <p>Pastikan ada pengecekan kondisi <code>if uang_bayar &lt; total_belanja:</code>. Kasir tidak boleh menyelesaikan transaksi dan mencetak kembalian bernilai negatif!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Format uang rupiah dengan f-string separator koma <code>{angka:,}</code> membuat tampilan struk langsung berstandar minimarket profesional.</p>\n        </div>\n    </div>\n</div>', 'menu = {\n    \"1\": {\"nama\": \"Kopi Susu\", \"harga\": 15000},\n    \"2\": {\"nama\": \"Roti Bakar\", \"harga\": 12000}\n}\nprint(\"Sistem Menu Siap\")', 3, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (38, 'Jika total transaksi belanja adalah Rp 145.000 dan pelanggan membayar dengan dua lembar uang seratus ribuan (Rp 200.000), berapakah uang kembalian yang harus diberikan kasir?', 'Rp 45.000', 'Rp 55.000', 'Rp 65.000', 'Rp 50.000', 'B', 'Kembalian = Uang Bayar - Total Belanja = 200.000 - 145.000 = Rp 55.000.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (38, 'Tindakan apakah yang harus diambil oleh sistem kasir jika uang_bayar lebih kecil daripada total_belanja?', 'Mencetak kembalian negatif dan menyelesaikan transaksi', 'Menolak penyelesaian transaksi, menampilkan pesan bahwa uang tunai kurang, dan meminta kekurangan pembayaran', 'Otomatis memberikan barang gratis', 'Menutup aplikasi paksa', 'B', 'Sistem kasir ritel wajib memvalidasi kecukupan pembayaran pembeli sebelum transaksi dinyatakan sah dan dicetak struknya.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (38, 'Manakah baris kode Python yang paling tepat untuk menghitung total akumulasi subtotal dari seluruh dictionary item di dalam keranjang belanja?', 'total = sum(item[\"subtotal\"] for item in keranjang)', 'total = keranjang.sum()', 'total = count(keranjang)', 'total = keranjang[\"subtotal\"]', 'A', 'List comprehension generator `sum(item[\"subtotal\"] for item in keranjang)` adalah cara standar dan paling efisien di Python untuk menjumlahkan nilai atribut list of dicts.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (38, 'Tantangan 8.3: Format Baris Struk Belanja', 'Diberikan nama = \"Kopi\", qty = 2, subtotal = 30000. Cetak tepat:\nSTRUK: 2x Kopi = Rp 30000', 'nama = \"Kopi\"\nqty = 2\nsubtotal = 30000\nprint(f\"STRUK: {qty}x {nama} = Rp {subtotal}\")', '[{\"name\": \"Cek Baris Struk\", \"expected_output\": \"STRUK: 2x Kopi = Rp 30000\"}]', 'print(f\"STRUK: {qty}x {nama} = Rp {subtotal}\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (39, 8, '8.4', '8.4 Jalur 3: Deep-Dive Buku Nilai Mini CLI', '8-4-deep-dive-buku-nilai-cli', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-graduation-cap text-amber-600\"></i> 1. Panduan Capstone Jalur 3: Aplikasi Rekap Nilai Siswa\n        </div>\n        <p>Di jalur ini, Anda membangun aplikasi buku nilai rombel kelas berbasis CLI dengan fitur CRUD (Create, Read, Update, Delete) lengkap. Pengguna (guru atau wali kelas) dapat menambah siswa baru, melihat seluruh daftar nilai dengan status KKM, mencari data siswa berdasarkan NIS unik, dan menghitung peringkat kelas!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-gears text-blue-600\"></i> 2. Pola Menu CLI Interaktif\n        </h4>\n        <p>Aplikasi dikelola menggunakan loop <code>while True</code> dengan menu pilihan bernomor:</p>\n        <pre class=\"bg-slate-900 text-slate-100 p-3 rounded-xl font-mono text-xs\"><code>while True:\n    print(\"[1] Lihat Daftar Nilai Siswa\")\n    print(\"[2] Tambah Data Siswa Baru\")\n    print(\"[3] Cari Siswa Berdasarkan NIS\")\n    print(\"[4] Keluar dari Aplikasi\")\n    pilihan = input(\"Pilih menu (1-4): \")</code></pre>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Bedah Contoh Kode Nyata\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code>data_siswa = [\n    {\"nis\": \"1001\", \"nama\": \"Ahmad Fadhil\", \"nilai\": 88.0},\n    {\"nis\": \"1002\", \"nama\": \"Siti Nurhaliza\", \"nilai\": 92.5},\n    {\"nis\": \"1003\", \"nama\": \"Budi Santoso\", \"nilai\": 71.0}\n]\n\ndef tampilkan_data():\n    print(\"\\n\" + \"=\" * 45)\n    print(f\"{\'NIS\':<6} {\'NAMA SISWA\':<20} {\'NILAI\':<8} {\'STATUS\'}\")\n    print(\"-\" * 45)\n    for s in data_siswa:\n        status = \"LULUS\" if s[\"nilai\"] >= 75 else \"REMEDIAL\"\n        print(f\"{s[\'nis\']:<6} {s[\'nama\']:<20} {s[\'nilai\']:<8.1f} {status}\")\n    print(\"=\" * 45)\n\ndef cari_siswa(nis_target):\n    for s in data_siswa:\n        if s[\"nis\"] == nis_target:\n            return s\n    return None\n\n# Contoh pemanggilan fungsi\ntampilkan_data()\nhasil_cari = cari_siswa(\"1002\")\nif hasil_cari:\n    print(f\"\\nDitemukan: {hasil_cari[\'nama\']} dengan nilai {hasil_cari[\'nilai\']}\")\nelse:\n    print(\"\\nSiswa tidak ditemukan!\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Jebakan Error: Duplikasi NIS\n        </div>\n        <p>Di sekolah, Nomor Induk Siswa (NIS) bersifat unik. Saat menambah siswa baru, selalu lakukan pemeriksaan apakah NIS tersebut sudah pernah terdaftar sebelumnya agar data tidak tertukar.</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Gunakan format string rata kiri <code>{teks:&lt;20}</code> untuk membuat tabel data di terminal tampak sangat lurus dan rapi seperti tabel Excel.</p>\n        </div>\n    </div>\n</div>', 'def hitung_kkm(nilai, kkm=75):\n    return \"LULUS\" if nilai >= kkm else \"REMEDIAL\"', 4, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (39, 'Apakah kepanjangan dari konsep dasar manajemen basis data CRUD dalam pengembangan software?', 'Create, Read, Update, Delete', 'Code, Run, Upgrade, Debug', 'Compile, Review, Undo, Deploy', 'Calculate, Return, Use, Divide', 'A', 'CRUD merupakan singkatan dari empat operasi dasar manipulasi data persisten: Create (Buat), Read (Baca), Update (Ubah), Delete (Hapus).', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (39, 'Jika KKM adalah 75, apakah status kelulusan untuk siswa bernama Budi Santoso yang memiliki nilai 71.0?', 'LULUS', 'REMEDIAL', 'DISPENSASI', 'None', 'B', 'Karena 71.0 lebih kecil dari batas KKM 75, maka status yang diberikan adalah REMEDIAL.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (39, 'Mengapa pencarian data siswa paling tepat dilakukan berdasarkan nomor unik NIS daripada menggunakan nama siswa?', 'Karena angka lebih mudah diketik', 'Karena kemungkinan ada siswa dengan nama panggilan yang sama (kembar), sedangkan NIS dijamin selalu unik untuk satu siswa', 'Karena fungsi pencarian Python hanya menerima integer', 'Agar ukuran memori lebih hemat', 'B', 'Primary identifier seperti NIS bersifat unik (unique identifier) sehingga menghilangkan ambiguitas jika ada siswa dengan nama serupa.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (39, 'Tantangan 8.4: Format Status Siswa Terformat', 'Diberikan nama = \"Farhan\", nilai = 82, status = \"LULUS\". Cetak:\n[HASIL] Farhan: 82 (LULUS)', 'nama = \"Farhan\"\nnilai = 82\nstatus = \"LULUS\"\nprint(f\"[HASIL] {nama}: {nilai} ({status})\")', '[{\"name\": \"Cek Format Hasil Siswa\", \"expected_output\": \"[HASIL] Farhan: 82 (LULUS)\"}]', 'print(f\"[HASIL] {nama}: {nilai} ({status})\")', 30);
INSERT INTO topics (id, module_id, sub_code, title, slug, content_html, starter_code, order_index, xp_reward) VALUES (40, 8, '8.5', '8.5 Boss Challenge: Deklarasi Pengumpulan Capstone', '8-5-boss-challenge-capstone-final', '<div class=\"space-y-4 text-xs sm:text-sm text-slate-700 leading-relaxed\">\n    <div class=\"p-4 bg-amber-50/80 border-l-4 border-amber-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-amber-900 flex items-center gap-2 mb-1.5 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-crown text-amber-600\"></i> 1. Puncak Kelulusan Siswa: Verifikasi Capstone Final\n        </div>\n        <p>SELAMAT! Anda telah tiba di garis akhir Akademi Python PyLMS SMK Wikrama 1 Garut. Ini adalah gerbang kelulusan di mana Anda memverifikasi proyek akhir Capstone Anda terhadap <strong>5 Pilar Kompetensi Rekayasa Perangkat Lunak</strong> sebelum dinyatakan kompeten dan siap terjun ke industri teknologi!</p>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-list-check text-blue-600\"></i> 2. Matriks 5 Pilar Penilaian Kelulusan\n        </h4>\n        <div class=\"overflow-x-auto\">\n            <table class=\"min-w-full text-xs border border-slate-200 rounded-xl overflow-hidden\">\n                <thead class=\"bg-slate-100 text-slate-800 font-bold\">\n                    <tr>\n                        <th class=\"p-2.5 text-left\">Pilar Kompetensi</th>\n                        <th class=\"p-2.5 text-left\">Implementasi Minimal Wajib</th>\n                    </tr>\n                </thead>\n                <tbody class=\"divide-y divide-slate-200 text-slate-700\">\n                    <tr>\n                        <td class=\"p-2 font-semibold\">1. Data &amp; Variabel</td>\n                        <td class=\"p-2\">Tipe data primitif (str, int, float, bool) terintegrasi rapi.</td>\n                    </tr>\n                    <tr>\n                        <td class=\"p-2 font-semibold\">2. Percabangan</td>\n                        <td class=\"p-2\">Pengambilan keputusan multi-cabang (<code>if-elif-else</code>) terarah.</td>\n                    </tr>\n                    <tr>\n                        <td class=\"p-2 font-semibold\">3. Perulangan</td>\n                        <td class=\"p-2\">Navigasi aplikasi berulang dengan <code>while</code> atau <code>for</code> loop.</td>\n                    </tr>\n                    <tr>\n                        <td class=\"p-2 font-semibold\">4. Koleksi Data</td>\n                        <td class=\"p-2\">Penyimpanan terstruktur memanfaatkan <code>List</code> atau <code>Dictionary</code>.</td>\n                    </tr>\n                    <tr>\n                        <td class=\"p-2 font-semibold\">5. Modularitas / I/O</td>\n                        <td class=\"p-2\">Pemecahan kode menggunakan fungsi (<code>def</code>) atau penyimpanan file teks (<code>open</code>).</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n\n    <div>\n        <h4 class=\"text-sm sm:text-base font-black text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-code text-indigo-600\"></i> 3. Program Evaluator Kelulusan Capstone\n        </h4>\n        <pre class=\"bg-slate-900 text-slate-100 p-4 rounded-2xl text-xs font-mono overflow-x-auto border border-slate-800 shadow-inner\"><code># Program Verifikator Capstone Otomatis\npilar_kompetensi = {\n    \"Variabel & Tipe Data\"   : True,\n    \"Percabangan Logika\"     : True,\n    \"Perulangan (Loop)\"      : True,\n    \"Struktur List/Dict\"     : True,\n    \"Fungsi Modular/File I/O\": True\n}\n\nskor = sum(1 for status in pilar_kompetensi.values() if status)\npersentase = (skor / len(pilar_kompetensi)) * 100\n\nprint(\"=== DEKLARASI KELULUSAN CAPSTONE PYTHON ===\")\nfor pilar, terpenuhi in pilar_kompetensi.items():\n    simbol = \"[V]\" if terpenuhi else \"[X]\"\n    print(f\"{simbol} {pilar}\")\n\nprint(\"-\" * 42)\nprint(f\"Kelengkapan Syarat : {skor}/5 Pilar ({persentase:.0f}%)\")\n\nif persentase == 100:\n    print(\"\\nSTATUS: DINYATAKAN LULUS KOMPETENSI REKAYASA PERANGKAT LUNAK!\")\n    print(\"Selamat atas kerja keras dan konsistensi Anda!\")\nelse:\n    print(\"\\nSTATUS: Masih ada pilar yang perlu disempurnakan.\")</code></pre>\n    </div>\n\n    <div class=\"p-4 bg-rose-50/80 border-l-4 border-rose-500 rounded-2xl text-slate-800 shadow-sm\">\n        <div class=\"font-black text-rose-900 flex items-center gap-2 mb-1 text-xs sm:text-sm\">\n            <i class=\"fa-solid fa-triangle-exclamation text-rose-600\"></i> 4. Pesan Integritas Akademik\n        </div>\n        <p>Kode yang hebat bukan kode yang disalin tanpa dipahami, melainkan baris kode yang Anda ketik, uji, dan pertahankan sendiri logikanya. Pertahankan kebiasaan menulis kode bersih dan jujur ini di dunia industri kelak!</p>\n    </div>\n\n    <div class=\"p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-emerald-950 flex items-center gap-3\">\n        <div class=\"w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center shrink-0\">\n            <i class=\"fa-solid fa-mobile-screen-button\"></i>\n        </div>\n        <div>\n            <span class=\"font-bold text-emerald-900 text-xs sm:text-sm\">Tips Coding HP:</span>\n            <p class=\"text-xs text-emerald-800 mt-0.5\">Anda dapat membagikan kode proyek Capstone Anda ke guru atau teman rombel melalui fitur Ekspor Kode di profil PyLMS!</p>\n        </div>\n    </div>\n</div>', 'print(\"STATUS: SELURUH MATERI PART 1-8 SELESAI\")\nprint(\"SIAP MENGUMPULKAN CAPSTONE PROJECT\")', 5, 25);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (40, 'Berapa banyak pilar kompetensi dasar rekayasa perangkat lunak yang wajib dipenuhi dalam sebuah proyek Capstone Python berkualitas?', '1 pilar', '3 pilar', '5 pilar utama (Variabel, Percabangan, Perulangan, Struktur Data, Modularitas/IO)', '100 pilar', 'C', 'Standar kurikulum menetapkan 5 pilar inti: Tipe Data/Variabel, Kontrol Percabangan, Kontrol Perulangan, Koleksi Struktur Data, dan Fungsi Modular/File I/O.', 15);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (40, 'Jika sebuah program Capstone siswa memenuhi kelima pilar kompetensi secara lengkap (5 dari 5 terpenuhi), berapakah persentase kelengkapan yang dicapai?', '80%', '90%', '100% (Kompeten Sempurna)', '50%', 'C', '(5 / 5) * 100 = 100%. Siswa telah menguasai seluruh spektrum materi kurikulum.', 20);
INSERT INTO quizzes (topic_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, xp_reward) VALUES (40, 'Sikap integritas profesional apakah yang paling berharga bagi seorang calon programmer muda saat menyelesaikan Capstone Project?', 'Menyalin seluruh proyek orang lain dari internet tanpa memahaminya', 'Menulis kode sendiri dengan pemahaman mendalam, mampu menjelaskan cara kerja baris per baris, dan jujur pada hasil uji coba', 'Menghapus komentar dokumentasi agar kode terlihat misterius', 'Menolak melakukan pengujian bug', 'B', 'Integritas akademik dan profesional diwujudkan dengan memahami kode yang ditulis sendiri serta siap mempertanggungjawabkannya di hadapan penguji.', 20);
INSERT INTO challenges (topic_id, title, instructions, starter_code, test_cases_json, hint, xp_reward) VALUES (40, 'Tantangan 8.5 (Boss): Deklarasi Kelulusan Lengkap', 'Cetak tepat 2 baris pernyataan kesiapan kelulusan:\nSTATUS: SELURUH MATERI SELESAI\nPROYEK AKHIR: SIAP DIREVIEW', 'print(\"STATUS: SELURUH MATERI SELESAI\")\nprint(\"PROYEK AKHIR: SIAP DIREVIEW\")', '[{\"name\": \"Cek Deklarasi Kelulusan\", \"expected_output\": \"STATUS: SELURUH MATERI SELESAI\\nPROYEK AKHIR: SIAP DIREVIEW\"}]', 'Cetak kedua baris persis seperti yang diminta.', 50);
